function getEnemyTapeCombatTuning(tapeId: EnemyTapeId): EnemyTapeCombatTuning {
  return ENEMY_TAPE_COMBAT_TUNING[tapeId];
}

function getNormalizedNoiseResponseLevel(level: number): number {
  return Math.max(0, Math.floor(level));
}

function formatNoiseResponseComposition(reinforcements: ReadonlyArray<EnemyArchetypeId>): string {
  if (reinforcements.length === 0) {
    return "no sweep bodies queued";
  }

  const counts = new Map<EnemyArchetypeId, number>();
  for (const archetypeId of reinforcements) {
    counts.set(archetypeId, (counts.get(archetypeId) ?? 0) + 1);
  }

  return [...counts.entries()]
    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
    .map(([archetypeId, count]) => `${count} ${SCAV_ARCHETYPES[archetypeId].name.toLowerCase()}${count === 1 ? "" : "s"}`)
    .join(" + ");
}

function getPendingNoiseResponseTier(route: RaidRouteDefinition, noiseResponseLevel: number) {
  return route.noiseResponseTiers[getNormalizedNoiseResponseLevel(noiseResponseLevel)] ?? null;
}

function getLastTriggeredNoiseResponseTier(route: RaidRouteDefinition, noiseResponseLevel: number) {
  const normalizedLevel = getNormalizedNoiseResponseLevel(noiseResponseLevel);
  return normalizedLevel > 0 ? route.noiseResponseTiers[normalizedLevel - 1] ?? null : null;
}

