const ROUTE_BUILDING_OCCUPATION_TARGETS: Record<
  RaidRouteId,
  {
    mustOwn: string[];
    guarded: string[];
  }
> = {
  "crosswind-docks": {
    mustOwn: ["Customs Block", "Container Yard", "Pier Trench Belt"],
    guarded: ["Greyline Pull Road"]
  },
  "broken-signal": {
    mustOwn: ["Dish Houses", "Uplink Yard", "Relay Cellar"],
    guarded: ["Antenna Ditch"]
  },
  "sundered-run": {
    mustOwn: ["Clinic Row", "Med Lane Trench", "Underpass Strongpoint"],
    guarded: ["Convoy Shell Yard"]
  }
};

const SUPPORT_STRONGPOINT_LABEL_PATTERN =
  /house|dish|shed|cellar|bunker|office|vault|room|relay|gate|slot|lift|mouth|yard|ridge|verge|lip/i;

function getRouteBuildingOccupationTier(routeId: RaidRouteId, label: string): BuildingOccupationTier {
  const targets = ROUTE_BUILDING_OCCUPATION_TARGETS[routeId];
  if (targets.mustOwn.includes(label)) {
    return "must-own";
  }
  if (targets.guarded.includes(label)) {
    return "guarded";
  }
  return "optional";
}

function getBuildingOccupationTierWeight(tier: BuildingOccupationTier): number {
  return tier === "must-own" ? 0 : tier === "guarded" ? 1 : 2;
}

function getStrongpointLaneLabel(label: string, placementKind: HostileSupportStrongpoint["placementKind"]): string {
  if (/gate|mouth|slot/i.test(label)) {
    return "gate mouth";
  }
  if (/yard|verge|lip|ridge|channel|court|spillway|duel/i.test(label)) {
    return "yard lip";
  }
  if (/trench|ditch|dugout/i.test(label)) {
    return "trench overlook";
  }
  if (/house|shed|cellar|bunker|office|vault|room|relay|lift|annex/i.test(label)) {
    return placementKind === "building" ? "window hold" : "lane hold";
  }
  return placementKind === "building" ? "window hold" : "lane hold";
}

function getStrongpointPriorityBoost(strongpoint: Pick<HostileSupportStrongpoint, "occupationTier" | "placementKind" | "label">): number {
  const tierBoost = strongpoint.occupationTier === "must-own" ? 0.9 : strongpoint.occupationTier === "guarded" ? 0.4 : 0;
  const laneBoost =
    /gate|mouth|slot|yard|verge|lip|ridge|channel|trench|ditch|dugout|relay|office|shed|house|bunker/i.test(strongpoint.label)
      ? 0.32
      : 0;
  const buildingBoost = strongpoint.placementKind === "building" ? 0.18 : 0;
  return tierBoost + laneBoost + buildingBoost;
}

function getStrongpointRoomClearDepthLabel(label: string, placementKind: HostileSupportStrongpoint["placementKind"]): string {
  if (placementKind !== "building") {
    return "Lane-owned pocket";
  }
  if (/cellar|lift|upper|tower|annex/i.test(label)) {
    return "Cellar plus upper chain";
  }
  if (/bunker|mouth|gate|vault/i.test(label)) {
    return "Bunker mouth plus rear pocket";
  }
  if (/relay|office|room/i.test(label)) {
    return "First room plus back room";
  }
  return "One-room hold";
}

export function getRouteBuildingOccupationEntries(
  route: RaidRouteDefinition,
  obstacles: ReadonlyArray<ArenaObstacle>
): RouteBuildingOccupationEntry[] {
  const obstacleEntries = obstacles
    .filter((obstacle) => {
      const label = obstacle.label ?? obstacle.breach?.label ?? "";
      if (!label || !obstacle.doorways || obstacle.doorways.length === 0) {
        return false;
      }
      if ((obstacle.breach?.label?.startsWith("Open room hold") ?? false) || (obstacle.breach?.label?.startsWith("Breach blockade") ?? false)) {
        return false;
      }
      return route.combatPockets.some((pocket) => {
        const center = { x: obstacle.x + obstacle.width / 2, y: obstacle.y + obstacle.height / 2 };
        return distance(center, pocket.position) <= Math.max(340, pocket.radius + 160);
      });
    })
    .map((obstacle) => {
      const label = obstacle.label ?? obstacle.breach?.label ?? "Unnamed structure";
      const position = { x: obstacle.x + obstacle.width / 2, y: obstacle.y + obstacle.height / 2 };
      const nearestPocket =
        route.combatPockets
          .map((pocket) => ({ pocket, distance: distance(position, pocket.position) }))
          .sort((left, right) => left.distance - right.distance)[0]?.pocket ?? null;
      const tier = getRouteBuildingOccupationTier(route.id, label);
      const placementKind =
        /house|shed|cellar|bunker|office|vault|room|relay|lift|annex|block|row|strongpoint/i.test(label)
          ? ("building" as const)
          : ("key-area" as const);
      return {
        label,
        tier,
        source: tier === "optional" ? ("fallback" as const) : ("authored" as const),
        nearestPocketLabel: nearestPocket?.label ?? null,
        position,
        placementKind,
        laneLabel: getStrongpointLaneLabel(label, placementKind),
        roomClearDepthLabel: getStrongpointRoomClearDepthLabel(label, placementKind)
      };
    });

  const syntheticEntries = TACTICAL_DISTRICT_BLUEPRINT.routes[route.id].subzones
    .filter((subzone) => getRouteBuildingOccupationTier(route.id, subzone.label) !== "optional")
    .map((subzone) => {
      const tier = getRouteBuildingOccupationTier(route.id, subzone.label);
      const placementKind =
        subzone.type === "town-block" || subzone.type === "bunker-chain" ? ("building" as const) : ("key-area" as const);
      const nearestPocket =
        route.combatPockets
          .map((pocket) => ({ pocket, distance: distance(subzone.anchor, pocket.position) }))
          .sort((left, right) => left.distance - right.distance)[0]?.pocket ?? null;
      return {
        label: subzone.label,
        tier,
        source: "authored" as const,
        nearestPocketLabel: nearestPocket?.label ?? null,
        position: { ...subzone.anchor },
        placementKind,
        laneLabel: getStrongpointLaneLabel(subzone.label, placementKind),
        roomClearDepthLabel: getStrongpointRoomClearDepthLabel(subzone.label, placementKind)
      };
    })
    .filter((entry) => !obstacleEntries.some((obstacle) => obstacle.label === entry.label));

  return obstacleEntries
    .concat(syntheticEntries)
    .sort((left, right) => {
      const tierWeight = (tier: BuildingOccupationTier): number =>
        tier === "must-own" ? 0 : tier === "guarded" ? 1 : 2;
      if (tierWeight(left.tier) !== tierWeight(right.tier)) {
        return tierWeight(left.tier) - tierWeight(right.tier);
      }
      return left.label.localeCompare(right.label);
    });
}

function getSupportStrongpointScore(anchor: Vec2, strongpoints: ReadonlyArray<HostileSupportStrongpoint>): number {
  if (strongpoints.length === 0) {
    return 0;
  }

  const nearestWeightedDistance = strongpoints.reduce(
    (best, strongpoint) => Math.min(best, distance(anchor, strongpoint.position) / Math.max(0.5, strongpoint.priority)),
    Number.POSITIVE_INFINITY
  );
  return clamp(3.6 - nearestWeightedDistance / 78, 0, 3.6);
}

function getNearestHostileStrongpoint(
  anchor: Vec2,
  strongpoints: ReadonlyArray<HostileSupportStrongpoint>,
  maxWeightedDistance = 180
): HostileSupportStrongpoint | null {
  let bestStrongpoint: HostileSupportStrongpoint | null = null;
  let bestWeightedDistance = Number.POSITIVE_INFINITY;

  for (const strongpoint of strongpoints) {
    const weightedDistance = distance(anchor, strongpoint.position) / Math.max(0.5, strongpoint.priority);
    if (weightedDistance < bestWeightedDistance) {
      bestWeightedDistance = weightedDistance;
      bestStrongpoint = strongpoint;
    }
  }

  return bestWeightedDistance <= maxWeightedDistance ? bestStrongpoint : null;
}

function getEnemyDoctrineState(
  squadRole: EnemySquadRole,
  openingPosture: EnemyOpeningPosture,
  strongpoint: HostileSupportStrongpoint | null
): EnemyDoctrineState {
  if (squadRole === "support-gunner") {
    return "cover-sector";
  }
  if (squadRole === "anchor-rifle") {
    return "hold-threshold";
  }
  if (squadRole === "deep-rifle") {
    return strongpoint?.placementKind === "building" ? "collapse-inside" : "hold-threshold";
  }
  return openingPosture === "hold" || openingPosture === "reserve" ? "probe-flank" : "probe-flank";
}

function getEnemyDoctrineWatchArc(doctrineState: EnemyDoctrineState): number {
  if (doctrineState === "cover-sector") {
    return 54;
  }
  if (doctrineState === "hold-threshold") {
    return 72;
  }
  if (doctrineState === "probe-flank") {
    return 112;
  }
  return 132;
}

function assignSquadsToStrongpoints(
  squadCentroids: ReadonlyArray<{ squadId: string; centroid: Vec2 }>,
  buildingStrongpoints: ReadonlyArray<HostileSupportStrongpoint>,
  fallbackStrongpoints: ReadonlyArray<HostileSupportStrongpoint>,
  reservedStrongpointsBySquadId: ReadonlyMap<string, HostileSupportStrongpoint> = new Map()
): Map<string, HostileSupportStrongpoint> {
  const assignments = new Map<string, HostileSupportStrongpoint>();
  reservedStrongpointsBySquadId.forEach((strongpoint, squadId) => {
    assignments.set(squadId, strongpoint);
  });
  const availableSquads = squadCentroids.filter((squad) => !assignments.has(squad.squadId));
  const reservedLabels = new Set([...reservedStrongpointsBySquadId.values()].map((strongpoint) => strongpoint.label));
  const prioritizedBuildings = [...buildingStrongpoints]
    .filter((strongpoint) => !reservedLabels.has(strongpoint.label))
    .sort((left, right) => right.priority - left.priority);

  for (const strongpoint of prioritizedBuildings) {
    if (availableSquads.length === 0) {
      break;
    }

    let bestIndex = 0;
    let bestScore = Number.POSITIVE_INFINITY;
    for (let index = 0; index < availableSquads.length; index += 1) {
      const candidate = availableSquads[index];
      const score = distance(candidate.centroid, strongpoint.position) / Math.max(0.5, strongpoint.priority);
      if (score < bestScore) {
        bestScore = score;
        bestIndex = index;
      }
    }

    const [assignedSquad] = availableSquads.splice(bestIndex, 1);
    if (assignedSquad) {
      assignments.set(assignedSquad.squadId, strongpoint);
    }
  }

  for (const squad of squadCentroids) {
    if (assignments.has(squad.squadId)) {
      continue;
    }
    const fallback = getNearestHostileStrongpoint(squad.centroid, fallbackStrongpoints, 190);
    if (fallback) {
      assignments.set(squad.squadId, fallback);
    }
  }

  return assignments;
}

