function isFrontlineRoomHoldObstacle(obstacle: ArenaObstacle): boolean {
  return obstacle.breach?.label.startsWith("Open room hold") ?? false;
}

function hasUsableDoorwayRouting(obstacle: ArenaObstacle): boolean {
  return (
    obstacle.doorways?.some((doorway) => doorway.width > 0.1 && (doorway.depth ?? 0) >= 0) ?? false
  );
}

function usesDoorwayPathRouting(obstacle: ArenaObstacle): boolean {
  return isFrontlineRoomHoldObstacle(obstacle) || hasUsableDoorwayRouting(obstacle);
}

function getFrontlineRoomHoldDepth(obstacle: ArenaObstacle): number {
  const match = obstacle.breach?.label.match(/Open room hold \d+\.(\d+)/);
  return match ? Number(match[1]) : 1;
}

function getFrontlineRoomHoldChainIndex(obstacle: ArenaObstacle): number | null {
  const match = obstacle.breach?.label.match(/Open room hold (\d+)\.\d+/);
  return match ? Number(match[1]) : null;
}

