const QUICK_INTEL_WINDOW_SECONDS = 45;
const EXTRACTION_HOLD_SECONDS = 60;
const EXTRACTION_HOLD_SLIP_PER_SECOND = 0.95;
const EXTRACTION_CONTEST_SLIP_PER_SECOND = 1.4;
