function getFocusedFrontlineIncidentForState(state: RaidState): FrontlineIncidentState | null {
  if (state.focusedFrontlineIncidentId === null) {
    return null;
  }

  return state.frontlineIncidents.find((incident) => incident.id === state.focusedFrontlineIncidentId && !incident.resolved) ?? null;
}

function isRecoveryDrivenRaidState(state: RaidState): boolean {
  const focusedIncident = getFocusedFrontlineIncidentForState(state);
  if (
    state.player.casualtyState === "downed" ||
    state.player.casualtyState === "dead" ||
    state.activeSquadBodyRecovery !== null ||
    state.activeRescueTask !== null
  ) {
    return true;
  }

  if (!focusedIncident) {
    return false;
  }

  return (
    focusedIncident.kind === "casualty" ||
    focusedIncident.actionVerb === "recover" ||
    focusedIncident.markerState === "bagged"
  );
}

function getFocusedExtractForState(state: RaidState): RaidExtractDefinition {
  return (
    (state.activeExtractId !== null ? state.extractZones.find((extract) => extract.id === state.activeExtractId) : null) ??
    state.extractZones[0] ?? {
      id: "fallback-extract",
      label: "Fallback extract",
      position: state.extractZone.position,
      radius: state.extractZone.radius,
      summary: "Fallback beacon."
    }
  );
}

function getClosestLabeledObstacleForState(state: RaidState, referencePoint: Vec2, radius: number): ArenaObstacle | null {
  let closestObstacle: ArenaObstacle | null = null;
  let closestDistance = radius;

  for (const obstacle of state.obstacles) {
    if (!obstacle.label) {
      continue;
    }

    const obstacleCenter = {
      x: obstacle.x + obstacle.width / 2,
      y: obstacle.y + obstacle.height / 2
    };
    const obstacleDistance = distance(referencePoint, obstacleCenter);
    if (obstacleDistance > closestDistance) {
      continue;
    }

    closestObstacle = obstacle;
    closestDistance = obstacleDistance;
  }

  return closestObstacle;
}

function getSupportOrderFocusLabel(state: RaidState, orderId: FrontlineSupportOrderId): string | null {
  if (orderId === "breach-push") {
    return getPriorityBreachObstacleForState(state)?.label ?? getPriorityBreachObstacleForState(state)?.breach?.label ?? null;
  }

  if (orderId === "hold-position") {
    return getSupportHoldAnchorForState(state).label;
  }

  if (orderId === "drop-ammo-crate") {
    return (
      getClosestLabeledObstacleForState(state, state.player.position, 180)?.label ??
      getFocusedFrontlineIncidentForState(state)?.label ??
      getSupportHoldAnchorForState(state).label
    );
  }

  if (orderId === "secure-exfil") {
    const focusedExtract = getFocusedExtractForState(state);
    const extractObstacle = getClosestLabeledObstacleForState(state, focusedExtract.position, focusedExtract.radius + 180);
    return extractObstacle?.label ?? focusedExtract.label;
  }

  if (orderId === "shift-fire") {
    const target = getSupportObjectiveTargetForState(state);
    return (
      getClosestLabeledObstacleForState(state, target, 220)?.label ??
      getFocusedFrontlineIncidentForState(state)?.label ??
      getClosestLabeledObstacleForState(state, state.player.position, 180)?.label ??
      null
    );
  }

  if (state.activeRouteId === "broken-signal") {
    return "Tree line";
  }

  return getFocusedFrontlineIncidentForState(state)?.label ?? null;
}

export function getFrontlineSupportOrderPresentation(
  state: RaidState,
  orderId: FrontlineSupportOrderId
): FrontlineSupportOrderPresentation {
  const base = FRONTLINE_SUPPORT_ORDERS[orderId];
  const focusLabel = getSupportOrderFocusLabel(state, orderId);

  if (orderId === "shift-fire") {
    if (focusLabel) {
      return {
        ...base,
        title: "Suppress Window",
        summary: `Tell the boys to own ${focusLabel.toLowerCase()} with hard lane fire so your next move lands under cover.`,
        effectSummary: `The wedge braces on ${focusLabel.toLowerCase()} and pins the lane through its openings.`,
        focusLabel
      };
    }

    return {
      ...base,
      title: "Suppress Window",
      summary: "Tell the boys to harden the nearest opening so your next move lands under cover instead of a naked peek.",
      effectSummary: "The wedge braces on the nearest opening and pins the lane through it.",
      focusLabel
    };
  }

  if (orderId === "draw-heat") {
    const openLaneLabel = focusLabel ?? "tree line";
    return {
      ...base,
      title: "Watch Tree Line",
      summary: `Send the boys wide on ${openLaneLabel.toLowerCase()} so hostile eyes drag off your true route.`,
      effectSummary: "The wedge opens a loud flank watch that muddies the route read and buys a cleaner move.",
      focusLabel
    };
  }

  if (orderId === "secure-exfil") {
    const lowerFocus = focusLabel?.toLowerCase() ?? null;
    if (focusLabel && /gate|slot|culvert|spur|lift|ferry|winch/i.test(focusLabel)) {
      return {
        ...base,
        title: "Hold Gate",
        summary: `Tell the boys to harden ${lowerFocus} so the pull reads like a real squad exit instead of a panic sprint.`,
        effectSummary: `The wedge anchors ${lowerFocus} and screens the collapse behind the pull.`,
        focusLabel
      };
    }

    if (focusLabel) {
      return {
        ...base,
        title: "Hold House",
        summary: `Tell the boys to turn ${lowerFocus} into a foothold so the peel has a real covered shoulder.`,
        effectSummary: `The wedge anchors ${lowerFocus} and screens the escape lane behind it.`,
        focusLabel
      };
    }

    return {
      ...base,
      title: "Hold House",
      summary: "Tell the boys to turn the chosen peel into a foothold before the route folds shut.",
      effectSummary: "The wedge anchors the peel and screens the collapse behind it.",
      focusLabel
    };
  }

  if (orderId === "hold-position") {
    const lowerFocus = focusLabel?.toLowerCase() ?? null;
    if (focusLabel && /house|shed|bunker|basement|block|compound|factory|village|relay/i.test(focusLabel)) {
      return {
        ...base,
        title: "Hold House",
        summary: `Tell the boys to dig into ${lowerFocus} and own the side angles before you widen the fight again.`,
        effectSummary: `The wedge anchors ${lowerFocus}, watches the flanks, and turns it into a real foothold.`,
        focusLabel
      };
    }

    return {
      ...base,
      title: "Hold Position",
      summary: focusLabel
        ? `Tell the boys to harden ${lowerFocus} and make the route come to you for one beat.`
        : "Tell the boys to harden the current shoulder and make the route come to you for one beat.",
      effectSummary: focusLabel
        ? `The wedge locks ${lowerFocus} and keeps the next push starting from cover.`
        : "The wedge locks the current shoulder and keeps the next push starting from cover.",
      focusLabel
    };
  }

  if (focusLabel) {
    return {
      ...base,
      title: "Clear House",
      summary: `Tell the boys to crash ${focusLabel.toLowerCase()} so the breach becomes a real shove under fire.`,
      effectSummary: `Friendly rifles stack on ${focusLabel.toLowerCase()} and surge through the opened cut.`,
      focusLabel
    };
  }

  return {
    ...base,
    focusLabel
  };
}

function getSupportObjectiveTargetForState(state: RaidState): Vec2 {
  const focusedIncident = getFocusedFrontlineIncidentForState(state);
  if (focusedIncident) {
    return focusedIncident.position;
  }

  const route =
    RAID_ROUTES.find((candidate) => candidate.id === state.activeRouteId) ??
    (RAID_ROUTES.length > 0 ? RAID_ROUTES[0] : null);
  if (!route) {
    return state.extractZone.position;
  }
  return route.combatPockets[0]?.position ?? state.extractZone.position;
}

function getSupportDecoyTargetForState(state: RaidState): Vec2 {
  const route =
    RAID_ROUTES.find((candidate) => candidate.id === state.activeRouteId) ??
    (RAID_ROUTES.length > 0 ? RAID_ROUTES[0] : null);
  if (!route) {
    return state.extractZone.position;
  }

  const farPocket = route.combatPockets[route.combatPockets.length - 1] ?? route.combatPockets[0];
  return state.extractionReady || state.extractionHoldTimer > 0 ? getFocusedExtractForState(state).position : farPocket?.position ?? state.extractZone.position;
}

function getSupportHoldAnchorForState(state: RaidState): {
  position: Vec2;
  label: string | null;
  obstacle: ArenaObstacle | null;
} {
  const focusedIncident = getFocusedFrontlineIncidentForState(state);
  const referencePoint = focusedIncident?.position ?? state.player.position;
  const nearbyObstacle = getClosestLabeledObstacleForState(state, referencePoint, 220);
  if (nearbyObstacle) {
    return {
      position: {
        x: nearbyObstacle.x + nearbyObstacle.width / 2,
        y: nearbyObstacle.y + nearbyObstacle.height / 2
      },
      label: nearbyObstacle.label ?? nearbyObstacle.breach?.label ?? focusedIncident?.label ?? null,
      obstacle: nearbyObstacle
    };
  }

  return {
    position: { ...(focusedIncident?.position ?? state.player.position) },
    label: focusedIncident?.label ?? getClosestLabeledObstacleForState(state, state.player.position, 180)?.label ?? null,
    obstacle: null
  };
}

function getPriorityBreachObstacleForState(state: RaidState): ArenaObstacle | null {
  if (state.activeObstacleBreach) {
    return state.obstacles.find((obstacle) => obstacle.id === state.activeObstacleBreach?.obstacleId) ?? null;
  }

  return (
    state.obstacles
      .filter((obstacle) => obstacle.breach && !obstacle.breach.breached && (obstacle.doorways?.length ?? 0) > 0)
      .sort(
        (left, right) =>
          distance(
            { x: left.x + left.width / 2, y: left.y + left.height / 2 },
            state.player.position
          ) -
          distance(
            { x: right.x + right.width / 2, y: right.y + right.height / 2 },
            state.player.position
          )
      )[0] ?? null
  );
}

export function getNoisePressureRead(route: RaidRouteDefinition, state: RaidState): NoisePressureRead {
  const pendingResponse = getPendingNoiseResponseTier(route, state.noiseResponseLevel);
  const lastTriggeredResponse = getLastTriggeredNoiseResponseTier(route, state.noiseResponseLevel);
  const noiseGap = pendingResponse ? Math.max(0, pendingResponse.threshold - state.soundPressure) : null;
  const reinforcementLabel = pendingResponse
    ? formatNoiseResponseComposition(pendingResponse.reinforcements)
    : lastTriggeredResponse
      ? `${lastTriggeredResponse.label} already burned`
      : "No sweep bodies queued";
  const pressureLabel = `${state.soundPressure.toFixed(2)} noise`;
  const quietIngressActive = state.quietIngressTimer > 0;

  if (quietIngressActive && pendingResponse) {
    return {
      title: "QUIET INGRESS",
      status: `${state.quietIngressTimer.toFixed(0)}s cold-entry window | ${pendingResponse.label} at ${pendingResponse.threshold.toFixed(1)} noise`,
      detail: `The route has not properly made you yet. ${pendingResponse.briefing} stays off-net if you use the opening to cut one sentry, reposition, or bypass the first pocket instead of starting a loud fair trade.`,
      compact: `Ingress | ${state.quietIngressTimer.toFixed(0)}s cold | ${pendingResponse.label} at ${pendingResponse.threshold.toFixed(1)}`,
      tone: "steady",
      nextResponseLabel: `${pendingResponse.label} at ${pendingResponse.threshold.toFixed(1)}`,
      reinforcementLabel,
      pressureLabel
    };
  }

  if (quietIngressActive) {
    return {
      title: "QUIET INGRESS",
      status: `${state.quietIngressTimer.toFixed(0)}s cold-entry window | no sweep staged`,
      detail: "The route has not properly made you yet and no scripted sweep is queued, so the opening is about taking one deliberate body or slipping the lane without waking the district.",
      compact: `Ingress | ${state.quietIngressTimer.toFixed(0)}s cold | no sweep`,
      tone: "steady",
      nextResponseLabel: "No sweep queued",
      reinforcementLabel,
      pressureLabel
    };
  }

  if (!pendingResponse && lastTriggeredResponse) {
    return {
      title: "ROUTE BLOWN",
      status: `${lastTriggeredResponse.label} already triggered | ${state.recentNoiseLabel}`,
      detail:
        "The scripted route sweeps are already spent. Existing contacts, frontline incidents, and extract crashes now matter more than staying technically quiet.",
      compact: `Blown | ${state.recentNoiseLabel} | sweeps burned`,
      tone: state.soundPressure >= 2.4 ? "critical" : "warning",
      nextResponseLabel: "Route sweeps burned",
      reinforcementLabel,
      pressureLabel
    };
  }

  if (pendingResponse && noiseGap !== null && noiseGap <= 0.35) {
    return {
      title: "ONE MORE LOUD BREAK",
      status: `${pendingResponse.label} ${noiseGap.toFixed(1)} away | ${state.recentNoiseLabel}`,
      detail: `${pendingResponse.briefing} ${reinforcementLabel} will step onto the route if you keep trading from the same lane.`,
      compact: `Blown open | ${state.recentNoiseLabel} | ${pendingResponse.label} ${noiseGap.toFixed(1)}`,
      tone: "critical",
      nextResponseLabel: `${pendingResponse.label} in ${noiseGap.toFixed(1)}`,
      reinforcementLabel,
      pressureLabel
    };
  }

  if (pendingResponse && state.soundPressure >= 2.4) {
    return {
      title: "COMPROMISED LANE",
      status: `${pendingResponse.label} in ${noiseGap?.toFixed(1) ?? "--"} noise | ${state.recentNoiseLabel}`,
      detail: `The route has a clean read on this pocket now. Cut angle, cool the lane, or hard-commit before ${pendingResponse.label.toLowerCase()} arrives with ${reinforcementLabel}.`,
      compact: `Compromised | ${state.recentNoiseLabel} | ${pendingResponse.label} ${noiseGap?.toFixed(1) ?? "--"}`,
      tone: "warning",
      nextResponseLabel: `${pendingResponse.label} in ${noiseGap?.toFixed(1) ?? "--"}`,
      reinforcementLabel,
      pressureLabel
    };
  }

  if (pendingResponse && state.soundPressure >= 1.1) {
    return {
      title: "HEARD ON THE NET",
      status: `${pendingResponse.label} in ${noiseGap?.toFixed(1) ?? "--"} noise | ${state.recentNoiseLabel}`,
      detail: `The lane has heard you twice, but it is not fully blown yet. ${pendingResponse.briefing} Keep the next touch deliberate if you want to stay ahead of ${reinforcementLabel}.`,
      compact: `Heard | ${state.recentNoiseLabel} | ${pendingResponse.label} ${noiseGap?.toFixed(1) ?? "--"}`,
      tone: "warning",
      nextResponseLabel: `${pendingResponse.label} in ${noiseGap?.toFixed(1) ?? "--"}`,
      reinforcementLabel,
      pressureLabel
    };
  }

  if (pendingResponse && state.soundPressure > 0.12) {
    return {
      title: "COOL THE LANE",
      status: `${pendingResponse.label} at ${pendingResponse.threshold.toFixed(1)} | ${state.recentNoiseLabel}`,
      detail: `The route still thinks this was background friction. Stay under ${pendingResponse.threshold.toFixed(1)} noise and ${pendingResponse.label.toLowerCase()} stays off-net.`,
      compact: `Cooling | ${state.recentNoiseLabel} | stay under ${pendingResponse.threshold.toFixed(1)}`,
      tone: "steady",
      nextResponseLabel: `${pendingResponse.label} at ${pendingResponse.threshold.toFixed(1)}`,
      reinforcementLabel,
      pressureLabel
    };
  }

  if (pendingResponse) {
    return {
      title: "QUIET LANE",
      status: `${pendingResponse.label} waits at ${pendingResponse.threshold.toFixed(1)} noise`,
      detail: `The route is still reading quiet. ${pendingResponse.briefing} stays off the board if you keep the first fight short and controlled.`,
      compact: `Quiet | ${pendingResponse.label} at ${pendingResponse.threshold.toFixed(1)}`,
      tone: "steady",
      nextResponseLabel: `${pendingResponse.label} at ${pendingResponse.threshold.toFixed(1)}`,
      reinforcementLabel,
      pressureLabel
    };
  }

  return {
    title: "QUIET LANE",
    status: "No route sweep is currently staged",
    detail: "This route has no additional noise sweeps queued right now. Existing contacts and extract flares are the main pressure surfaces.",
    compact: `Quiet | ${state.recentNoiseLabel}`,
    tone: "steady",
    nextResponseLabel: "No sweep queued",
    reinforcementLabel,
    pressureLabel
  };
}

export function getRaidOperationRead(state: RaidState): RaidOperationRead {
  const route =
    RAID_ROUTES.find((candidate) => candidate.id === state.activeRouteId) ??
    RAID_ROUTES[0];
  const activeSector =
    state.frontlineSectors.find((sector) => sector.routeId === route.id) ?? null;
  const settlementRead = getSettlementStateRead(state, route.id);
  const noiseRead = getNoisePressureRead(route, state);
  const focusedExtract = getFocusedExtractForState(state);
  const extractRisk = getExtractSquadRiskRead(state);
  const manifestCount =
    state.carriedManifest.intel +
    state.carriedManifest.medical +
    state.carriedManifest.munitions +
    state.carriedManifest.hardware;
  const recoveryDriven = isRecoveryDrivenRaidState(state);
  const bankLoaded = state.carriedValue > 0 || manifestCount > 0 || state.activeContract.completed;
  const ringThreats = state.enemies.filter(
    (enemy) => distance(enemy.position, focusedExtract.position) <= focusedExtract.radius + 96
  ).length;
  const playerDistanceToExtract = distance(state.player.position, focusedExtract.position);
  const playerInExtractZone = playerDistanceToExtract <= focusedExtract.radius - 12;
  const playerNearExtract = playerDistanceToExtract <= focusedExtract.radius + 48;
  const holdSlipping = state.extractionHoldTimer > 0 && !state.extractionContested && !playerInExtractZone;
  const nearestWave = state.pendingReinforcements.reduce<PendingReinforcementState | null>(
    (best, pending) => (!best || pending.timer < best.timer ? pending : best),
    null
  );
  const focusedCasualtyIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "casualty" &&
        !incident.resolved &&
        (incident.id === state.focusedFrontlineIncidentId || incident.status === "engaged")
    ) ?? null;
  const focusedStripIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "convoy" &&
        !incident.resolved &&
        incident.presentationVariant === "white-van-ambush" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const whiteVanAmbushLive = focusedStripIncident !== null;
  const focusedDishHouseIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "firefight" &&
        !incident.resolved &&
        incident.presentationVariant === "dish-house-breach" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const dishHouseBreachLive = focusedDishHouseIncident !== null;
  const focusedBunkerFootholdIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "bunker" &&
        !incident.resolved &&
        incident.presentationVariant === "bunker-foothold" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const bunkerFootholdLive = focusedBunkerFootholdIncident !== null;
  const focusedAmrCounterLaneIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "firefight" &&
        !incident.resolved &&
        incident.presentationVariant === "amr-counter-lane" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const amrCounterLaneLive = focusedAmrCounterLaneIncident !== null;
  const focusedCoveringCrossingIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "firefight" &&
        !incident.resolved &&
        incident.presentationVariant === "covering-crossing" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const coveringCrossingLive = focusedCoveringCrossingIncident !== null;
  const focusedDishHouseSquad =
    focusedDishHouseIncident !== null ? getFocusedEnemySquadRead(state, focusedDishHouseIncident.position, 220) : null;
  const focusedBunkerFootholdSquad =
    focusedBunkerFootholdIncident !== null
      ? getFocusedEnemySquadRead(state, focusedBunkerFootholdIncident.position, 220)
      : null;
  const focusedDishHouseCompressedCount =
    focusedDishHouseIncident !== null
      ? state.enemies.filter(
          (enemy) =>
            enemy.casualtyState !== "downed" &&
            enemy.casualtyState !== "dead" &&
            enemy.compressionState !== "idle" &&
            distance(enemy.position, focusedDishHouseIncident.position) <= 220
        ).length
      : 0;
  const dishHouseCompressionLive = focusedDishHouseCompressedCount >= 2;
  const dishHouseDeepRoomStillLive =
    focusedDishHouseSquad !== null && !focusedDishHouseSquad.secondRoomSoftened;
  const dishHouseCrossingStillOwned =
    focusedDishHouseSquad !== null && !focusedDishHouseSquad.crossingDangerReduced;
  const bunkerFootholdCompressionCount =
    focusedBunkerFootholdIncident !== null
      ? state.enemies.filter(
          (enemy) =>
            enemy.casualtyState !== "downed" &&
            enemy.casualtyState !== "dead" &&
            enemy.compressionState !== "idle" &&
            distance(enemy.position, focusedBunkerFootholdIncident.position) <= 220
        ).length
      : 0;
  const bunkerFootholdCompressedLive = bunkerFootholdCompressionCount >= 2;
  const bunkerFootholdDeepRoomStillLive =
    focusedBunkerFootholdSquad !== null && !focusedBunkerFootholdSquad.secondRoomSoftened;
  const bunkerFootholdSupportStillOwnsLane =
    focusedBunkerFootholdSquad !== null && !focusedBunkerFootholdSquad.crossingDangerReduced;
  const roomClearShowcaseLive =
    activeSector?.routeModifierTitle === "Authored three-room clear stack" &&
    state.player.frontlineMomentumTimer > 0;
  const roomClearCompressedCount = state.enemies.filter(
    (enemy) =>
      enemy.casualtyState !== "downed" &&
      enemy.casualtyState !== "dead" &&
      enemy.compressionState !== "idle" &&
      distance(enemy.position, state.player.position) <= 280
  ).length;
  const roomClearCompressedLive = roomClearCompressedCount >= 2;
  const focusedDroneSweepIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "firefight" &&
        !incident.resolved &&
        incident.presentationVariant === "drone-sweep" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const droneSweepLive = focusedDroneSweepIncident !== null;
  const focusedHostileChatterIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "firefight" &&
        !incident.resolved &&
        incident.presentationVariant === "hostile-lane-chatter" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const hostileLaneChatterLive = focusedHostileChatterIncident !== null;
  const focusedArmoredDropIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "convoy" &&
        !incident.resolved &&
        incident.presentationVariant === "armored-drop" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const armoredDropLive = focusedArmoredDropIncident !== null;
  const focusedMortarBracketIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "firefight" &&
        !incident.resolved &&
        incident.presentationVariant === "mortar-bracket" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const mortarBracketLive = focusedMortarBracketIncident !== null;
  const focusedCaravanTrapIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "convoy" &&
        !incident.resolved &&
        incident.presentationVariant === "caravan-trap" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const caravanTrapLive = focusedCaravanTrapIncident !== null;
  const focusedCellarIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "bunker" &&
        !incident.resolved &&
        incident.presentationVariant === "cellar-counterhold" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const cellarCounterholdLive = focusedCellarIncident !== null;
  const focusedCellarSquad =
    focusedCellarIncident !== null ? getFocusedEnemySquadRead(state, focusedCellarIncident.position, 220) : null;
  const cellarCompressedCount =
    focusedCellarIncident !== null
      ? state.enemies.filter(
          (enemy) =>
            enemy.casualtyState !== "downed" &&
            enemy.casualtyState !== "dead" &&
            enemy.compressionState !== "idle" &&
            distance(enemy.position, focusedCellarIncident.position) <= 220
        ).length
      : 0;
  const cellarCompressedLive = cellarCompressedCount >= 2;
  const cellarDeepRoomStillLive = focusedCellarSquad !== null && !focusedCellarSquad.secondRoomSoftened;
  const focusedHideIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "bunker" &&
        !incident.resolved &&
        incident.presentationVariant === "shed-hide" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const shedHideLive = focusedHideIncident !== null;
  const focusedCivilianIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "civilian" &&
        !incident.resolved &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const hunterSearchLive = focusedCivilianIncident?.presentationVariant === "hunter-search";
  const civilianEvacLive = focusedCivilianIncident !== null && !hunterSearchLive;
  const focusedWoundedSoldierIncident =
    state.frontlineIncidents.find(
      (incident) =>
        incident.kind === "firefight" &&
        !incident.resolved &&
        incident.presentationVariant === "wounded-soldier" &&
        (incident.id === state.focusedFrontlineIncidentId || distance(incident.position, state.player.position) <= 220)
    ) ?? null;
  const woundedSoldierLive = focusedWoundedSoldierIncident !== null;
  const armoredEvacIncident =
    focusedCasualtyIncident === null
      ? null
      : state.frontlineIncidents.find(
          (incident) =>
            incident.kind === "convoy" &&
            !incident.resolved &&
            incident.status === "extracting" &&
            distance(incident.position, focusedCasualtyIncident.position) <= 180
        ) ?? null;
  const armoredEvacLive = focusedCasualtyIncident !== null && armoredEvacIncident !== null;
  const ownershipFocusPosition =
    focusedDishHouseIncident?.position ??
    focusedBunkerFootholdIncident?.position ??
    focusedCellarIncident?.position ??
    focusedHideIncident?.position ??
    focusedMortarBracketIncident?.position ??
    focusedHostileChatterIncident?.position ??
    focusedDroneSweepIncident?.position ??
    focusedCaravanTrapIncident?.position ??
    focusedStripIncident?.position ??
    focusedArmoredDropIncident?.position ??
    focusedCoveringCrossingIncident?.position ??
    focusedAmrCounterLaneIncident?.position ??
    focusedCivilianIncident?.position ??
    focusedWoundedSoldierIncident?.position ??
    focusedCasualtyIncident?.position ??
    state.player.position;
  const focusedOwnershipRead =
    state.phase === "raid" ? getFocusedEnemySquadOwnershipRead(state, ownershipFocusPosition, 240) : null;
  const ownershipLabel = focusedOwnershipRead?.ownershipLabel ?? null;
  const ownershipStatusLabel = focusedOwnershipRead?.statusLabel ?? null;
  const ownershipStatusSuffix = ownershipStatusLabel ? ` | ${ownershipStatusLabel}` : "";
  const crashSoon = nearestWave !== null && (nearestWave.source === "extraction-wave" || nearestWave.timer <= 12);
  const settlementPressurePenalty =
    settlementRead.control === "lost"
      ? 18
      : settlementRead.volatility === "breaking"
        ? 14
        : settlementRead.volatility === "reclaiming"
          ? 10
          : settlementRead.volatility === "fragile"
            ? 6
            : 0;
  const settlementSoundTax = settlementPressurePenalty / 100;
  const effectiveSoundPressure = state.soundPressure + settlementSoundTax;
  const contractDriven =
    state.activeContract.completed ||
    state.activeContract.progress >= Math.max(1, Math.ceil(state.activeContract.target * 0.7));
  const extractPlanned = state.extractionReady && state.activeExtractId !== null;
  const extractCommitted =
    state.extractionHoldTimer > 0 ||
    state.extractionContested ||
    (playerNearExtract && (bankLoaded || recoveryDriven || ringThreats > 0 || crashSoon || state.soundPressure >= 0.6)) ||
    (extractPlanned &&
      (recoveryDriven ||
        crashSoon ||
        ringThreats >= 2 ||
        state.soundPressure >= 0.84 ||
        state.timerRemaining <= 60));
  const extractCleanliness: RaidExtractCleanliness =
    holdSlipping || state.extractionContested
      ? "slipping"
      : state.extractionHoldTimer > 0 || ringThreats >= 3 || crashSoon || effectiveSoundPressure >= 1.2
        ? "hot"
        : extractCommitted || ringThreats > 0 || effectiveSoundPressure >= 0.4
          ? "warming"
          : "clean";
  const phase: RaidOperationPhase =
    holdSlipping || state.extractionContested || (extractCommitted && (ringThreats >= 3 || crashSoon))
      ? "collapse"
        : state.extractionHoldTimer > 0 || extractCommitted
          ? "exfil"
        : hunterSearchLive
          ? "commitment"
        : civilianEvacLive
          ? "commitment"
        : cellarCounterholdLive
          ? "commitment"
        : shedHideLive
          ? "commitment"
        : hostileLaneChatterLive
          ? "commitment"
        : droneSweepLive
          ? "commitment"
        : mortarBracketLive
          ? "commitment"
        : caravanTrapLive
          ? "commitment"
        : bankLoaded ||
            state.currentRaidStats.intelSecured > 0 ||
            state.currentRaidStats.lootRecovered > 0 ||
            state.currentRaidStats.cachesSearched > 0 ||
            state.currentRaidStats.scavsKilled >= 3 ||
            effectiveSoundPressure >= 0.76
          ? "commitment"
          : state.currentRaidStats.scavsKilled > 0 ||
              state.currentRaidStats.cachesSearched > 0 ||
              effectiveSoundPressure > 0.12
            ? "gain"
            : "approach";
  const exitIntent: RaidOperationExitIntent = recoveryDriven
    ? "recovery"
    : hunterSearchLive
      ? "contract"
    : civilianEvacLive
      ? "contract"
    : woundedSoldierLive
      ? "survival"
    : !bankLoaded && (phase === "collapse" || state.timerRemaining <= 45)
      ? "survival"
      : contractDriven
        ? "contract"
        : "profit";
  const pressureScore = Number(
    Math.min(
      100,
      effectiveSoundPressure * 18 +
        ringThreats * 11 +
        (nearestWave ? Math.max(0, 26 - nearestWave.timer) * 2.1 : 0) +
        (state.extractionContested ? 24 : 0) +
        (holdSlipping ? 18 : 0) +
        settlementPressurePenalty
    ).toFixed(1)
  );
  const phaseLabel =
    phase === "approach"
      ? "Approach"
      : phase === "gain"
        ? "Initial gain"
        : phase === "commitment"
          ? "Commitment"
          : phase === "exfil"
            ? "Exfil problem"
            : "Collapse";
  const exitIntentLabel =
    exitIntent === "profit"
      ? "Leave with the haul"
      : exitIntent === "contract"
        ? "Lock the contract"
        : exitIntent === "recovery"
          ? "Recovery-driven"
          : "Survive the route";
  const extractCleanlinessLabel =
    extractCleanliness === "clean"
      ? "Clean exit"
      : extractCleanliness === "warming"
        ? "Exit warming"
        : extractCleanliness === "hot"
          ? "Hot exfil"
          : "Route slipping";
  const crashWaveReadiness =
    nearestWave !== null
      ? `${nearestWave.label} in ${nearestWave.timer.toFixed(1)}s`
      : "No crash wave queued";
  const settlementStatus = `${settlementRead.label} | ${settlementRead.volatilityLabel}`;
  const settlementRiskLine =
    settlementPressurePenalty > 0
      ? `${settlementRead.extractRisk} ${settlementRead.tacticalPlan}`
      : settlementRead.extractRisk;

  if (phase === "collapse") {
    return {
      phase,
      phaseLabel,
      pressureScore,
      pressureLabel: `${pressureScore.toFixed(0)} pressure`,
      settlementLabel: settlementRead.label,
      settlementVolatilityLabel: settlementRead.volatilityLabel,
      settlementExtractRisk: settlementRead.extractRisk,
      settlementPressurePenalty,
      exitIntent,
      exitIntentLabel,
      extractCleanliness,
      extractCleanlinessLabel,
      focusedExtractLabel: focusedExtract.label,
      crashWaveReadiness,
      title: "DISTRICT CLOSING",
      status: `${settlementStatus} | ${extractCleanlinessLabel} | ${focusedExtract.label}${ownershipStatusSuffix}`,
      detail:
        hunterSearchLive
          ? extractCleanliness === "slipping"
            ? `${focusedCivilianIncident.label} is no longer a clean guide lane. ${settlementRiskLine} Re-enter the reeds, reopen the hunter screen, and keep the old man moving before the treeline swallows the son's route note for good.`
            : `${focusedCivilianIncident.label} is still live, but the search lane is closing around the shack and reed cut. ${settlementRiskLine} ${extractRisk.detail} Pull the old hunter now or the rescue turns into a forced survival peel.`
        : woundedSoldierLive
          ? extractCleanliness === "slipping"
            ? `${focusedWoundedSoldierIncident.label} is no longer a controllable medic hold. ${settlementRiskLine} Re-enter the split, restitch Yara's shoulder, and reopen the peel before one more bad trade turns the wound into a full squad collapse.`
            : `${focusedWoundedSoldierIncident.label} is still live, but the split is closing around Yara's hot shoulder. ${settlementRiskLine} ${extractRisk.detail} Keep her moving now or the medic hold turns into a forced survival peel.`
        : civilianEvacLive
          ? extractCleanliness === "slipping"
            ? `${focusedCivilianIncident.label} is no longer a clean escort. ${settlementRiskLine} Re-enter the block, reopen the cellar mouth, and keep the van curb alive before the family gets trapped in a full panic peel.`
            : `${focusedCivilianIncident.label} is still live, but the block is closing around the family and the waiting van. ${settlementRiskLine} ${extractRisk.detail} Peel the family now or the escort turns into a forced survival exit.`
        : bunkerFootholdLive
          ? extractCleanliness === "slipping"
            ? `${focusedBunkerFootholdIncident.label} is no longer a calm bunker reset. ${settlementRiskLine} Re-enter the concrete mouth, win the lip again, and peel before Blue reseats the freight lane onto the bunker pocket. ${
                bunkerFootholdSupportStillOwnsLane
                  ? bunkerFootholdDeepRoomStillLive
                    ? "The lane gun still owns the freight lip and the back room is still live."
                    : "The lane gun still owns the freight lip."
                  : bunkerFootholdCompressedLive && bunkerFootholdDeepRoomStillLive
                    ? "The bunker pocket has compressed inward and the back room is still live."
                    : "The bunker pocket is only half-held."
              }`
            : `${focusedBunkerFootholdIncident.label} is still live, but the freight lip is tightening around the concrete mouth. ${settlementRiskLine} ${extractRisk.detail} ${
                bunkerFootholdSupportStillOwnsLane
                  ? bunkerFootholdDeepRoomStillLive
                    ? "Kill the lip gun, then settle inside and clear the back room."
                    : "Kill the lip gun, then settle inside."
                  : bunkerFootholdCompressedLive && bunkerFootholdDeepRoomStillLive
                    ? "The bunker pocket is compressing inward, so win the mouth and clear the back room before the lane reseats."
                    : "Own the concrete mouth now or the bunker reset turns into a forced survival peel."
              }`
        : dishHouseBreachLive
          ? extractCleanliness === "slipping"
            ? `${focusedDishHouseIncident.label} is no longer a clean room-take. ${settlementRiskLine} Re-enter the block, win the first door again, and peel before the relay reserve reseats the whole lane onto the dish houses. ${
                dishHouseCrossingStillOwned
                  ? "The lane gun is still owning the crossing."
                  : dishHouseCompressionLive
                    ? dishHouseDeepRoomStillLive
                      ? "The building has already compressed inward and room two is still live."
                      : "The building has already compressed inward and only the deeper reset is still hanging on."
                    : "The first room is still too loose to count as solved."
              }`
            : `${focusedDishHouseIncident.label} is still live, but the block is closing around the first doorway and the short hall. ${settlementRiskLine} ${extractRisk.detail} ${
                dishHouseCrossingStillOwned
                  ? "Kill the lane gun, cross clean, and only then flood the rooms."
                  : dishHouseCompressionLive
                    ? dishHouseDeepRoomStillLive
                      ? "The building is compressing inward, so win room one and turn room two before the reserve shove reseats the stack."
                      : "The building is compressing inward, so finish the deeper reset before the reserve shove reseats the stack."
                    : "Flood the rooms now before the dish-house take turns into a forced survival peel."
              }`
        : amrCounterLaneLive
          ? extractCleanliness === "slipping"
            ? `${focusedAmrCounterLaneIncident.label} is no longer a controllable plate-break lane. ${settlementRiskLine} Re-open the brace point, kill the plated repeek owner, and peel before the reserve reseats Dish Houses around the outer angle again.`
            : `${focusedAmrCounterLaneIncident.label} is still live, but the dish-lane repeek is closing around one plated anchor. ${settlementRiskLine} ${extractRisk.detail} Break the plated anchor now or the lane turns into a forced survival peel.`
        : coveringCrossingLive
          ? extractCleanliness === "slipping"
            ? `${focusedCoveringCrossingIncident.label} is no longer a controllable ditch cross. ${settlementRiskLine} Re-open the brace lane, put one body back on moving cover, and cross before the reserve reseats the antenna cut around the whole squad.`
            : `${focusedCoveringCrossingIncident.label} is still live, but the antenna ditch is closing around the brace point and moving-cover lane. ${settlementRiskLine} ${extractRisk.detail} Cross under moving cover now or the lane turns into a forced survival peel.`
        : droneSweepLive
          ? extractCleanliness === "slipping"
            ? `${focusedDroneSweepIncident.label} is no longer a quiet relay cut. ${settlementRiskLine} Re-enter the hedges, steal the route board fast, and reopen the slip before the drone settles the whole lane onto your boys.`
            : `${focusedDroneSweepIncident.label} is still live, but the eye is closing around the relay board and hedge cut. ${settlementRiskLine} ${extractRisk.detail} Cut the board now or the infiltration lane turns into a forced survival peel.`
        : mortarBracketLive
          ? extractCleanliness === "slipping"
            ? `${focusedMortarBracketIncident.label} is no longer a controllable shell lane. ${settlementRiskLine} Re-enter the clinic cut, break the tube fast, and reopen the underpass peel before the next bracket walks the whole strip shut.`
            : `${focusedMortarBracketIncident.label} is still live, but the bracket is closing around Clinic Row and the med lane lip. ${settlementRiskLine} ${extractRisk.detail} Break the tube now or the shell lane turns into a forced survival peel.`
        : hostileLaneChatterLive
          ? extractCleanliness === "slipping"
            ? `${focusedHostileChatterIncident.label} is no longer a readable dock argument. ${settlementRiskLine} Re-enter the gantry lane, kill the loudest tape mouth first, and reopen the peel before the whole district hardens around the cranes.`
            : `${focusedHostileChatterIncident.label} is still live, but the crane cut is closing under overlapping Blue, Green, and Yellow calls. ${settlementRiskLine} ${extractRisk.detail} Cut the loudest tape now or the dock fight turns into a forced survival peel.`
        : caravanTrapLive
          ? extractCleanliness === "slipping"
            ? `${focusedCaravanTrapIncident.label} is no longer a controllable salvage lane. ${settlementRiskLine} Re-enter the wreck shoulder, strip what still matters, and reopen the pull before the kill zone turns into a second volley trap.`
            : `${focusedCaravanTrapIncident.label} is still live, but the road is closing around the burning wagons and loose haul. ${settlementRiskLine} ${extractRisk.detail} Strip the kill zone now or the salvage run turns into a forced survival peel.`
        : extractCleanliness === "slipping"
          ? recoveryDriven
            ? armoredEvacLive
              ? `${focusedExtract.label} is no longer a clean recovery peel. ${settlementRiskLine} Re-enter the ring, break the evac wagon screen, and keep the bag or casualty corridor intact before the route folds.`
              : `${focusedExtract.label} is no longer a clean recovery peel. ${settlementRiskLine} Re-enter the ring, kill the contesters, and keep the bag or casualty corridor intact before the route folds.`
            : `${focusedExtract.label} is no longer a clean pull. ${settlementRiskLine} Re-enter the ring, kill the contesters, and treat the run like a forced exit instead of one more greedy pocket.`
          : recoveryDriven
            ? armoredEvacLive
              ? `${focusedExtract.label} is heating past the comfort line while Blue is still trying to shove wounded into the wagon. ${settlementRiskLine} ${extractRisk.detail} Break the load mouth, peel under pressure now, and stop spending the corridor on greed.`
              : `${focusedExtract.label} is heating past the comfort line while the route is already bent around recovery work. ${settlementRiskLine} ${extractRisk.detail} Peel under pressure now and stop spending the corridor on greed.`
            : `${focusedExtract.label} is heating past the comfort line. ${settlementRiskLine} ${extractRisk.detail} Leave under pressure now.`,
      compact: `Collapse | ${focusedExtract.label} | ${exitIntentLabel}${ownershipLabel ? ` | ${ownershipLabel}` : ""}`,
      tone: "critical",
      ownershipLabel
    };
  }

  if (phase === "exfil") {
    return {
      phase,
      phaseLabel,
      pressureScore,
      pressureLabel: `${pressureScore.toFixed(0)} pressure`,
      settlementLabel: settlementRead.label,
      settlementVolatilityLabel: settlementRead.volatilityLabel,
      settlementExtractRisk: settlementRead.extractRisk,
      settlementPressurePenalty,
      exitIntent,
      exitIntentLabel,
      extractCleanliness,
      extractCleanlinessLabel,
      focusedExtractLabel: focusedExtract.label,
      crashWaveReadiness,
      title: "EXFIL PROBLEM",
      status: `${settlementStatus} | ${focusedExtract.label} | ${crashWaveReadiness}${ownershipStatusSuffix}`,
      detail: hunterSearchLive
        ? `${focusedCivilianIncident.label} is now the real pull, not just ambient tragedy. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? "Keep the guide lane stable until the old hunter clears the reeds and the son's route note is bagged."
              : "Stage the boys, walk the hunter off the treeline, and burn the peel before the search lane reheats."
          }`
        : woundedSoldierLive
        ? `${focusedWoundedSoldierIncident.label} is now the real hold, not a normal room-clear follow-through. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? "Keep the split stitched until Yara clears the shoulder and the lane stops hinging on one wounded body."
              : "Stage the boys, keep Yara moving, and burn the peel before the next bad trade drops her out of the push."
          }`
        : civilianEvacLive
        ? `${focusedCivilianIncident.label} is now the real pull, not background flavor. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? "Keep the van lane stable until the family clears the curb and the cellar note is bagged."
              : "Stage the boys, walk the family to the white van, and burn the peel before the block reheats."
          }`
        : bunkerFootholdLive
        ? `${focusedBunkerFootholdIncident.label} is now the real foothold problem, not just a bunker prop. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? bunkerFootholdSupportStillOwnsLane
                ? bunkerFootholdDeepRoomStillLive
                  ? "Keep the concrete mouth owned until the lip gun drops and the back room finally quiets."
                  : "Keep the concrete mouth owned until the lip gun drops and the bunker finally quiets."
                : bunkerFootholdCompressedLive && bunkerFootholdDeepRoomStillLive
                  ? "Keep the concrete mouth owned while the bunker compresses inward and the back room finally goes quiet."
                  : "Keep the concrete mouth owned until the bunker quiets."
              : bunkerFootholdSupportStillOwnsLane
                ? bunkerFootholdDeepRoomStillLive
                  ? "Stage the boys, kill the lip gun, clear the back room, and only then settle the bunker."
                  : "Stage the boys, kill the lip gun, and only then settle the bunker."
                : bunkerFootholdCompressedLive && bunkerFootholdDeepRoomStillLive
                  ? "Stage the boys, own the concrete mouth, and clear the bunker back room before the freight lane reheats."
                  : "Stage the boys, settle the bunker, and burn the peel before the freight lane reheats."
          }`
        : dishHouseBreachLive
        ? `${focusedDishHouseIncident.label} is now the real room problem, not just another relay duel. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? focusedDishHouseSquad?.crossingDangerReduced
                ? dishHouseCompressionLive
                  ? dishHouseDeepRoomStillLive
                    ? "Keep the first room owned while the dead belt keeps the crossing softer, the building compresses inward, and room two finally goes quiet."
                    : "Keep the first room owned while the dead belt keeps the crossing softer and the deeper reset finally collapses."
                  : "Keep the first room owned while the dead belt keeps the crossing softer and the short hall finally goes quiet."
                : dishHouseCompressionLive
                  ? "Keep the first room owned, break the lane gun, and do not let the compressed stack turn room two into the real hold."
                  : "Keep the first room owned until the short hall finally goes quiet and the reserve shove loses the block."
              : focusedDishHouseSquad?.crossingDangerReduced
                ? dishHouseCompressionLive
                  ? dishHouseDeepRoomStillLive
                    ? "Stage the boys, flood the first door, and turn room two before the reserve lane can reseat Dish Houses."
                    : "Stage the boys, flood the first door, and finish the deeper reset before the reserve lane can reseat Dish Houses."
                  : "Stage the boys, flood the first door, and ride the dead-belt crossing before the reserve lane can reseat Dish Houses."
                : "Stage the boys, kill the lane gun, and burn the peel before the reserve lane turns Dish Houses back into a long-angle fight."
          }`
        : amrCounterLaneLive
        ? `${focusedAmrCounterLaneIncident.label} is now the real lane problem, not generic outer contact. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? "Keep the brace point stable until the plated repeek owner drops and the crack stays open long enough for the follow-up flood."
              : "Stage the boys, break the plated anchor, and burn the peel before the relay reserve turns Dish Houses back into a hard outer-lane hold."
          }`
        : coveringCrossingLive
        ? `${focusedCoveringCrossingIncident.label} is now the real crossing problem, not generic relay pressure. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? "Keep the brace lane stable until the ditch crosser clears the cut and the moving-cover body stops the reserve from reseating the antenna lip."
              : "Stage the boys, brace the ditch, and burn the cross before the reserve lane turns the antenna cut back into a stand-up hold."
          }`
        : droneSweepLive
        ? `${focusedDroneSweepIncident.label} is now the real cut, not just atmosphere. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? "Keep the hedge screen low until the relay board is bagged and the drone slides past the lane."
              : "Stage the boys, steal the route board under the eye, and burn the peel before the sweep settles the relay cut."
          }`
        : mortarBracketLive
        ? `${focusedMortarBracketIncident.label} is now the real strip problem, not background shell flavor. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? "Keep the clinic cut broken until the tube goes quiet and the underpass peel clears the bracket walk."
              : "Stage the boys, break the tube lane, and burn the peel before the next bracket settles Ambulance Mile shut."
          }`
        : hostileLaneChatterLive
        ? `${focusedHostileChatterIncident.label} is now the real dock problem, not just ambient shouting. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? "Keep the gantry screen steady until the loudest tape mouth is cut and the peel lane quiets."
              : "Stage the boys, cut the loudest tape first, and burn the peel before the whole dock starts moving on the same call."
          }`
        : caravanTrapLive
        ? `${focusedCaravanTrapIncident.label} is now the real road problem, not only scenery. ${settlementRiskLine} ${extractRisk.detail} ${
            state.extractionHoldTimer > 0
              ? "Keep the wreck shoulder covered until the loose haul is bagged and the second volley misses the strip."
              : "Stage the boys, strip the kill zone fast, and burn the peel before Blue resets the trap on the burning wagons."
          }`
        : recoveryDriven
        ? `${focusedExtract.label} is now a recovery peel, not just the way out. ${settlementRiskLine} ${extractRisk.detail} ${
            armoredEvacLive
              ? state.extractionHoldTimer > 0
                ? "Keep the hold stable until the bag or casualty clears the beacon and the evac wagon loses the strip."
                : "Stage the boys, break the wagon shoulder, and burn the pull before the district closes harder on the recovery lane."
              : state.extractionHoldTimer > 0
                ? "Keep the hold stable until the bag or casualty clears the beacon."
                : "Stage the boys and burn the pull before the district closes harder on the recovery lane."
          }`
        : `${focusedExtract.label} is now the real fight. ${settlementRiskLine} ${extractRisk.detail} ${state.extractionHoldTimer > 0 ? "Keep the hold stable until the beacon clears." : "Stage the boys and burn the pull before the district closes harder."}`,
      compact: `Exfil | ${focusedExtract.label} | ${extractCleanlinessLabel}${ownershipLabel ? ` | ${ownershipLabel}` : ""}`,
      tone: extractCleanliness === "hot" ? "warning" : "steady",
      ownershipLabel
    };
  }

  if (phase === "commitment") {
    return {
      phase,
      phaseLabel,
      pressureScore,
      pressureLabel: `${pressureScore.toFixed(0)} pressure`,
      settlementLabel: settlementRead.label,
      settlementVolatilityLabel: settlementRead.volatilityLabel,
      settlementExtractRisk: settlementRead.extractRisk,
      settlementPressurePenalty,
      exitIntent,
      exitIntentLabel,
      extractCleanliness,
      extractCleanlinessLabel,
      focusedExtractLabel: focusedExtract.label,
      crashWaveReadiness,
      title: "COMMIT OR CUT",
      status: `${settlementStatus} | ${exitIntentLabel} | ${focusedExtract.label}${ownershipStatusSuffix}`,
      detail: hunterSearchLive
        ? `${focusedCivilianIncident.label} is the live guide problem and the treeline is only half-screened. ${settlementRiskLine} Treat ${focusedExtract.label.toLowerCase()} like the hunter peel, walk him off the reeds, bag the son's route note, and only take another pocket if it directly keeps the search lane from collapsing.`
        : woundedSoldierLive
        ? `${focusedWoundedSoldierIncident.label} is the live medical-hold problem and Yara only stays useful while the shoulder stays stitched. ${settlementRiskLine} Treat ${focusedExtract.label.toLowerCase()} like the peel, keep the boys screening her split, and only spend another pocket if it directly stops the wound from becoming a collapse tax.`
        : civilianEvacLive
        ? `${focusedCivilianIncident.label} is the live escort problem and the block is only half-screened. ${settlementRiskLine} Treat ${focusedExtract.label.toLowerCase()} like the family peel, move the civilians to the van, and only take another pocket if it directly keeps the curb lane from collapsing.`
        : bunkerFootholdLive
          ? `${focusedBunkerFootholdIncident.label} is the live bunker-pocket problem and the freight lip only stays solvable while the bunker mouth is still yours. ${settlementRiskLine} ${
              bunkerFootholdSupportStillOwnsLane
                ? bunkerFootholdDeepRoomStillLive
                  ? "Kill the lip gun first, keep the concrete mouth owned, turn the back room, and only spend another pocket if it directly protects"
                  : "Kill the lip gun first, keep the concrete mouth owned, and only spend another pocket if it directly protects"
                : bunkerFootholdCompressedLive && bunkerFootholdDeepRoomStillLive
                  ? "The bunker pocket is compressing inward, so win the mouth, clear the back room, and only spend another pocket if it directly protects"
                  : "Own the concrete mouth, bank the reset, and only spend another pocket if it directly protects"
            } ${focusedExtract.label.toLowerCase()} from inheriting the whole freight lane.`
        : amrCounterLaneLive
          ? `${focusedAmrCounterLaneIncident.label} is the live plate-break problem and the dish lane only stays solvable while the brace point still owns the first shot. ${settlementRiskLine} Break the plated anchor first, keep the repeek shut, and only spend another pocket if it directly protects ${focusedExtract.label.toLowerCase()} from inheriting the whole outer lane.`
        : coveringCrossingLive
          ? `${focusedCoveringCrossingIncident.label} is the live crossing problem and the ditch only stays solvable while one boy is braced and another is already walking moving cover. ${settlementRiskLine} Brace the lane, cross under moving cover, and only spend another pocket if it directly protects ${focusedExtract.label.toLowerCase()} from inheriting the whole antenna cut.`
        : dishHouseBreachLive
          ? `${focusedDishHouseIncident.label} is the live room-flood problem and the first doorway only stays winnable while the short hall is still disorganized. ${settlementRiskLine} ${
              focusedDishHouseSquad?.crossingDangerReduced
                ? dishHouseCompressionLive
                  ? dishHouseDeepRoomStillLive
                    ? "The support belt is already dead and the building is compressing, so flood room one, turn room two, and only spend another pocket if it directly protects"
                    : "The support belt is already dead and the building is compressing, so finish the deeper reset and only spend another pocket if it directly protects"
                  : "The support belt is already dead, so flood the first room while the crossing is softer, keep the yard lid up, and only spend another pocket if it directly protects"
                : "Kill the lane gun, keep the yard lid up, and only spend another pocket if it directly protects"
            } ${focusedExtract.label.toLowerCase()} from inheriting the whole relay block.`
        : cellarCounterholdLive
          ? `${focusedCellarIncident.label} is the only reliable foothold in the relay cut while the reserve lane is still trying to shove back into the dish houses. ${settlementRiskLine} ${
              cellarCompressedLive && cellarDeepRoomStillLive
                ? `Hold the cellar mouth, turn the back room, and only widen if the next pocket directly keeps ${focusedExtract.label.toLowerCase()} from becoming another panic peel.`
                : `Hold the cellar mouth, bank the route note, and only widen if the next pocket directly keeps ${focusedExtract.label.toLowerCase()} from becoming another panic peel.`
            }`
        : shedHideLive
          ? `${focusedHideIncident.label} is the only quiet hide still left in the relay sweep and the whole lane depends on staying dark longer than Blue expects. ${settlementRiskLine} Treat ${focusedExtract.label.toLowerCase()} like the planned peel, keep the boys silent, and only spend another pocket if it directly protects the slip back into the village.`
        : mortarBracketLive
          ? `${focusedMortarBracketIncident.label} is the live shell bracket and the strip only stays playable while the tube team is still half-exposed behind Clinic Row. ${settlementRiskLine} Break the tube before the next walk, keep the underpass peel staged, and only spend another pocket if it directly stops ${focusedExtract.label.toLowerCase()} from inheriting the whole bracketed lane.`
        : droneSweepLive
          ? `${focusedDroneSweepIncident.label} is the live spotter-eye cut and the relay hedge only stays quiet while the drone is drifting past. ${settlementRiskLine} Keep the boys low, steal the route board, and only spend another pocket if it directly protects ${focusedExtract.label.toLowerCase()} from turning into a panic peel under the next sweep pass.`
        : hostileLaneChatterLive
          ? `${focusedHostileChatterIncident.label} is the live dock argument and the tape calls are already teaching Blue where to lean next. ${settlementRiskLine} Cut the loudest tape first, keep the boys on the gantry lane, and only spend another pocket if it directly protects ${focusedExtract.label.toLowerCase()} from inheriting the whole dock fight.`
        : caravanTrapLive
          ? `${focusedCaravanTrapIncident.label} is the live salvage kill zone and the burning shoulder only pays while Blue is still disorganized around the wrecks. ${settlementRiskLine} Strip the loose haul, keep the boys owning the berm, and only spend another pocket if it directly protects ${focusedExtract.label.toLowerCase()} from becoming the next bracketed strip.`
        : recoveryDriven
        ? armoredEvacLive
          ? `Bodies or casualties are already bending this route and Blue is actively trying to load the same strip into an evac wagon. ${settlementRiskLine} Treat ${focusedExtract.label.toLowerCase()} like the next real objective, break the load mouth, and only take another pocket if it directly secures the corridor.`
          : `Bodies or casualties are already bending this route. ${settlementRiskLine} Treat ${focusedExtract.label.toLowerCase()} like the next real objective and only take another pocket if it directly secures the corridor.`
        : armoredDropLive
          ? `${focusedArmoredDropIncident.label} is the live reinforcement break and fresh tape bodies are already spilling off the ramp. ${settlementRiskLine} Crash the ramp, strip the first dismount kit, and keep ${focusedExtract.label.toLowerCase()} staged as the peel before the relay berm turns into a new hold.`
        : whiteVanAmbushLive
          ? `${focusedStripIncident.label} is the live comms-strip payday and Blue is already leaning reserve on the relay verge. ${settlementRiskLine} Strip the mast kit, keep ${focusedExtract.label.toLowerCase()} staged as the pull, and do not spend another pocket unless it directly keeps the comms haul from being clawed back.`
        : bankLoaded
          ? `The haul is real now, and ${focusedExtract.label} is still ${extractCleanlinessLabel.toLowerCase()}. ${settlementRiskLine} Push only if the next pocket is worth turning this into a harder exit.`
          : `The district is leaning back. ${settlementRiskLine} The contract and route state justify the push, but ${focusedExtract.label} needs to stay in mind before this turns into a forced exit.`,
      compact: `Commitment | ${exitIntentLabel} | ${extractCleanlinessLabel}${ownershipLabel ? ` | ${ownershipLabel}` : ""}`,
      tone: extractCleanliness === "clean" ? "steady" : "warning",
      ownershipLabel
    };
  }

  if (phase === "gain") {
    return {
      phase,
      phaseLabel,
      pressureScore,
      pressureLabel: `${pressureScore.toFixed(0)} pressure`,
      settlementLabel: settlementRead.label,
      settlementVolatilityLabel: settlementRead.volatilityLabel,
      settlementExtractRisk: settlementRead.extractRisk,
      settlementPressurePenalty,
      exitIntent,
      exitIntentLabel,
      extractCleanliness,
      extractCleanlinessLabel,
      focusedExtractLabel: focusedExtract.label,
      crashWaveReadiness,
      title: "GAIN WINDOW",
      status: `${settlementStatus} | ${noiseRead.title} | ${focusedExtract.label}${ownershipStatusSuffix}`,
      detail: roomClearShowcaseLive
        ? `${activeSector?.routeName ?? "The route"} is paying now through a chained room clear, not open-ground greed. ${settlementRiskLine} ${
            roomClearCompressedLive
              ? "Room one is won, but the building has compressed inward and room two is still live."
              : "Room one is won, but the deeper stack is not solved yet."
          } Keep the room-take controlled and protect ${focusedExtract.label.toLowerCase()} before the reserve shove reheats the whole interior.`
        : woundedSoldierLive
        ? `${focusedWoundedSoldierIncident.label} is still paying a narrow medic-hold window while Yara can breathe and fight. ${settlementRiskLine} Keep the split stitched, protect ${focusedExtract.label.toLowerCase()}, and do not turn this wounded shoulder into a greedier second push.`
        : civilianEvacLive
        ? `${focusedCivilianIncident.label} is still paying a brief escort window while the curb van and cellar note are both live. ${settlementRiskLine} Keep the house mouth calm, move the family cleanly, and protect ${focusedExtract.label.toLowerCase()} before the block turns into a panic peel.`
        : bunkerFootholdLive
        ? `${focusedBunkerFootholdIncident.label} is paying now and the bunker mouth is still only half-reseated. ${settlementRiskLine} ${
            bunkerFootholdSupportStillOwnsLane
              ? bunkerFootholdDeepRoomStillLive
                ? "The support gun still owns the freight lip and the back room is still live, so cut that belt first, then keep the bunker mouth quiet and protect"
                : "The support gun still owns the freight lip, so cut that belt first, then keep the bunker mouth quiet and protect"
              : bunkerFootholdCompressedLive && bunkerFootholdDeepRoomStillLive
                ? "The bunker pocket is compressing inward, so keep the mouth quiet, clear the back room, and protect"
                : "Keep the bunker mouth quiet and protect"
          } ${focusedExtract.label.toLowerCase()} before the freight lane turns back into a long reset trap.`
        : dishHouseBreachLive
        ? focusedDishHouseSquad?.crossingDangerReduced
          ? `${focusedDishHouseIncident.label} is paying now and the first door is still only half-reseated. ${settlementRiskLine} ${
              dishHouseCompressionLive
                ? dishHouseDeepRoomStillLive
                  ? "The support gun is already off the lane and the building is compressing, so keep the SMG flood inside room one, turn room two, and protect"
                  : "The support gun is already off the lane and the building is compressing, so finish the deeper reset and protect"
                : "The support gun is already off the lane, so keep the SMG flood inside the rooms, let the shotgun own the hard corner, and protect"
            } ${focusedExtract.label.toLowerCase()} before the reserve shove rebuilds the block.`
          : `${focusedDishHouseIncident.label} is paying now and the first door is still only half-reseated. ${settlementRiskLine} The lane gun still owns the crossing, so cut that belt first, then keep the SMG flood inside the rooms and protect ${focusedExtract.label.toLowerCase()} before the reserve shove turns the block back into a long relay lane.`
        : coveringCrossingLive
        ? `${focusedCoveringCrossingIncident.label} is paying now and the antenna ditch is still bent just enough for a disciplined cross. ${settlementRiskLine} Keep one body braced, let the moving-cover gun walk the lane, and protect ${focusedExtract.label.toLowerCase()} before the reserve resets the cut into another static duel.`
        : cellarCounterholdLive
        ? `${focusedCellarIncident.label} is paying now and the cellar mouth is still screened just well enough to bank a steadier route note. ${settlementRiskLine} ${
            cellarCompressedLive && cellarDeepRoomStillLive
              ? `Keep the concrete mouth quiet, turn the back room, stop the reserve shove from reopening the relay cellar, and protect ${focusedExtract.label.toLowerCase()} before the hold collapses back into the dish lane.`
              : `Keep the concrete mouth quiet, stop the reserve shove from reopening the relay cellar, and protect ${focusedExtract.label.toLowerCase()} before the hold collapses back into the dish lane.`
          }`
        : shedHideLive
        ? `${focusedHideIncident.label} is paying now and the sweep has not fully sealed the village lip yet. ${settlementRiskLine} Stay dark, let Blue overshoot the slit, and protect ${focusedExtract.label.toLowerCase()} before one bad sound turns the peel into a panic exit.`
        : mortarBracketLive
        ? `${focusedMortarBracketIncident.label} is paying now and the tube team has not fully settled the walk onto the strip yet. ${settlementRiskLine} Break the tube cleanly, keep the underpass peel viable, and protect ${focusedExtract.label.toLowerCase()} before the next bracket turns Ambulance Mile into a panic exit.`
        : droneSweepLive
        ? `${focusedDroneSweepIncident.label} is paying now and the spotter eye has not fixed the relay cut yet. ${settlementRiskLine} Stay under the hedge, steal the route board cleanly, and protect ${focusedExtract.label.toLowerCase()} before the next sweep pass turns this into a panicked peel.`
        : hostileLaneChatterLive
        ? `${focusedHostileChatterIncident.label} is paying now and the dock tape net has not unified yet. ${settlementRiskLine} Read the shouting, cut the loudest caller cleanly, and protect ${focusedExtract.label.toLowerCase()} before the whole crane lane moves on one command.`
        : caravanTrapLive
        ? `${focusedCaravanTrapIncident.label} is paying now and the burning wagons are still choking the road. ${settlementRiskLine} Strip the loose haul cleanly, own the berm, and protect ${focusedExtract.label.toLowerCase()} before the kill zone resets into a second volley lane.`
        : armoredDropLive
        ? `${focusedArmoredDropIncident.label} is paying now and the wagon is still dumping bodies into the relay berm instead of holding it. ${settlementRiskLine} Keep the ramp mouth broken, strip the spill kit cleanly, and protect ${focusedExtract.label.toLowerCase()} before the drop hardens into a fresh pocket.`
        : whiteVanAmbushLive
        ? `${focusedStripIncident.label} is paying now and the relay verge is still only half-screened. ${settlementRiskLine} Keep the van mouth controlled, strip the comms kit cleanly, and protect ${focusedExtract.label.toLowerCase()} before the reserve lane turns this into a panic peel.`
        : `The first pocket is paying out and the pull is still readable. ${settlementRiskLine} Keep the next fight controlled so ${focusedExtract.label} stays a decision instead of a panic exit.`,
      compact: `Gain | ${noiseRead.title} | ${extractCleanlinessLabel}${ownershipLabel ? ` | ${ownershipLabel}` : ""}`,
      tone: noiseRead.tone === "critical" ? "warning" : "steady",
      ownershipLabel
    };
  }

  return {
    phase,
    phaseLabel,
    pressureScore,
    pressureLabel: `${pressureScore.toFixed(0)} pressure`,
    settlementLabel: settlementRead.label,
    settlementVolatilityLabel: settlementRead.volatilityLabel,
    settlementExtractRisk: settlementRead.extractRisk,
    settlementPressurePenalty,
    exitIntent,
    exitIntentLabel,
    extractCleanliness,
    extractCleanlinessLabel,
    focusedExtractLabel: focusedExtract.label,
    crashWaveReadiness,
    title: "APPROACH WINDOW",
    status: `${settlementStatus} | ${noiseRead.title} | ${focusedExtract.label}${ownershipStatusSuffix}`,
    detail: `The raid is still opening. ${settlementRiskLine} Read the first lane, stage ${focusedExtract.label.toLowerCase()} as the likely pull, and do not spend the clean exit before the district proves the push is worth it.`,
    compact: `Approach | ${focusedExtract.label} | ${extractCleanlinessLabel}${ownershipLabel ? ` | ${ownershipLabel}` : ""}`,
    tone: "steady",
    ownershipLabel
  };
}

function getFrontlineControlLabel(control: FrontlineControl): string {
  if (control === "held") {
    return "Held ground";
  }

  if (control === "contested") {
    return "Contested district";
  }

  return "Lost district";
}

export function getFrontlineOperationRead(state: RaidState): FrontlineOperationRead {
  const route =
    RAID_ROUTES.find((candidate) => candidate.id === state.activeRouteId) ??
    RAID_ROUTES[0];
  const activeSector = state.frontlineSectors.find((sector) => sector.routeId === route.id) ?? null;
  const operationState =
    state.phase === "raid"
      ? state.activeFrontlineOperation
      : state.pendingFrontlineOperations.find((operation) => operation.routeId === route.id) ?? null;

  if (!operationState) {
    return {
      tone: "steady",
      title: "No sector order staged",
      status: `${route.name} | self-contained push`,
      detail: "Queue a district order from Campaign Fallout or the sector grid so stash planning carries a concrete opening edge into the next raid.",
      compact: `No order | ${route.name}`,
      operationLabel: "None staged",
      districtLabel: activeSector?.zoneLabel ?? route.name,
      effectLabel: "Baseline sector state",
      deployLabel: "Let the raid earn its own lane"
    ,
      live: false
    };
  }

  const definition = FRONTLINE_OPERATION_DEFINITIONS[operationState.operationId];
  const controlLabel = activeSector ? getFrontlineControlLabel(activeSector.control) : "Stand by";
  const districtLabel = activeSector?.zoneLabel ?? route.name;
  const live = state.phase === "raid";
  let tone: FrontlineOperationRead["tone"] =
    activeSector?.control === "lost" || (activeSector?.pressure ?? 0) >= 78
      ? "critical"
      : activeSector?.control === "contested" || (activeSector?.pressure ?? 0) >= 58
        ? "warning"
        : definition.id === "burner-coffee" || definition.id === "smuggle-cache"
          ? "support"
          : "steady";
  let deployLabel = "Deploy this district next so the staged support actually cashes into a cleaner opening.";
  let detail = `${definition.summary} ${definition.effectSummary}`;

  if (definition.id === "reinforce-pickets") {
    deployLabel = live
      ? "Win the first clash while the pickets are still thinning the opener."
      : "Hit first contact fast while the reinforced pickets are still thinning the opener.";
    detail = live
      ? `${definition.effectSummary} The opener should read thinner right now, so use it to own the first lane before Blue hardens again.`
      : `${definition.summary} ${definition.effectSummary}`;
  } else if (definition.id === "smuggle-cache") {
    deployLabel = live
      ? "Spend the buried reserve only after the route pays you a real pocket."
      : "Plan one greedier pocket only after the buried cache buys back sustain margin.";
    detail = live
      ? `${definition.effectSummary} The dead-ground reserve is what lets this raid take one greedier touch without instantly folding.`
      : `${definition.summary} ${definition.effectSummary}`;
    tone = tone === "steady" ? "support" : tone;
  } else if (definition.id === "mark-exfil") {
    deployLabel = live
      ? "Rotate toward the taped pull before greed turns the exit hot."
      : "Route the raid toward the taped pull early so the marked exfil lane actually matters.";
    detail = live
      ? `${definition.effectSummary} The taped exit is the point of this order, so keep the run bending toward a cleaner peel instead of wandering into a late collapse.`
      : `${definition.summary} ${definition.effectSummary}`;
  } else if (definition.id === "burner-coffee") {
    deployLabel = live
      ? "Take the warm reset on purpose and convert it into one sharper shove."
      : "Use the warm reset deliberately and spend the steadier hands on the ugly shove, not on idle looting.";
    detail = live
      ? `${definition.effectSummary} The coffee pocket only matters if you actually pause, settle, and cash that steadier window into a cleaner assault.`
      : `${definition.summary} ${definition.effectSummary}`;
    tone = tone === "steady" ? "support" : tone;
  } else if (definition.id === "recover-body") {
    deployLabel = live
      ? "Treat the first clean lane as a recovery corridor before it becomes a haul run."
      : "Re-enter this district ready to win the casualty corridor first and only then widen into greed.";
    detail = live
      ? `${definition.effectSummary} This raid is carrying body debt, so the correct read is recovery first, profit second, until the corridor is actually secured.`
      : `${definition.summary} ${definition.effectSummary}`;
    tone = "critical";
  }

  return {
    tone,
    title: live ? `${definition.title} live` : `${definition.title} staged`,
    status: `${districtLabel} | ${controlLabel}`,
    detail,
    compact: `${definition.title} | ${districtLabel}`,
    operationLabel: definition.title,
    districtLabel,
    effectLabel: definition.effectSummary,
    deployLabel,
    live
  };
}

