function getRouteDistrictMeta(routeId: RaidRouteId) {
  return TACTICAL_DISTRICT_BLUEPRINT.routes[routeId];
}

export function getActiveTacticalSubzoneRead(state: RaidState, routeId = state.activeRouteId): TacticalSubzoneRead {
  const route = RAID_ROUTES.find((candidate) => candidate.id === routeId) ?? RAID_ROUTES[0];
  const routeMeta = getRouteDistrictMeta(route.id);
  const extract =
    state.phase === "raid" && routeId === state.activeRouteId
      ? getFocusedExtractForState(state)
      : route.extractOptions[0] ?? route.extractZone;
  const extractDistance =
    state.phase === "raid" && routeId === state.activeRouteId
      ? distance(state.player.position, extract.position)
      : Number.POSITIVE_INFINITY;

  const chosenSubzone =
    routeMeta.subzones.find(
      (subzone) =>
        subzone.type === "extract-edge" &&
        (state.activeExtractId !== null || state.extractionHoldTimer > 0 || extractDistance <= extract.radius + 140)
    ) ??
    routeMeta.subzones.reduce((best, subzone) => {
      if (!best) {
        return subzone;
      }

      const bestDistance =
        state.phase === "raid" && routeId === state.activeRouteId
          ? distance(state.player.position, best.anchor)
          : Number.POSITIVE_INFINITY;
      const subzoneDistance =
        state.phase === "raid" && routeId === state.activeRouteId
          ? distance(state.player.position, subzone.anchor)
          : Number.POSITIVE_INFINITY;

      return subzoneDistance < bestDistance ? subzone : best;
    }, routeMeta.subzones[0]);

  return {
    id: chosenSubzone.id,
    districtId: TACTICAL_DISTRICT_BLUEPRINT.id,
    routeId: route.id,
    label: chosenSubzone.label,
    type: chosenSubzone.type,
    typeLabel: getTacticalSubzoneTypeLabel(chosenSubzone.type),
    detail: chosenSubzone.detail
  };
}

export function getSettlementStateRead(state: RaidState, routeId = state.activeRouteId): SettlementStateRead {
  const route = RAID_ROUTES.find((candidate) => candidate.id === routeId) ?? RAID_ROUTES[0];
  const routeMeta = getRouteDistrictMeta(route.id);
  const trenchLineSettlement = routeMeta.settlementType === "trench-line";
  const sector =
    state.frontlineSectors.find((candidate) => candidate.routeId === route.id) ??
    state.frontlineSectors[0] ?? {
      routeId: route.id,
      routeName: route.name,
      zoneLabel: route.name,
      control: "contested" as FrontlineControl,
      pressure: 50,
      fortification: 50,
      scars: 40,
      routeModifierTitle: "Baseline route",
      routeModifierSummary: route.briefing,
      enemyReduction: 0,
      extractionHoldMultiplier: 1,
      noiseMultiplier: 1,
      activeEvent: route.briefing,
      supportNeed: "No settlement state available yet.",
      watch: "Stand by for live route contact.",
      lastOutcome: "No route state logged yet.",
      lastRaidResult: "standby" as const,
      settlementMemoryTags: [],
      lastMeaningfulShiftCycle: 0,
      fallenSquadBodies: [],
      fallenEnemyBodies: []
    };
  const routeIncidents =
    state.phase === "raid" && route.id === state.activeRouteId
      ? state.frontlineIncidents
      : [];
  const territorialIncidents = routeIncidents.filter(
    (incident) => incident.kind === "firefight" || incident.kind === "casualty"
  );
  const casualtyCorridorOpen = routeIncidents.some(
    (incident) => incident.kind === "casualty" && incident.resolved === false
  );
  const convoyHit = routeIncidents.some(
    (incident) => incident.kind === "convoy" && incident.resolved === false
  );
  const reclaimedCount = territorialIncidents.filter((incident) => incident.territoryState === "reclaimed").length;
  const breakingCount = territorialIncidents.filter(
    (incident) => incident.territoryState === "breaking" || incident.markerState === "raising"
  ).length;
  const lostCount = territorialIncidents.filter(
    (incident) => incident.territoryState === "lost" || incident.markerState === "bagged"
  ).length;
  const volatility: SettlementVolatilityState =
    breakingCount > 0
      ? "breaking"
      : reclaimedCount > 0 && sector.control !== "held"
        ? "reclaiming"
        : sector.lastRaidResult === "failed" || sector.control !== "held" || lostCount > 0
          ? "fragile"
          : "stable";
  const controlLabel = getFrontlineControlLabel(sector.control);
  const volatilityLabel = getSettlementVolatilityLabel(volatility);
  const tone: SettlementStateRead["tone"] =
    volatility === "breaking" || sector.control === "lost"
      ? "critical"
      : volatility === "reclaiming" || volatility === "fragile" || sector.control === "contested"
        ? "warning"
        : "steady";
  const liveMemoryTags = [
    ...(routeIncidents.some((incident) => incident.markerState === "planted") ? ["flag-planted"] : []),
    ...(breakingCount > 0 ? ["claim-breaking"] : []),
    ...(routeIncidents.some((incident) => incident.territoryState === "lost") ? ["town-lost"] : []),
    ...(reclaimedCount > 0 ? ["town-reclaimed"] : []),
    ...(casualtyCorridorOpen ? ["casualty-corridor-open"] : []),
    ...(convoyHit ? ["convoy-hit"] : []),
    ...(sector.fallenSquadBodies.length > 0 ? ["body-left-behind"] : []),
    ...(routeIncidents.some((incident) => incident.markerState === "bagged") ? ["body-recovered"] : []),
    ...(routeIncidents.some((incident) => incident.status === "routed" && incident.territoryState === "reclaimed")
      ? ["surrender-pocket"]
      : [])
  ];
  const memoryTags = mergeUniqueStrings([...(sector.settlementMemoryTags ?? []), ...liveMemoryTags]);
  const activeSituationIds = getSettlementSituationIds(routeMeta.settlementType, sector.control, volatility, memoryTags);
  const shiftReason =
    breakingCount > 0
      ? trenchLineSettlement
        ? "One trench scar is still half-locked and can reopen the whole strip if the tape dies."
        : "Flag teams are still trying to lock the scar."
      : reclaimedCount > 0
        ? trenchLineSettlement
          ? "Friendlies pushed back onto the trench lip and turned it into shaky cover instead of a solved hold."
          : "Friendlies pushed back onto the pocket and turned it into shaky cover."
        : lostCount > 0
          ? trenchLineSettlement
            ? "At least one trench strip is memorial ground until a later counterhold."
            : "At least one strip is memorial ground until a later retake."
          : sector.lastRaidResult === "success"
            ? trenchLineSettlement
              ? "The last raid bought one temporary trench hold that still needs a clinic-side follow-through."
              : "The last raid bought a temporary hold that still needs follow-through."
            : sector.lastRaidResult === "failed"
            ? trenchLineSettlement
              ? "The last raid bled the trench hold and left the med lane easier to pry back open."
              : "The last raid hurt the hold and left the district easier to pry open."
            : "The settlement is waiting for a real push before it changes tone.";
  const bodyDebtActive = sector.fallenSquadBodies.length > 0;
  const tacticalProblem =
    volatility === "breaking"
      ? trenchLineSettlement
        ? "A live trench claim is still hanging on the lip."
        : "A live claim is still hanging in the lane."
      : volatility === "reclaiming"
        ? trenchLineSettlement
          ? "Blue has been bent off one trench strip, but the lip is not actually owned yet."
          : "Blue has been bent, but the pocket is not actually owned yet."
        : sector.control === "lost"
          ? trenchLineSettlement
            ? "The trench line is acting like lost ground and the first lip has to be won again."
            : "The settlement is acting like lost ground and the first foothold has to be won again."
          : bodyDebtActive
            ? "Missing-body debt is bending the route into a recovery-first raid."
            : volatility === "fragile"
              ? trenchLineSettlement
                ? "The hold is thin enough that one bad trench lane reopens the whole strip."
                : "The hold is thin enough that one bad lane reopens the whole block."
              : "The district is currently stable enough to treat the route like a proper push.";
  const tacticalPlan =
    volatility === "breaking"
      ? trenchLineSettlement
        ? "Screen the active trench claim, finish the planted scar, and do not widen into greed until the lip locks."
        : "Screen the active flag team, finish the planted scar, and do not widen into greed until the lane locks."
      : volatility === "reclaiming"
        ? trenchLineSettlement
          ? "Cross while the trench claim is still bending in your favor, then turn the first reclaimed lip into cover before the reserve file lands."
          : "Cross while the claim is still bending in your favor, then turn the first reclaimed strip into cover before the reserve file lands."
        : sector.control === "lost"
          ? "Buy one foothold with suppression, grenades, and a short room or trench shove instead of trying to clear the whole district at once."
          : bodyDebtActive
            ? "Treat the cleanest lane as a drag corridor first, then decide whether the route can afford a second pocket."
            : volatility === "fragile"
              ? trenchLineSettlement
                ? "Hold the med-lane lip, keep the squad tight on the first trench crossing, and leave before the district gets another chance to pry the strip open."
                : "Hold the best pocket, keep the squad tight on the first crossing, and leave before the district gets another chance to pry the block open."
              : "Use the current hold to press one meaningful pocket, bank the gain, and leave before stability turns into false confidence.";
  const extractRisk =
    sector.control === "lost"
      ? "Late extracts get uglier because Blue still owns the wider settlement and can fold back over the peel."
      : volatility === "breaking"
        ? trenchLineSettlement
          ? "If the trench claim is left half-finished, the same peel comes home hotter and less screenable."
          : "If the claim is left half-finished, the same extract lane comes home hotter and less screenable."
        : volatility === "reclaiming"
          ? trenchLineSettlement
            ? "The route can still peel clean, but only if the first reclaimed trench strip is secured before the reserve resets the lane."
            : "The route can still peel clean, but only if the first reclaimed strip is secured before the reserve resets the lane."
          : bodyDebtActive
            ? "Extraction should be treated like a recovery peel, not a profit jog, until the memorial debt is physically off the route."
            : volatility === "fragile"
              ? trenchLineSettlement
                ? "The trench line still punishes greed, so the clean extract window closes faster than the labels imply."
                : "The district still punishes greed, so the clean extract window closes faster than the labels imply."
              : "The current hold buys a cleaner peel, but only if the squad banks the route before pressure spikes again.";

  return {
    id: routeMeta.settlementId,
    routeId: route.id,
    districtId: TACTICAL_DISTRICT_BLUEPRINT.id,
    label: routeMeta.settlementLabel,
    type: routeMeta.settlementType,
    control: sector.control,
    controlLabel,
    volatility,
    volatilityLabel,
    pressureLabel: `${sector.pressure}% pressure | ${getSettlementTypeLabel(routeMeta.settlementType)}`,
    shiftReason,
    detail: `${sector.lastOutcome} ${shiftReason} ${sector.watch}`,
    tacticalProblem,
    tacticalPlan,
    extractRisk,
    memoryTags,
    activeSituationIds,
    lastMeaningfulShiftCycle: sector.lastMeaningfulShiftCycle,
    tone
  };
}

export function getPressurePostureRead(state: RaidState): PressurePostureRead {
  const activeSubzone = getActiveTacticalSubzoneRead(state);
  const trenchLineActive = activeSubzone.type === "trench-line";
  const focusedIncident =
    state.phase === "raid"
      ? state.frontlineIncidents.find((incident) => incident.id === state.focusedFrontlineIncidentId) ??
        state.frontlineIncidents.find((incident) => incident.kind === "firefight") ??
        null
      : null;
  const nearbyPressuredEnemies =
    state.phase === "raid"
      ? state.enemies.filter(
          (enemy) =>
            (enemy.pressureType === "suppressed" || enemy.pressureType === "pinned") &&
            distance(enemy.position, state.player.position) <= 320
        ).length
      : 0;
  const nearbyPinnedCount =
    state.phase === "raid"
      ? state.enemies.filter(
          (enemy) => enemy.pressureType === "pinned" && distance(enemy.position, state.player.position) <= 320
        ).length
      : 0;
  const nearbySuppressedCount =
    state.phase === "raid"
      ? state.enemies.filter(
          (enemy) => enemy.pressureType === "suppressed" && distance(enemy.position, state.player.position) <= 320
        ).length
      : 0;
  const nearbyPinnedMachineGunners =
    state.phase === "raid"
      ? state.enemies.filter(
          (enemy) =>
            enemy.weaponId === "pkm" &&
            enemy.casualtyState !== "downed" &&
            enemy.casualtyState !== "dead" &&
            (enemy.pressureType === "suppressed" || enemy.pressureType === "pinned") &&
            distance(enemy.position, state.player.position) <= 360
        )
      : [];
  const nearbyPinnedMachineGunnerCount = nearbyPinnedMachineGunners.length;
  const primaryPinnedMachineGunner = nearbyPinnedMachineGunners[0] ?? null;
  const pinnedMachineGunLabel =
    state.phase === "raid" && nearbyPinnedMachineGunnerCount > 0
      ? primaryPinnedMachineGunner?.supportStrongpointLabel
        ? `${primaryPinnedMachineGunner.supportStrongpointLabel}${primaryPinnedMachineGunner.supportLaneLabel ? ` ${primaryPinnedMachineGunner.supportLaneLabel}` : ""}`
        : getClosestLabeledObstacleForState(state, nearbyPinnedMachineGunners[0].position, 220)?.label ??
        focusedIncident?.label ??
        "the lane"
      : null;
  const pressuredWindowSeconds =
    state.phase === "raid"
      ? state.enemies
          .filter(
            (enemy) =>
              (enemy.pressureType === "suppressed" || enemy.pressureType === "pinned") &&
              distance(enemy.position, state.player.position) <= 320 &&
              enemy.pressureTimer > 0.05
          )
          .reduce<number | null>(
            (best, enemy) => (best === null ? enemy.pressureTimer : Math.min(best, enemy.pressureTimer)),
            null
          )
      : null;
  const reserveSeconds =
    state.pendingReinforcements.length > 0
      ? state.pendingReinforcements.reduce<number | null>(
          (best, reinforcement) => (best === null ? reinforcement.timer : Math.min(best, reinforcement.timer)),
          null
        )
      : null;
  const focusedCasualtyIncident =
    focusedIncident?.kind === "casualty" && !focusedIncident.resolved ? focusedIncident : null;
  const focusedCivilianIncident =
    focusedIncident?.kind === "civilian" && !focusedIncident.resolved ? focusedIncident : null;
  const focusedHunterIncident =
    focusedCivilianIncident?.presentationVariant === "hunter-search" ? focusedCivilianIncident : null;
  const focusedDishHouseIncident =
    focusedIncident?.kind === "firefight" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "dish-house-breach"
      ? focusedIncident
      : null;
  const focusedBunkerFootholdIncident =
    focusedIncident?.kind === "bunker" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "bunker-foothold"
      ? focusedIncident
      : null;
  const focusedAmrCounterLaneIncident =
    focusedIncident?.kind === "firefight" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "amr-counter-lane"
      ? focusedIncident
      : null;
  const focusedCoveringCrossingIncident =
    focusedIncident?.kind === "firefight" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "covering-crossing"
      ? focusedIncident
      : null;
  const focusedWoundedSoldierIncident =
    focusedIncident?.kind === "firefight" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "wounded-soldier"
      ? focusedIncident
      : null;
  const focusedDroneSweepIncident =
    focusedIncident?.kind === "firefight" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "drone-sweep"
      ? focusedIncident
      : null;
  const focusedHostileChatterIncident =
    focusedIncident?.kind === "firefight" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "hostile-lane-chatter"
      ? focusedIncident
      : null;
  const focusedMortarBracketIncident =
    focusedIncident?.kind === "firefight" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "mortar-bracket"
      ? focusedIncident
      : null;
  const focusedStripIncident =
    focusedIncident?.kind === "convoy" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "white-van-ambush"
      ? focusedIncident
      : null;
  const focusedArmoredDropIncident =
    focusedIncident?.kind === "convoy" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "armored-drop"
      ? focusedIncident
      : null;
  const focusedCaravanTrapIncident =
    focusedIncident?.kind === "convoy" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "caravan-trap"
      ? focusedIncident
      : null;
  const focusedCellarIncident =
    focusedIncident?.kind === "bunker" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "cellar-counterhold"
      ? focusedIncident
      : null;
  const focusedHideIncident =
    focusedIncident?.kind === "bunker" &&
    !focusedIncident.resolved &&
    focusedIncident.presentationVariant === "shed-hide"
      ? focusedIncident
      : null;
  const armoredEvacLive =
    focusedCasualtyIncident !== null &&
    state.frontlineIncidents.some(
      (incident) =>
        incident.kind === "convoy" &&
        !incident.resolved &&
        incident.status === "extracting" &&
        distance(incident.position, focusedCasualtyIncident.position) <= 180
    );
  const focusedDishHouseSquad =
    focusedDishHouseIncident !== null ? getFocusedEnemySquadRead(state, focusedDishHouseIncident.position, 220) : null;
  const focusedBunkerFootholdSquad =
    focusedBunkerFootholdIncident !== null
      ? getFocusedEnemySquadRead(state, focusedBunkerFootholdIncident.position, 220)
      : null;
  const focusedCellarSquad =
    focusedCellarIncident !== null ? getFocusedEnemySquadRead(state, focusedCellarIncident.position, 220) : null;
  const dishHouseRolePayoffSquad =
    focusedDishHouseIncident !== null
      ? focusedDishHouseSquad ?? getNearestDegradedEnemySquadRead(state, focusedDishHouseIncident.position)
      : null;
  const activeSector =
    state.frontlineSectors.find((sector) => sector.routeId === state.activeRouteId) ?? null;
  const focusedDishHouseCompressedCount =
    focusedDishHouseIncident !== null
      ? state.enemies.filter(
          (enemy) =>
            enemy.casualtyState !== "downed" &&
            enemy.casualtyState !== "dead" &&
            enemy.compressionState !== "idle" &&
            distance(enemy.position, focusedDishHouseIncident.position) <= 220
        ).length
      : 0;
  const dishHouseCompressionLive = focusedDishHouseCompressedCount >= 2;
  const dishHouseDeepRoomStillLive =
    dishHouseRolePayoffSquad !== null && !dishHouseRolePayoffSquad.secondRoomSoftened;
  const bunkerFootholdCompressionCount =
    focusedBunkerFootholdIncident !== null
      ? state.enemies.filter(
          (enemy) =>
            enemy.casualtyState !== "downed" &&
            enemy.casualtyState !== "dead" &&
            enemy.compressionState !== "idle" &&
            distance(enemy.position, focusedBunkerFootholdIncident.position) <= 220
        ).length
      : 0;
  const bunkerFootholdCompressedLive = bunkerFootholdCompressionCount >= 2;
  const bunkerFootholdDeepRoomStillLive =
    focusedBunkerFootholdSquad !== null && !focusedBunkerFootholdSquad.secondRoomSoftened;
  const bunkerFootholdSupportStillOwnsLane =
    focusedBunkerFootholdSquad !== null && !focusedBunkerFootholdSquad.crossingDangerReduced;
  const cellarCompressedCount =
    focusedCellarIncident !== null
      ? state.enemies.filter(
          (enemy) =>
            enemy.casualtyState !== "downed" &&
            enemy.casualtyState !== "dead" &&
            enemy.compressionState !== "idle" &&
            distance(enemy.position, focusedCellarIncident.position) <= 220
        ).length
      : 0;
  const cellarCompressedLive = cellarCompressedCount >= 2;
  const cellarDeepRoomStillLive = focusedCellarSquad !== null && !focusedCellarSquad.secondRoomSoftened;
  const roomClearShowcaseLive =
    activeSector?.routeModifierTitle === "Authored three-room clear stack" &&
    state.player.frontlineMomentumTimer > 0;
  const roomClearCompressedCount = state.enemies.filter(
    (enemy) =>
      enemy.casualtyState !== "downed" &&
      enemy.casualtyState !== "dead" &&
      enemy.compressionState !== "idle" &&
      distance(enemy.position, state.player.position) <= 280
  ).length;
  const roomClearCompressedLive = roomClearCompressedCount >= 2;
  const postureOwnershipFocusPosition =
    focusedIncident?.position ??
    primaryPinnedMachineGunner?.position ??
    state.player.position;
  const focusedOwnershipRead =
    state.phase === "raid" ? getFocusedEnemySquadOwnershipRead(state, postureOwnershipFocusPosition, 240) : null;
  const ownershipLabel = focusedOwnershipRead?.ownershipLabel ?? null;
  const ownershipStatusLabel = focusedOwnershipRead?.statusLabel ?? null;

  let posture: PressurePosture = "holding";
  let detail = "The district is still in a hold-versus-hold read with no lane fully broken yet.";
  let tone: PressurePostureRead["tone"] = "steady";
  let actionLabel = "Probe the lane";
  let windowLabel = nearbyPressuredEnemies > 0 ? "Pressure window open" : "No crossing window";
  let threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "No reserve leaning";

  if (roomClearShowcaseLive) {
    posture = "holding";
    detail = roomClearCompressedLive
      ? "The room-clear stack is paying, but the defenders have compressed inward and room two is still live, so the fight is about owning room one, turning the second room, and refusing to let the reserve shove reset the whole building."
      : "The room-clear stack is paying, but the deeper rooms are still unsettled, so the fight is about holding room one and finishing the next doorway before the reserve shove resets the building.";
    tone = "critical";
    actionLabel = roomClearCompressedLive ? "Cross, own room one, turn room two" : "Hold room one, finish the stack";
    windowLabel = roomClearCompressedLive ? "Building compressed | room two live" : "Room stack still live";
    threatLabel = roomClearCompressedLive ? "First room won | room two still live" : "Deeper rooms still unsettled";
  } else if (focusedBunkerFootholdIncident !== null) {
    posture = "holding";
    detail = bunkerFootholdSupportStillOwnsLane
      ? "The freight bunker is only stable while the support gun still owns the lip, so the fight is about killing that belt, holding the concrete mouth, and refusing to let the bunker reset become another exposed crossing."
      : bunkerFootholdCompressedLive && bunkerFootholdDeepRoomStillLive
        ? "The freight bunker pocket is compressing inward and the back room is still live, so the fight is about owning the concrete mouth and clearing the deeper pocket before the lane reheats."
        : "The freight bunker pocket is still live, so the fight is about owning the concrete mouth and banking the reset before the freight lane wakes back up.";
    tone = "warning";
    actionLabel = bunkerFootholdSupportStillOwnsLane ? "Kill the lip gun first" : "Own the mouth, clear the back room";
    windowLabel = bunkerFootholdSupportStillOwnsLane
      ? "Support gun owns freight lip"
      : bunkerFootholdCompressedLive
        ? "Bunker compressed | back room live"
        : "Concrete foothold live";
    threatLabel = bunkerFootholdDeepRoomStillLive ? "Back room still live" : "Bunker reset still fragile";
  } else if (focusedHunterIncident !== null) {
    posture = "recovering";
    detail =
      "The old hunter is still exposed in the reeds, so the fight is about screening the shack mouth, guiding him off the lane, and banking the son's route note before Blue closes the treeline.";
    tone = "warning";
    actionLabel = "Guide the hunter off the reeds";
    windowLabel = "Search lane live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Shack mouth still exposed";
  } else if (focusedAmrCounterLaneIncident !== null) {
    posture = "holding";
    detail =
      "A plated relay owner is still freezing Dish Houses from the outer lane, so the fight is about bracing one deliberate AMR shot, deleting the anchor, and flooding the crack before the reserve reseats the block.";
    tone = "critical";
    actionLabel = "Break the plated anchor first";
    windowLabel = "Plate-break window live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Repeek still plated";
  } else if (focusedCoveringCrossingIncident !== null) {
    posture = "holding";
    detail =
      "The antenna ditch is finally bent into a real crossing problem, so the fight is about planting one boy on the brace lane, walking one gun through moving cover, and crossing the cut before the reserve resets the relay mouth.";
    tone = "critical";
    actionLabel = "Cross under moving cover";
    windowLabel = "Covering-cross window live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Brace lane still exposed";
  } else if (focusedDishHouseIncident !== null) {
    detail =
      dishHouseRolePayoffSquad?.crossingDangerReduced
        ? dishHouseCompressionLive
          ? dishHouseDeepRoomStillLive
            ? "Dish Houses is live as a close room-take and the belt is already off the lane, but the building has compressed inward and room two is still live, so the fight is about crossing now, owning room one, and turning the second room before the reserve shove resets the stack."
            : "Dish Houses is live as a close room-take and the belt is already off the lane, but the building has compressed inward, so the fight is about crossing now and finishing the deeper reset before the reserve shove rebuilds the stack."
          : "Dish Houses is live as a close room-take and the belt is already off the lane, so the fight is about crossing now, flooding the first doorway, and refusing to let the reserve shove rebuild the outside pressure."
        : dishHouseCompressionLive
          ? "Dish Houses is live as a close room-take, but the lane gun still owns the crossing while the building compresses inward, so the fight is about killing that belt first and refusing to let room two become the real hold."
          : "Dish Houses is live as a close room-take, so the fight is about flooding the first doorway, keeping one yard lid on the outside angle, and refusing to let the reserve shove turn the block back into a long relay lane.";
    tone = "warning";
    actionLabel = dishHouseRolePayoffSquad?.crossingDangerReduced
      ? dishHouseDeepRoomStillLive
        ? "Cross, own room one, turn room two"
        : "Cross and finish the stack"
      : "Kill the lane gun first";
    windowLabel = dishHouseRolePayoffSquad?.crossingDangerReduced
      ? dishHouseCompressionLive
        ? dishHouseDeepRoomStillLive
          ? "Building compressed | room two live"
          : "Building compressed | deeper reset live"
        : "Belt down | crossing softer"
      : "Lane gun owns crossing";
    threatLabel = dishHouseRolePayoffSquad?.firstThresholdSoftened
      ? dishHouseDeepRoomStillLive
        ? "First room won | room two still live"
        : reserveSeconds !== null
          ? `Reserve in ${reserveSeconds.toFixed(1)}s`
          : "Threshold softened"
      : dishHouseCompressionLive
        ? "Building compressed deeper"
        : reserveSeconds !== null
          ? `Reserve in ${reserveSeconds.toFixed(1)}s`
          : "Yard lid still exposed";
  } else if (focusedDroneSweepIncident !== null) {
    posture = "holding";
    detail =
      "The spotter eye is still hanging over the relay cut, so the fight is about staying low under the hedge, ripping the route board fast, and slipping the boys out before the next sweep pass fixes the whole lane.";
    tone = "warning";
    actionLabel = "Stay low until the board is bagged";
    windowLabel = "Drone sweep live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Tripod board still exposed";
  } else if (focusedMortarBracketIncident !== null) {
    posture = "reinforcing";
    detail =
      "The tube team is still walking brackets over Ambulance Mile, so the fight is about breaking the clinic cut fast, killing the tube before the next walk lands, and keeping the underpass peel alive behind the strip.";
    tone = "critical";
    actionLabel = "Break the tube before next bracket";
    windowLabel = "Bracket walk live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Tube team still walking fire";
  } else if (focusedHostileChatterIncident !== null) {
    posture = "holding";
    detail =
      "Blue, Green, and Yellow tape are all shouting over the same dock cut, so the fight is about reading who is calling the lane, killing the loudest mouth first, and keeping the gantry peel from inheriting the whole district.";
    tone = "warning";
    actionLabel = "Cut the loudest tape first";
    windowLabel = "Tape lane arguing";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Three tape calls live";
  } else if (focusedCivilianIncident !== null) {
    posture = "recovering";
    detail =
      "Civilians are still pinned in the block and the lane is only worth as much as the escort discipline holding the van curb, cellar mouth, and the first peel together.";
    tone = "warning";
    actionLabel = "Walk the family to the van";
    windowLabel = "Escort lane live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Cellar curb still exposed";
  } else if (focusedWoundedSoldierIncident !== null) {
    posture = "recovering";
    detail =
      "One wounded squadmate is still holding the shoulder, so the fight is about stitching her lane, screening the split, and refusing any extra angle that could turn a stabilized wound into a collapse peel.";
    tone = "warning";
    actionLabel = "Keep Yara on the line";
    windowLabel = "Wounded shoulder live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Next bad trade drops the medic";
  } else if (focusedCellarIncident !== null) {
    posture = "holding";
    detail = cellarCompressedLive && cellarDeepRoomStillLive
      ? "The relay cellar is the only real foothold in this push and the reserve file has already compressed inward, so the fight is about holding the mouth, turning the back room, and refusing the shove outside."
      : "The relay cellar is the only real foothold in this push, so the fight is about holding the mouth, banking the route note, and refusing the reserve shove outside.";
    tone = "warning";
    actionLabel = cellarCompressedLive && cellarDeepRoomStillLive ? "Hold the mouth, turn the back room" : "Hold the cellar mouth";
    windowLabel = cellarCompressedLive ? "Cellar compressed | back room live" : "Concrete foothold live";
    threatLabel = cellarDeepRoomStillLive
      ? "Back room still live"
      : reserveSeconds !== null
        ? `Reserve in ${reserveSeconds.toFixed(1)}s`
        : "Reserve lane still probing";
  } else if (focusedHideIncident !== null) {
    posture = "holding";
    detail =
      "The shed is the only quiet pocket left in the village sweep, so the fight is about staying dark, counting the Blue boots, and slipping the boys back into the lane only after the search line overshoots.";
    tone = "warning";
    actionLabel = "Stay dark in the shed";
    windowLabel = "Hide window live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Sweep line still overhead";
  } else if (focusedArmoredDropIncident !== null) {
    posture = "reinforcing";
    detail =
      "The armored wagon is still vomiting fresh bodies into the relay berm, so the fight is about crashing the ramp, stealing the spill kit, and refusing the new foothold before it hardens.";
    tone = "critical";
    actionLabel = "Crash the ramp before dismount";
    windowLabel = "Ramp kill lane live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Dismount stack still spilling";
  } else if (focusedCaravanTrapIncident !== null) {
    posture = "reinforcing";
    detail =
      "The road is still a burning convoy graveyard, so the fight is about owning the berm, ripping loose haul out of the kill zone, and leaving before Blue brackets the wreck mouths again.";
    tone = "critical";
    actionLabel = "Strip the kill zone fast";
    windowLabel = "Ammo cookoff live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Second volley still forming";
  } else if (state.activeRescueTask || state.activeSquadBodyRecovery || focusedIncident?.kind === "casualty") {
    posture = "recovering";
    detail = armoredEvacLive
      ? "Bodies or casualties are bending the lane while a Blue evac wagon is trying to swallow the same strip, so the fight is about breaking the load mouth and holding the recovery corridor."
      : "Bodies or casualties are bending the lane, so the fight is about holding the recovery corridor instead of only winning the pocket.";
    tone = "warning";
    actionLabel = armoredEvacLive ? "Break the wagon lane" : "Hold the recovery corridor";
    windowLabel = "Recovery lane live";
    threatLabel =
      reserveSeconds !== null
        ? `Reserve in ${reserveSeconds.toFixed(1)}s`
        : armoredEvacLive
          ? "Wagon load still exposed"
          : "Casualty drag still exposed";
  } else if (
    focusedIncident?.status === "routed" &&
    focusedIncident.territoryState === "reclaimed"
  ) {
    posture = "surrendering";
    detail = "The pocket is routed and the ground is nearly yours, so the correct follow-through is force the surrender and lock the scar.";
    tone = "warning";
    actionLabel = "Close the surrender pocket";
    windowLabel = "Pocket already routed";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Ground almost owned";
  } else if (focusedIncident?.status === "collapsing") {
    posture = "collapsing";
    detail = "The pocket is half-held and one more shove decides whether this becomes owned ground or a wiped strip.";
    tone = "critical";
    actionLabel = "Shove before the pocket resets";
    windowLabel = pressuredWindowSeconds !== null ? `${pressuredWindowSeconds.toFixed(1)}s collapse window` : "Collapse window live";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Last shove decides the strip";
  } else if (focusedIncident?.status === "engaged" && nearbyPressuredEnemies > 0) {
    posture = "pinned";
    detail =
      nearbyPinnedMachineGunnerCount > 0
        ? primaryPinnedMachineGunner?.supportStrongpointTier === "must-own"
          ? `A PKM owns ${pinnedMachineGunLabel ?? "the lane"} and is stapling the crossing, so the route does not really open until you break the gun or solve the structure.`
          : `A PKM is stitching ${pinnedMachineGunLabel ?? "the lane"} and keeping heads down, so this is the moment to cross, frag, or break the gun before the belt settles back in.`
        : "Suppression is already changing how the defenders peek, so this is the moment to cross, frag, or finish the room properly.";
    tone = "warning";
    actionLabel = "Cross now";
    windowLabel =
      nearbyPinnedMachineGunnerCount > 0
        ? pressuredWindowSeconds !== null
          ? `${pressuredWindowSeconds.toFixed(1)}s PKM lane window`
          : primaryPinnedMachineGunner?.supportStrongpointTier === "must-own"
            ? `Must-own PKM lane live | ${nearbyPinnedCount + nearbySuppressedCount} bent`
            : `PKM lane live | ${nearbyPinnedCount + nearbySuppressedCount} bent`
        : pressuredWindowSeconds !== null
          ? `${pressuredWindowSeconds.toFixed(1)}s crossing window`
          : `${nearbyPinnedCount + nearbySuppressedCount} bodies bent`;
    threatLabel =
      reserveSeconds !== null
        ? `Reserve in ${reserveSeconds.toFixed(1)}s`
        : nearbyPinnedMachineGunnerCount > 0
          ? `${nearbyPinnedMachineGunnerCount} PKM lane | ${nearbyPinnedCount} pinned | ${nearbySuppressedCount} suppressed`
          : `${nearbyPinnedCount} pinned | ${nearbySuppressedCount} suppressed`;
  } else if (focusedIncident?.status === "routed") {
    posture = "routed";
    detail = "Blue has already been walked off the lane, but the route still needs a bag, flag, or recovery pass before the ground is truly stable.";
    tone = "warning";
    actionLabel = "Secure the won ground";
    windowLabel = "Lane already broken";
    threatLabel = reserveSeconds !== null ? `Reserve in ${reserveSeconds.toFixed(1)}s` : "Bag, flag, or recover now";
  } else if (
    state.quietIngressTimer > 0 &&
    state.pendingReinforcements.length === 0 &&
    state.noiseResponseLevel === 0 &&
    !state.enemies.some((enemy) => enemy.alert || enemy.awareness === "engaged")
  ) {
    posture = "holding";
    detail =
      "The route is still cold enough that Blue has not fully made the squad, so this is the setup beat: isolate one sentry, cut the angle you want, or bypass the first pocket before the district actually wakes.";
    tone = "steady";
    actionLabel = "Cut one sentry or bypass";
    windowLabel = `${state.quietIngressTimer.toFixed(0)}s quiet ingress`;
    threatLabel = "Hold the first loud shot";
  } else if (state.pendingReinforcements.length > 0 || state.noiseResponseLevel > 0) {
    posture = "reinforcing";
    detail = focusedStripIncident
      ? "The white van strip already woke the relay reserve lane, so the next pressure read is about incoming bodies trying to claw the comms kit back off the verge."
      : trenchLineActive
        ? "The trench line has woken the reserve lane, so the next pressure read is about incoming bodies spilling toward the lip rather than only the current pocket."
        : "The route has woken the reserve lane, so the next pressure read is about incoming bodies rather than only the current pocket.";
    tone = "warning";
    actionLabel = focusedStripIncident
      ? "Strip the mast kit before reserve"
      : nearbyPressuredEnemies > 0
        ? "Finish the pocket before reserve"
        : trenchLineActive
          ? "Brace the trench reserve lane"
          : "Brace for the reserve lane";
    windowLabel =
      pressuredWindowSeconds !== null ? `${pressuredWindowSeconds.toFixed(1)}s crossing window` : "Pressure still forming";
    threatLabel = reserveSeconds !== null
      ? `Reserve in ${reserveSeconds.toFixed(1)}s`
      : focusedStripIncident
        ? "Mast kit still exposed"
        : "Noise is still leaning reserve";
  } else if (state.activeExtractId !== null || state.extractionHoldTimer > 0) {
    posture = "withdrawing";
    detail = "The lane is now bending toward exfil, so posture is about screening the peel instead of deepening the push.";
    tone = state.extractionContested ? "critical" : "warning";
    actionLabel = state.extractionContested ? "Clear the ring and peel" : "Screen the peel";
    windowLabel = state.extractionHoldTimer > 0 ? `${state.extractionHoldTimer.toFixed(1)}s hold left` : "Extract lane open";
    threatLabel = state.extractionContested
      ? `${state.extractionContesters} ring threat${state.extractionContesters === 1 ? "" : "s"} live`
      : reserveSeconds !== null
        ? `Reserve in ${reserveSeconds.toFixed(1)}s`
        : "Keep the screen lean";
  }

  const title = getPressurePostureLabel(posture);
  const statusBase = focusedIncident ? `${focusedIncident.label} | ${title}` : title;
  return {
    posture,
    title,
    status: ownershipStatusLabel ? `${statusBase} | ${ownershipStatusLabel}` : statusBase,
    detail,
    compact: ownershipLabel ? `${title} posture | ${ownershipLabel}` : `${title} posture`,
    tone,
    actionLabel,
    windowLabel,
    threatLabel,
    ownershipLabel,
    pinnedCount: nearbyPinnedCount,
    suppressedCount: nearbySuppressedCount,
    windowSeconds: pressuredWindowSeconds,
    reserveSeconds
  };
}

export function getTacticalDistrictRead(state: RaidState): TacticalDistrictRead {
  const activeRoute =
    RAID_ROUTES.find((candidate) => candidate.id === state.activeRouteId) ??
    RAID_ROUTES[0];
  const settlementRead = getSettlementStateRead(state, activeRoute.id);
  const subzoneRead = getActiveTacticalSubzoneRead(state, activeRoute.id);
  const totalPressure =
    state.frontlineSectors.reduce((sum, sector) => sum + sector.pressure, 0) /
    Math.max(1, state.frontlineSectors.length);
  const heldCount = state.frontlineSectors.filter((sector) => sector.control === "held").length;
  const lostCount = state.frontlineSectors.filter((sector) => sector.control === "lost").length;
  const contestedCount = state.frontlineSectors.filter((sector) => sector.control === "contested").length;
  const controlTone: TacticalDistrictControlTone =
    contestedCount > 0 ? "mixed" : lostCount === state.frontlineSectors.length ? "lost" : heldCount === state.frontlineSectors.length ? "held" : "contested";
  const controlLabel =
    controlTone === "mixed"
      ? "Mixed control"
      : controlTone === "held"
        ? "Friendly hold"
        : controlTone === "lost"
          ? "Blue-owned ground"
          : "Contested district";

  return {
    id: TACTICAL_DISTRICT_BLUEPRINT.id,
    label: TACTICAL_DISTRICT_BLUEPRINT.label,
    controlTone,
    controlLabel,
    pressureLabel: `${Math.round(totalPressure)} district pressure`,
    activeRouteLabel: activeRoute.name,
    activeSettlementLabel: settlementRead.label,
    activeSubzoneLabel: subzoneRead.label,
    detail: `${TACTICAL_DISTRICT_BLUEPRINT.summary} ${settlementRead.label} is currently a ${settlementRead.volatilityLabel.toLowerCase()} inside ${subzoneRead.label.toLowerCase()}.`
  };
}

function getCampaignFinaleStateLabel(state: CampaignFinaleState): string {
  if (state === "revealed") {
    return "Stronghold revealed";
  }

  if (state === "preparing") {
    return "Preparation underway";
  }

  if (state === "ready") {
    return "Final assault ready";
  }

  if (state === "launched") {
    return "Final assault launched";
  }

  if (state === "won") {
    return "War sector escaped";
  }

  return "Stronghold still rumor";
}

function getCampaignPrepOutputTone(
  ready: boolean,
  hasRoute: boolean,
  missingBodies = 0
): CampaignFinalePrepOutput["tone"] {
  if (ready) {
    return "steady";
  }

  if (missingBodies > 0 || !hasRoute) {
    return "critical";
  }

  return "warning";
}

export function getCampaignFinaleRead(state: RaidState): CampaignFinaleRead {
  const strongholdLabel = "Black Orchard Redoubt";
  const enemyLabel = "Hinge-9 Brigade";
  const objectiveLabel = "Break the command relay citadel and open the real escape lane.";
  const successfulSummaries = state.raidHistory.filter((summary) => summary.result === "success");
  const successfulExtracts = successfulSummaries.length;
  const clearedContracts = state.raidHistory.filter((summary) => summary.contractCompleted).length;
  const totalIntel = state.raidHistory.reduce((sum, summary) => sum + summary.intelSecured, 0);
  const uniqueRoutes = new Set(state.raidHistory.map((summary) => summary.routeId)).size;
  const uniqueWeapons = new Set(
    state.raidHistory
      .map((summary) => summary.weaponId)
      .filter((weaponId) => weaponId !== "none")
  ).size;
  const totalFlags = state.raidHistory.reduce((sum, summary) => sum + summary.routeFlagsPlanted, 0);
  const totalBodiesRecovered = state.raidHistory.reduce((sum, summary) => sum + summary.bodiesRecovered, 0);
  const readyOperators = state.squadRoster.filter((mate) => mate.status === "active").length;
  const missingBodies = state.squadRoster.filter((mate) => mate.status === "killed" && !mate.bodyRecovered).length;
  const pkmDoctrineLive =
    state.selectedWeapon === "pkm" ||
    state.squadRoster.some((mate) => mate.weaponId === "pkm" && mate.status !== "killed") ||
    state.raidHistory.some((summary) => summary.weaponId === "pkm");
  const totalSupplyStock = state.stashSupplies.medkits + state.stashSupplies.ammoPacks;
  const heldSectors = state.frontlineSectors.filter((sector) => sector.control === "held").length;
  const pendingOperations = state.pendingFrontlineOperations.map((operation) => {
    const route =
      RAID_ROUTES.find((candidate) => candidate.id === operation.routeId) ??
      RAID_ROUTES[0];
    return {
      ...operation,
      routeLabel: route.name,
      definition: FRONTLINE_OPERATION_DEFINITIONS[operation.operationId]
    };
  });
  const getBestRouteSummary = (
    score: (summary: RaidSummary) => number
  ): RaidSummary | null =>
    successfulSummaries.reduce<RaidSummary | null>((best, summary) => {
      const summaryScore = score(summary);
      const bestScore = best ? score(best) : -Infinity;
      return summaryScore > bestScore ? summary : best;
    }, null);
  const markedExfilOperation = pendingOperations.find((operation) => operation.operationId === "mark-exfil") ?? null;
  const reinforcedPicketsOperation =
    pendingOperations.find((operation) => operation.operationId === "reinforce-pickets") ?? null;
  const recoveryOperation = pendingOperations.find((operation) => operation.operationId === "recover-body") ?? null;
  const bestIntelRoute = getBestRouteSummary((summary) => summary.intelSecured);
  const bestFlagRoute = getBestRouteSummary((summary) => summary.routeFlagsPlanted + summary.territoryReclaimed);
  const bestRecoveryRoute = getBestRouteSummary((summary) => summary.bodiesRecovered);
  const bestExtractRoute = getBestRouteSummary(
    (summary) => (summary.extractedAtLabel ? 2 : 0) + summary.routeFlagsPlanted + summary.territoryReclaimed
  );
  const repeatedRecoveryProofReady = totalBodiesRecovered >= 2;
  const firstRecoveryProofReady = bestRecoveryRoute !== null && totalBodiesRecovered >= 1 && missingBodies === 0;
  const recoveryPathReady = recoveryOperation !== null || repeatedRecoveryProofReady || firstRecoveryProofReady;
  const finaleOutcome = state.campaignFinaleOutcome;
  const setbackSpentOutputIds = new Set(
    finaleOutcome?.state === "setback" ? finaleOutcome.spentPrepOutputIds ?? [] : []
  );
  const setbackDamagedTrackLabels = new Set(
    finaleOutcome?.state === "setback" ? finaleOutcome.damagedTrackLabels ?? [] : []
  );
  let prepOutputs: CampaignFinalePrepOutput[] = [
    {
      id: "safer-lane",
      label: "Safer lane",
      effectLabel: "Marked pull lane",
      status: markedExfilOperation
        ? `${markedExfilOperation.routeLabel} already has chemlights and route tape hidden on the pull.`
        : bestExtractRoute && successfulExtracts >= 3
          ? `${bestExtractRoute.routeName} has enough clean exfils logged to seed a practiced pull into the finale wall.`
          : "No approach lane is staged cleanly enough yet to trust the first finale peel.",
      sourceLabel: markedExfilOperation
        ? `${markedExfilOperation.routeLabel} // ${markedExfilOperation.definition.title}`
        : bestExtractRoute
          ? `${bestExtractRoute.routeName} // ${bestExtractRoute.extractedAtLabel ?? "logged pull"}`
          : "No marked exfil route",
      detail: markedExfilOperation
        ? "The squad can reuse the taped fallback path and shorter uplink hold from a live safe-exfil order."
        : "Safer-lane prep should come from marked exfil work or repeated clean pulls on one district instead of raw readiness score inflation.",
      ready: markedExfilOperation !== null || (bestExtractRoute !== null && successfulExtracts >= 3),
      tone: getCampaignPrepOutputTone(markedExfilOperation !== null || (bestExtractRoute !== null && successfulExtracts >= 3), bestExtractRoute !== null)
    },
    {
      id: "weaker-flank",
      label: "Weaker flank",
      effectLabel: "Outer lane softened",
      status: reinforcedPicketsOperation
        ? `${reinforcedPicketsOperation.routeLabel} is already being thinned by staged pickets and false positions.`
        : bestFlagRoute && (totalFlags >= 4 || heldSectors >= 2)
          ? `${bestFlagRoute.routeName} has enough planted claims and reclaimed ground to treat one outer flank as thinner.`
          : "The final assault still needs a route where first contact has already been blunted.",
      sourceLabel: reinforcedPicketsOperation
        ? `${reinforcedPicketsOperation.routeLabel} // ${reinforcedPicketsOperation.definition.title}`
        : bestFlagRoute
          ? `${bestFlagRoute.routeName} // ${bestFlagRoute.routeFlagsPlanted} flags planted`
          : "No softened flank",
      detail: reinforcedPicketsOperation
        ? "This reuses the frontline operation that trims first contact instead of inventing a finale-only flank bonus."
        : "Weaker-flank prep should come from real territorial reps and planted claims that make one side of the wall less stable.",
      ready: reinforcedPicketsOperation !== null || (bestFlagRoute !== null && (totalFlags >= 4 || heldSectors >= 2)),
      tone: getCampaignPrepOutputTone(
        reinforcedPicketsOperation !== null || (bestFlagRoute !== null && (totalFlags >= 4 || heldSectors >= 2)),
        bestFlagRoute !== null
      )
    },
    {
      id: "recovery-path",
      label: "Recovery path",
      effectLabel: "Casualty corridor steadied",
      status: recoveryOperation
        ? `${recoveryOperation.routeLabel} has straps, wagon cover, and a marked drag lane already queued.`
        : repeatedRecoveryProofReady
          ? "The squad has already proven body and casualty pulls often enough that the finale can inherit a real recovery route."
          : firstRecoveryProofReady
            ? "One successful memorial return already proved the squad can reopen a drag lane and close the chair debt cleanly."
          : missingBodies > 0
            ? "Unrecovered chair debt is still hanging over the squad and no fresh recovery lane is staged."
            : "Recovery path is still theory until the squad logs more body or casualty pulls.",
      sourceLabel: recoveryOperation
        ? `${recoveryOperation.routeLabel} // ${recoveryOperation.definition.title}`
        : bestRecoveryRoute
          ? `${bestRecoveryRoute.routeName} // ${bestRecoveryRoute.bodiesRecovered} bodies recovered`
          : missingBodies > 0
            ? `${missingBodies} unrecovered chair${missingBodies === 1 ? "" : "s"}`
            : "No recovery route logged",
      detail: recoveryOperation
        ? "The finale now inherits the same body-recovery and casualty-pull prep language used by the normal campaign."
        : firstRecoveryProofReady
          ? "A cleared memorial return is now enough to prove the squad can build one real casualty corridor into the finale without inventing a separate endgame-only rule."
          : "Recovery prep should come from the live memorial debt loop, not a separate finale-only mercy state.",
      ready: recoveryPathReady,
      tone: getCampaignPrepOutputTone(recoveryPathReady, bestRecoveryRoute !== null, missingBodies)
    },
    {
      id: "route-intel",
      label: "Route intel",
      effectLabel: "Approach reads updated",
      status: bestIntelRoute && totalIntel >= 5
        ? `${bestIntelRoute.routeName} is already paying enough terminal and route intel to turn the stronghold from rumor into approach work.`
        : bestIntelRoute
          ? `${bestIntelRoute.routeName} is the current best intel feed, but the war wall still needs more live reads.`
          : "No district has fed enough live intel back to the stash to map the final wall cleanly.",
      sourceLabel: bestIntelRoute
        ? `${bestIntelRoute.routeName} // ${bestIntelRoute.intelSecured} intel secured`
        : "No route intel feed",
      detail: "This output is built from real extracted intel rather than a separate campaign tech tree.",
      ready: bestIntelRoute !== null && totalIntel >= 5,
      tone: getCampaignPrepOutputTone(bestIntelRoute !== null && totalIntel >= 5, bestIntelRoute !== null)
    }
  ];
  if (setbackSpentOutputIds.size > 0) {
    prepOutputs = prepOutputs.map((output) => {
      if (!setbackSpentOutputIds.has(output.id)) {
        return output;
      }

      if (output.id === "safer-lane") {
        return {
          ...output,
          ready: false,
          tone: "critical",
          status: "The failed breach burned the taped pull lane, so the squad needs one fresh safer-lane rep before another launch.",
          sourceLabel: "Setback tax // Marked pull lane spent",
          detail:
            "The first launch consumed the old exfil tape and sightline discipline. Another retry has to reopen a live pull route instead of pretending the first one stayed free."
        };
      }

      if (output.id === "recovery-path") {
        return {
          ...output,
          ready: false,
          tone: "critical",
          status: "The collapse peel spent the old casualty corridor, so the squad needs to restage a drag lane before relaunching.",
          sourceLabel: "Setback tax // Casualty corridor blown",
          detail:
            "Failure keeps the campaign recoverable, but the retry has to earn a fresh recovery path through the same body-debt loop the normal campaign already uses."
        };
      }

      return {
        ...output,
        ready: false,
        tone: "warning",
        status: `The failed launch spent ${output.effectLabel.toLowerCase()} and it now needs another prep rep before the next push.`,
        sourceLabel: "Setback tax // Prep spent"
      };
    });
  }

  const readyPrepOutputs = prepOutputs.filter((output) => output.ready);
  const prepSummary =
    readyPrepOutputs.length > 0
      ? readyPrepOutputs.map((output) => output.effectLabel).join(" | ")
      : "No finale prep outputs live";
  let prepTracks: CampaignFinalePrepTrack[] = [
    {
      label: "Route intel",
      status:
        totalIntel >= 5
          ? "Multiple districts have already paid real intel back to stash."
          : "The stronghold is still mostly rumor until more intel comes home alive.",
      ready: totalIntel >= 5
    },
    {
      label: "District reps",
      status:
        uniqueRoutes >= 3
          ? "Every current district has at least one logged operation feeding the war map."
          : "The squad still needs a broader district record before the final wall should feel readable.",
      ready: uniqueRoutes >= 3
    },
    {
      label: "Doctrine ladder",
      status:
        uniqueWeapons >= 4 && pkmDoctrineLive
          ? "The squad has touched the wider weapon ladder and the PKM support answer is live."
          : "The final wall should stay closed until the gun ladder is wider and belt-fed support is real.",
      ready: uniqueWeapons >= 4 && pkmDoctrineLive
    },
    {
      label: "Preparation orders",
      status:
        readyPrepOutputs.length >= 2 || state.pendingFrontlineOperations.length >= 2 || heldSectors >= 2 || totalFlags >= 4
          ? `${prepSummary} are already shaping future approaches.`
          : "Queue more district prep so the final offensive is built on real approach work, not wishful clicks.",
      ready: readyPrepOutputs.length >= 2 || state.pendingFrontlineOperations.length >= 2 || heldSectors >= 2 || totalFlags >= 4
    },
    {
      label: "Squad depth",
      status:
        readyOperators >= 3 && missingBodies === 0 && totalSupplyStock >= 4
          ? "Three ready operators, no unrecovered chair debt, and enough sealed stock to support a harder push."
          : "The squad still needs cleaner chairs, steadier stock, or both before the final assault should open.",
      ready: readyOperators >= 3 && missingBodies === 0 && totalSupplyStock >= 4
    },
    {
      label: "Campaign reps",
      status:
        successfulExtracts >= 4 && clearedContracts >= 3
          ? "The crew has enough real extracts and cashed asks to read like a finishing force."
          : "The game still needs more clean extracts and closed asks before the stronghold can feel earned.",
      ready: successfulExtracts >= 4 && clearedContracts >= 3
    }
  ];
  if (setbackDamagedTrackLabels.size > 0) {
    prepTracks = prepTracks.map((track) => {
      if (!setbackDamagedTrackLabels.has(track.label)) {
        return track;
      }

      if (track.label === "Preparation orders") {
        return {
          ...track,
          ready: false,
          status:
            "The first launch spent the safer lane and casualty corridor, so prep orders have to be rebuilt instead of staying silently checked off."
        };
      }

      if (track.label === "Squad depth") {
        return {
          ...track,
          ready: false,
          status:
            "The setback left the squad short on sealed stock and reset confidence, so squad depth must steady again before the wall should reopen."
        };
      }

      return {
        ...track,
        ready: false,
        status: `The setback damaged ${track.label.toLowerCase()} and the squad has to restage it before another stronghold push.`
      };
    });
  }

  const saferLaneOutput = prepOutputs.find((output) => output.id === "safer-lane") ?? prepOutputs[0];
  const weakerFlankOutput = prepOutputs.find((output) => output.id === "weaker-flank") ?? prepOutputs[0];
  const recoveryPathOutput = prepOutputs.find((output) => output.id === "recovery-path") ?? prepOutputs[0];
  const routeIntelOutput = prepOutputs.find((output) => output.id === "route-intel") ?? prepOutputs[0];
  const doctrineTrack = prepTracks.find((track) => track.label === "Doctrine ladder") ?? prepTracks[0];
  const squadDepthTrack = prepTracks.find((track) => track.label === "Squad depth") ?? prepTracks[0];
  let assaultPlan: CampaignFinaleAssaultBeat[] = [
    {
      label: "Entry Belt",
      title: saferLaneOutput.ready ? "Marked pull lane staged" : "Entry lane still blind",
      detail: saferLaneOutput.ready
        ? `${saferLaneOutput.status} ${routeIntelOutput.ready ? "Route intel is already good enough that the first relay belt should read like a planned cut, not a blind guess." : "The lane still needs cleaner approach reads before the first relay belt should be trusted."}`
        : `${saferLaneOutput.status} ${routeIntelOutput.status}`,
      tone: saferLaneOutput.ready ? "steady" : routeIntelOutput.ready ? "warning" : "critical",
      tags: [saferLaneOutput.effectLabel, saferLaneOutput.sourceLabel]
    },
    {
      label: "Relay Mouth",
      title: weakerFlankOutput.ready ? "Outer pickets softened" : "Outer pickets still stiff",
      detail: `${weakerFlankOutput.status} ${doctrineTrack.ready ? doctrineTrack.status : "The squad still needs a broader doctrine ladder before the breach mouth should feel finishable."}`,
      tone: weakerFlankOutput.ready && doctrineTrack.ready ? "steady" : weakerFlankOutput.ready || doctrineTrack.ready ? "warning" : "critical",
      tags: [weakerFlankOutput.effectLabel, doctrineTrack.label]
    },
    {
      label: "Casualty Strip",
      title: recoveryPathOutput.ready ? "Drag lane is credible" : "Corridor still brittle",
      detail: `${recoveryPathOutput.status} ${squadDepthTrack.status}`,
      tone: recoveryPathOutput.ready && squadDepthTrack.ready ? "steady" : recoveryPathOutput.ready ? "warning" : "critical",
      tags: [recoveryPathOutput.effectLabel, squadDepthTrack.label]
    },
    {
      label: "Escape Cut",
      title: routeIntelOutput.ready ? "Exit reads are mapped" : "Escape lane is still rumor",
      detail: routeIntelOutput.ready
        ? `${routeIntelOutput.status} ${saferLaneOutput.ready ? "The same marked pull can become the finishing peel once the relay wall finally breaks." : "The campaign still needs a safer lane before the winning peel should feel disciplined."}`
        : `${routeIntelOutput.status} Do not spend the finale on hope alone; the way out still needs a route the squad actually understands.`,
      tone: routeIntelOutput.ready && saferLaneOutput.ready ? "steady" : routeIntelOutput.ready ? "warning" : "critical",
      tags: [routeIntelOutput.effectLabel, strongholdLabel]
    }
  ];

  const readyTrackCount = prepTracks.filter((track) => track.ready).length;
  const readinessPenalty = finaleOutcome?.state === "setback" ? finaleOutcome.readinessPenalty ?? 0 : 0;
  const readinessCap = finaleOutcome?.state === "setback" ? 72 : 100;
  const readiness = Math.max(
    0,
    Math.min(
      readinessCap,
      Math.round(
        successfulExtracts * 9 +
          clearedContracts * 6 +
          totalIntel * 4 +
          uniqueRoutes * 9 +
          uniqueWeapons * 5 +
          readyTrackCount * 8 +
          readyPrepOutputs.length * 4 +
          readyOperators * 4 +
          Math.min(18, state.stashCredits / 45) -
          missingBodies * 15 -
          readinessPenalty
      )
    )
  );
  const squadDepthReady = prepTracks.some((track) => track.label === "Squad depth" && track.ready);
  const baseCampaignState: CampaignFinaleState =
    successfulExtracts < 2 || totalIntel < 2
      ? "locked"
      : readyTrackCount >= 5 && readiness >= 78 && squadDepthReady
        ? "ready"
        : readyTrackCount >= 2 || readiness >= 48
          ? "preparing"
          : "revealed";
  let campaignState: CampaignFinaleState = baseCampaignState;
  let stateLabel = getCampaignFinaleStateLabel(campaignState);
  let tone: CampaignFinaleRead["tone"] =
    campaignState === "ready" ? "steady" : campaignState === "locked" ? "critical" : "warning";
  let progressLabel = `${readyTrackCount}/${prepTracks.length} prep tracks live`;
  let revealReason =
    campaignState === "locked"
      ? `The war keeps hinting that ${enemyLabel} is sitting behind ${strongholdLabel}, but the campaign still lacks enough live extracts and intel to make that district concrete.`
      : campaignState === "revealed"
        ? `${strongholdLabel} is now a named wall in the campaign, but the squad is not yet carrying the prep depth to launch it.`
      : campaignState === "preparing"
          ? `${strongholdLabel} is no longer abstract. ${prepSummary} now changes whether the final push will feel like a test or a suicide note.`
          : `The campaign is finally carrying enough prep to let ${strongholdLabel} read like a real endgame operation instead of a rumor. ${prepSummary} are already live.`;
  const missingTrack = prepTracks.find((track) => !track.ready) ?? null;
  const missingPrepOutput = prepOutputs.find((output) => !output.ready) ?? null;
  let launchInstruction =
    campaignState === "ready"
      ? `Use the next push to formally unlock ${strongholdLabel} and launch the hardest district in the sector.`
      : missingPrepOutput
        ? `Keep feeding ${missingPrepOutput.label.toLowerCase()} before trying to open ${strongholdLabel}.`
      : missingTrack
        ? `Keep feeding ${missingTrack.label.toLowerCase()} before trying to open ${strongholdLabel}.`
        : `Keep stacking route work until ${strongholdLabel} stops reading like a rumor.`;
  let statusLabel =
    campaignState === "ready"
      ? "Launch window is live"
      : campaignState === "preparing"
        ? "Prep is reshaping the wall"
        : campaignState === "revealed"
          ? "The target is named"
          : "Rumor only";
  let followThrough =
    campaignState === "ready"
      ? `${prepSummary} are already stacked, so the next push can spend that work on the wall instead of more theory.`
      : `The finale still lives or dies on route work, doctrine breadth, and whether the squad can arrive without unresolved chair debt.`;
  let retryInstruction: string | null = null;
  let closure: CampaignClosureRead | null = null;
  if (finaleOutcome?.state === "launched") {
    campaignState = "launched";
    stateLabel = getCampaignFinaleStateLabel(campaignState);
    tone = "warning";
    progressLabel = "Stronghold breach committed";
    revealReason = finaleOutcome.status;
    launchInstruction = finaleOutcome.nextInstruction;
    statusLabel = finaleOutcome.title;
    followThrough = finaleOutcome.detail;
    assaultPlan = [
      {
        label: "Entry Belt",
        title: "First relay belt entered",
        detail:
          "The marked pull lane is already being spent under fire. The squad is inside the first wall, so the route work now has to survive contact instead of living on the planning board.",
        tone: "warning",
        tags: [saferLaneOutput.effectLabel, saferLaneOutput.sourceLabel]
      },
      {
        label: "Relay Mouth",
        title: "Outer pickets are bending",
        detail:
          "The softened flank is now the only thing keeping the relay mouth from sealing back up. Belt-fed support and the wider doctrine ladder are being cashed in on one live shove.",
        tone: "warning",
        tags: [weakerFlankOutput.effectLabel, doctrineTrack.label]
      },
      {
        label: "Casualty Strip",
        title: "Drag lane under load",
        detail:
          "The steadied casualty corridor is no longer theory. Recovery prep is now live campaign debt that has to stay open while the breach keeps moving.",
        tone: "warning",
        tags: [recoveryPathOutput.effectLabel, squadDepthTrack.label]
      },
      {
        label: "Escape Cut",
        title: "Finish the wall or die on the peel",
        detail:
          "Approach intel has to carry the exit now. The final escape lane only exists if the relay wall breaks cleanly enough for the squad to turn route knowledge into a real finishing cut.",
        tone: "critical",
        tags: [routeIntelOutput.effectLabel, strongholdLabel]
      }
    ];
  } else if (finaleOutcome?.state === "setback") {
    campaignState = "preparing";
    stateLabel = "Launch setback";
    tone = "critical";
    progressLabel = "Prep damaged but recoverable";
    revealReason = finaleOutcome.status;
    launchInstruction = finaleOutcome.nextInstruction;
    statusLabel = finaleOutcome.title;
    followThrough = finaleOutcome.detail;
    retryInstruction = finaleOutcome.nextInstruction;
    assaultPlan = [
      {
        label: "Entry Belt",
        title: "Entry tape burned",
        detail:
          "The failed launch spent the old safer lane, so the squad has to earn a fresh approach instead of pretending the first pull stayed usable after contact.",
        tone: "critical",
        tags: [saferLaneOutput.effectLabel, "Setback tax"]
      },
      {
        label: "Relay Mouth",
        title: "Outer wall is reading the squad back",
        detail:
          "The first shove showed the wall how the squad wanted to enter. Another launch needs a cleaner flank and a steadier doctrine answer before the relay mouth should be touched again.",
        tone: "warning",
        tags: [weakerFlankOutput.effectLabel, doctrineTrack.label]
      },
      {
        label: "Casualty Strip",
        title: "Old corridor blown",
        detail:
          "The collapse peel spent the recovery path. Rebuild the drag lane through normal memorial and recovery work before trying to relaunch.",
        tone: "critical",
        tags: [recoveryPathOutput.effectLabel, squadDepthTrack.label]
      },
      {
        label: "Escape Cut",
        title: "Retry lane still exists",
        detail:
          "The campaign is recoverable, but only if the next launch uses better route intel and a new exit discipline instead of rerunning the same breach by habit.",
        tone: "warning",
        tags: [routeIntelOutput.effectLabel, strongholdLabel]
      }
    ];
  } else if (finaleOutcome?.state === "won") {
    campaignState = "won";
    stateLabel = getCampaignFinaleStateLabel(campaignState);
    tone = "steady";
    progressLabel = "Escape corridor secured";
    revealReason = finaleOutcome.status;
    launchInstruction = finaleOutcome.nextInstruction;
    statusLabel = finaleOutcome.title;
    followThrough = finaleOutcome.detail;
    assaultPlan = [
      {
        label: "Entry Belt",
        title: "First wall broken",
        detail: "The opening belt is no longer a live debt. The squad already converted the marked pull into a real breach.",
        tone: "steady",
        tags: [saferLaneOutput.effectLabel, strongholdLabel]
      },
      {
        label: "Relay Mouth",
        title: "Command relay seized",
        detail: "The outer pickets and relay mouth are finished problems now, not future planning work.",
        tone: "steady",
        tags: [weakerFlankOutput.effectLabel, doctrineTrack.label]
      },
      {
        label: "Casualty Strip",
        title: "Corridor paid for the win",
        detail: "The recovery path carried real bodies through the hardest wall and is now part of the campaign closure rather than another prep ask.",
        tone: "steady",
        tags: [recoveryPathOutput.effectLabel, squadDepthTrack.label]
      },
      {
        label: "Escape Cut",
        title: "Real way out secured",
        detail: "Route intel and exit discipline paid off. The final peel is no longer theory because the war-sector exit is actually open.",
        tone: "steady",
        tags: [routeIntelOutput.effectLabel, "True escape"]
      }
    ];
    closure = {
      headline: "Chapter closed",
      status: "Normal raid loop is over",
      summary:
        `${strongholdLabel} is down, the surviving squad finally has a real way out, and the stash now reads as what the war cost instead of fuel for one more ordinary deploy.`,
      nextChapter:
        "Freeze the normal deploy cadence here; any later return should be framed as a new chapter, not a quiet rerun of the same war sector.",
      beats: [
        {
          label: "Stronghold",
          value: `${strongholdLabel} broken`,
          detail: `${enemyLabel}'s relay wall is no longer an active campaign debt.`
        },
        {
          label: "Prep Payoff",
          value: readyPrepOutputs.length > 0 ? prepSummary : "No spare prep left over",
          detail: "The winning push reuses the same route, recovery, and territorial work the campaign already taught."
        },
        {
          label: "Squad",
          value:
            missingBodies === 0
              ? `${readyOperators} operators walked out`
              : `${readyOperators} operators out | ${missingBodies} chair still owed`,
          detail: "Closure should still remember who made the corridor and what chair debt was carried to the end."
        },
        {
          label: "Stash",
          value: `${state.stashCredits} cr | ${totalSupplyStock} sealed stock`,
          detail: "This is aftermath inventory now, not the opening wallet for another routine raid."
        }
      ]
    };
  }

  return {
    state: campaignState,
    stateLabel,
    strongholdLabel,
    enemyLabel,
    readiness,
    progressLabel,
    objectiveLabel,
    revealReason,
    detail: `${objectiveLabel} ${revealReason} ${followThrough}`.trim(),
    launchInstruction,
    statusLabel,
    followThrough,
    retryInstruction,
    prepTracks,
    prepSummary,
    prepOutputs,
    assaultPlan,
    closure,
    tone,
    compact: `${strongholdLabel} | ${stateLabel}`
  };
}

export function getBlindFireRead(state: RaidState): BlindFireRead {
  const nearbySuppressedBlue = state.enemies.filter(
    (enemy) =>
      enemy.pressureType === "suppressed" &&
      enemy.blindFireTimer > 0.08 &&
      distance(enemy.position, state.player.position) <= 340
  );
  const nearbyFriendlyBlindFire = state.frontlineSupports.filter(
    (support) => support.kind === "fireteam" && support.blindFireTimer > 0.08 && distance(support.position, state.player.position) <= 360
  );
  const nearbyHostileBlindFire = state.frontlineIncidents.filter(
    (incident) =>
      incident.kind === "firefight" &&
      incident.blindFireTimer > 0.08 &&
      distance(incident.position, state.player.position) <= 380
  );
  const hostileCount = nearbySuppressedBlue.length + nearbyHostileBlindFire.length;
  const friendlyCount = nearbyFriendlyBlindFire.length;

  if (hostileCount === 0 && friendlyCount === 0) {
    return {
      title: "BLIND FIRE QUIET",
      status: "No active heads-down spray is crossing your lane.",
      detail: "Suppression is moving bodies right now, but nobody nearby is blind-firing off memory or panic.",
      compact: "Blind fire quiet",
      tone: "steady"
    };
  }

  const hostileLabel =
    hostileCount > 0 ? `${hostileCount} hostile ${hostileCount === 1 ? "gun" : "guns"} spraying blind` : "no hostile blind fire";
  const friendlyLabel =
    friendlyCount > 0 ? `${friendlyCount} boy${friendlyCount === 1 ? "" : "s"} returning blind fire` : "boys not blind-firing";
  const closeHostile = nearbySuppressedBlue[0] ?? null;
  const tone: BlindFireRead["tone"] = hostileCount >= 3 ? "critical" : hostileCount >= 1 ? "warning" : "steady";
  const detail =
    hostileCount > 0
      ? `${closeHostile ? getEnemyTapeDefinition(closeHostile.tapeId).shortLabel : "Blue"} has been forced heads-down and is still spraying from cover, while the boys answer with low-confidence return fire through the same cut.`
      : "The boys are forcing return blind fire through cover, which means the lane is hot even if nobody has a clean body shot.";

  return {
    title: hostileCount > 0 ? "BLIND FIRE LIVE" : "BLIND FIRE RETURN",
    status: `${hostileLabel} | ${friendlyLabel}`,
    detail,
    compact: hostileCount > 0 ? `${hostileCount} hostile blind fire` : `${friendlyCount} friendly blind fire`,
    tone
  };
}

export function getFrontlineSupportOrderPayoff(state: RaidState): FrontlineSupportOrderPayoffState {
  const activeOrderId =
    state.activeFrontlineSupportOrderId !== null && state.frontlineSupportOrderTimer > 0
      ? state.activeFrontlineSupportOrderId
      : null;

  if (!activeOrderId) {
    if (state.frontlineSupportOrderCooldown > 0) {
      return {
        orderId: null,
        title: "Net resetting",
        metric: `${state.frontlineSupportOrderCooldown.toFixed(1)}s until next call`,
        detail: "The boys stay on shoulder coverage until the net settles and another shove is ready.",
        tone: "cooldown"
      };
    }

    return {
      orderId: null,
      title: "Net ready",
      metric: "Z cover | X draw | C exfil | B hold | V breach",
      detail: "The boys are clear to take the next lane order whenever the raid needs a shove.",
      tone: "ready"
    };
  }

  if (activeOrderId === "shift-fire") {
    const target = getSupportObjectiveTargetForState(state);
    const focusedIncident = getFocusedFrontlineIncidentForState(state);
    const pinnedEnemies = state.enemies.filter(
      (enemy) => distance(enemy.position, target) <= 240 && enemy.pressureTimer > 0.08
    ).length;
    const bracedFireteams = state.frontlineSupports.filter(
      (support) => support.kind === "fireteam" && distance(support.position, target) <= 160
    ).length;
    return {
      orderId: activeOrderId,
      title: "Cover window open",
      metric: `${pinnedEnemies} pinned | ${bracedFireteams} rifles braced | ${state.frontlineSupportOrderTimer.toFixed(1)}s`,
      detail: focusedIncident
        ? `The boys are leaning into ${focusedIncident.label.toLowerCase()} so your next move lands under cover instead of a raw peek.`
        : "The boys are stitching fire across the next hot lane so you can move under suppression instead of eating a naked swing.",
      tone: activeOrderId
    };
  }

  if (activeOrderId === "draw-heat") {
    const decoyTracks = state.frontlineSupports.filter((support) => support.kind !== "fireteam");
    const draggedEyes = state.enemies.filter(
      (enemy) =>
        enemy.investigateTimer > 0.08 &&
        enemy.investigateTarget !== null &&
        decoyTracks.some((support) => distance(support.position, enemy.investigateTarget as Vec2) <= 96)
    ).length;
    const nextWave = state.pendingReinforcements.reduce<PendingReinforcementState | null>(
      (best, pending) => (!best || pending.timer < best.timer ? pending : best),
      null
    );
    return {
      orderId: activeOrderId,
      title: "Eyes dragged wide",
      metric: `${draggedEyes} pulled off | noise ${state.soundPressure.toFixed(2)}${nextWave ? ` | ${nextWave.timer.toFixed(1)}s to next wave` : ""}`,
      detail: nextWave
        ? `Decoys are muddying the route read and buying time before ${nextWave.label.toLowerCase()} lands on your shoulder.`
        : "Decoys are muddying the route read so Blue hesitates on the next collapse and your lane opens cleaner.",
      tone: activeOrderId
    };
  }

  if (activeOrderId === "secure-exfil") {
    const focusedExtract = getFocusedExtractForState(state);
    const pressuredRingThreats = state.enemies.filter(
      (enemy) => distance(enemy.position, focusedExtract.position) <= focusedExtract.radius + 86 && enemy.pressureTimer > 0.08
    ).length;
    const extractScreen = state.frontlineSupports.filter(
      (support) => distance(support.position, focusedExtract.position) <= focusedExtract.radius + 72
    ).length;
    return {
      orderId: activeOrderId,
      title: "Exfil screen holding",
      metric: `${pressuredRingThreats} ring threats pinned | ${extractScreen} on beacon | ${state.frontlineSupportOrderTimer.toFixed(1)}s`,
      detail: state.extractionContested
        ? `The boys are crushing the ${focusedExtract.label.toLowerCase()} ring so the uplink can recover before the haul slips.`
        : `The boys are screening ${focusedExtract.label.toLowerCase()} so the last hold reads like a squad pull instead of a solo stand.`,
      tone: activeOrderId
    };
  }

  if (activeOrderId === "hold-position") {
    const holdAnchor = getSupportHoldAnchorForState(state);
    const anchoredSupportTracks = state.frontlineSupports.filter(
      (support) => support.kind === "fireteam" && distance(support.position, holdAnchor.position) <= 148
    ).length;
    const anchoredFireteams = Math.max(state.squadMates.length > 0 ? 1 : 0, anchoredSupportTracks);
    const checkedThreats = state.enemies.filter(
      (enemy) => distance(enemy.position, holdAnchor.position) <= 230 && (enemy.pressureTimer > 0.08 || enemy.awareness === "engaged")
    ).length;
    return {
      orderId: activeOrderId,
      title: "Hold anchored",
      metric: `${anchoredFireteams} anchored | ${checkedThreats} checked | ${state.frontlineSupportOrderTimer.toFixed(1)}s`,
      detail: holdAnchor.label
        ? `The boys are dug into ${holdAnchor.label.toLowerCase()} and forcing Blue to re-take the pocket before you move again.`
        : "The boys are dug into the current shoulder and forcing Blue to re-take the pocket before you move again.",
      tone: activeOrderId
    };
  }

  const breachObstacle = getPriorityBreachObstacleForState(state);
  const breachPoint = breachObstacle ? getObstacleBreachPoint(breachObstacle) : null;
  const stackedFireteams =
    breachPoint === null
      ? 0
      : state.frontlineSupports.filter(
          (support) => support.kind === "fireteam" && distance(support.position, breachPoint) <= 112
        ).length;
  const pressuredCutThreats =
    breachPoint === null
      ? 0
      : state.enemies.filter(
          (enemy) => distance(enemy.position, breachPoint) <= 240 && enemy.pressureTimer > 0.08
        ).length;
  const breachLabel = breachObstacle?.breach?.label ?? "the live cut";
  const activeObstacleBreach = state.activeObstacleBreach;
  const breachState =
    breachObstacle?.breach?.breached
      ? "room flooded"
      : activeObstacleBreach !== null && breachObstacle !== null && activeObstacleBreach.obstacleId === breachObstacle.id
        ? `${activeObstacleBreach.timer.toFixed(1)}s on the cut`
        : "stacking the cut";
  return {
    orderId: activeOrderId,
    title: "Breach follow-through live",
    metric: `${stackedFireteams} stacked | ${pressuredCutThreats} pinned | ${breachState}`,
    detail: breachObstacle?.breach?.breached
      ? `The boys are through ${breachLabel.toLowerCase()} and holding interior angles so you can flood the next room on their shoulder.`
      : `The boys are crashing ${breachLabel.toLowerCase()} so the cut becomes a real shove instead of a solo interact under fire.`,
    tone: activeOrderId
  };
}

export function getExtractCommandRecommendation(state: RaidState): ExtractCommandRecommendationState {
  const escortOnline = state.frontlineSupports.some((support) => support.playerEscort);
  if (!escortOnline) {
    return {
      orderId: null,
      title: "No boys call online",
      metric: "Deploy armed to unlock the wedge",
      detail: "The extract read can name the right move, but there is no player-bound boys net in this raid yet.",
      tone: "idle",
      actionable: false
    };
  }

  const activeOrderId =
    state.activeFrontlineSupportOrderId !== null && state.frontlineSupportOrderTimer > 0
      ? state.activeFrontlineSupportOrderId
      : null;
  const focusedExtract = getFocusedExtractForState(state);
  const manifestCount =
    state.carriedManifest.intel +
    state.carriedManifest.medical +
    state.carriedManifest.munitions +
    state.carriedManifest.hardware;
  const recoveryDriven = isRecoveryDrivenRaidState(state);
  const bankLoaded = state.carriedValue > 0 || manifestCount > 0 || state.activeContract.completed;
  const playerDistanceToExtract = distance(state.player.position, focusedExtract.position);
  const ringThreats = state.enemies.filter(
    (enemy) => distance(enemy.position, focusedExtract.position) <= focusedExtract.radius + 96
  ).length;
  const nearestThreatDistance = state.enemies.reduce<number | null>((best, enemy) => {
    const sample = distance(enemy.position, state.player.position);
    return best === null ? sample : Math.min(best, sample);
  }, null);
  const waveSoon =
    state.pendingReinforcements.length > 0 &&
    state.pendingReinforcements.some((entry) => entry.timer <= 12 || entry.source === "extraction-wave");
  const breachObstacle = getPriorityBreachObstacleForState(state);
  const extractCommitted =
    state.extractionHoldTimer > 0 ||
    state.extractionContested ||
    playerDistanceToExtract <= focusedExtract.radius + 120 ||
    (state.extractionReady &&
      state.activeExtractId !== null &&
      (bankLoaded || recoveryDriven) &&
      (waveSoon || state.soundPressure >= 0.84 || state.timerRemaining <= 60 || recoveryDriven));
  const shouldFinishGate = !state.extractionReady;
  const laneHot =
    state.extractionContested ||
    ringThreats >= 2 ||
    (nearestThreatDistance !== null && nearestThreatDistance <= 210) ||
    state.soundPressure >= 0.9;

  let recommendedOrderId: FrontlineSupportOrderId | null = null;
  let title = "Keep the boys on ambient cover";
  let detail =
    "No immediate boys call is stronger than staying flexible. Let the wedge breathe until the lane or the pull sharpens.";

  if (shouldFinishGate) {
    if (breachObstacle?.breach) {
      recommendedOrderId = "breach-push";
      title = "Stack the gate cut";
      detail = `Exfil is still gated. Crash ${breachObstacle.breach.label.toLowerCase()} with the boys so the last room opens the pull instead of stalling the raid.`;
    } else if (laneHot) {
      recommendedOrderId = "shift-fire";
      title = "Cover the gate shove";
      detail = "The route is still too hot to drift gateward naked. Tell the boys to pin the lane before you force the final exfil opener.";
    }
  } else if (state.extractionHoldTimer > 0 || state.extractionContested || extractCommitted) {
    recommendedOrderId = "secure-exfil";
    title =
      state.extractionHoldTimer > 0 || state.extractionContested
        ? recoveryDriven
          ? "Crash the ring and clear the recovery peel"
          : "Crash the ring with the boys"
        : recoveryDriven
          ? "Turn the pull into a recovery peel"
          : "Turn the pull into a squad exit";
    detail =
      state.extractionHoldTimer > 0 || state.extractionContested
        ? recoveryDriven
          ? `Screen ${focusedExtract.label.toLowerCase()} now so the boys pin ring threats and keep the bag or casualty corridor from collapsing on the beacon.`
          : `Screen ${focusedExtract.label.toLowerCase()} now so the boys pin ring threats and the beacon stops reading like a solo panic stand.`
        : recoveryDriven
          ? `You already have a named recovery peel. Fire Screen Exfil and let the boys harden ${focusedExtract.label.toLowerCase()} before the corridor turns into body debt.`
          : `You already have a named pull. Fire Screen Exfil and let the boys harden ${focusedExtract.label.toLowerCase()} before you commit the hold.`;
  } else if (state.extractionReady && state.activeExtractId !== null && (waveSoon || state.soundPressure >= 0.8)) {
    recommendedOrderId = "draw-heat";
    title = "Drag eyes off the pull";
    detail = `Blue pressure is building before you reach ${focusedExtract.label.toLowerCase()}. Pull Eyes Off buys a dirtier read so you can cut cleaner toward exfil.`;
  } else if (laneHot) {
    recommendedOrderId = "shift-fire";
    title = "Cover the exfil lane";
    detail = `The walk to ${focusedExtract.label.toLowerCase()} is still hot. Cover Me buys the cleanest move window before you start the last hold.`;
  } else if (state.extractionReady && state.activeExtractId !== null) {
    recommendedOrderId = "secure-exfil";
    title = recoveryDriven ? "Commit the boys to the recovery peel" : "Commit the boys to the chosen pull";
    detail = recoveryDriven
      ? `The route is quiet enough that calling Screen Exfil early can turn ${focusedExtract.label.toLowerCase()} into a rehearsed recovery peel instead of a late scramble under body debt.`
      : `The route is quiet enough that calling Screen Exfil early can turn ${focusedExtract.label.toLowerCase()} into a rehearsed squad exit instead of a late scramble.`;
  }

  if (activeOrderId) {
    const order = FRONTLINE_SUPPORT_ORDERS[activeOrderId];
    return {
      orderId: activeOrderId,
      title: `${order.title} already live`,
      metric: `${order.hotkey} committed | ${state.frontlineSupportOrderTimer.toFixed(1)}s left`,
      detail:
        recommendedOrderId !== null && recommendedOrderId !== activeOrderId
          ? `${detail} Let the current boys call finish before you swap the wedge onto ${FRONTLINE_SUPPORT_ORDERS[recommendedOrderId].title.toLowerCase()}.`
          : "The boys are already on the right shout for this moment. Let the live call ride before you stack another order.",
      tone: activeOrderId,
      actionable: false
    };
  }

  if (state.frontlineSupportOrderCooldown > 0) {
    return {
      orderId: recommendedOrderId,
      title: recommendedOrderId ? `${FRONTLINE_SUPPORT_ORDERS[recommendedOrderId].title} next` : "Support net resetting",
      metric: `${state.frontlineSupportOrderCooldown.toFixed(1)}s reset`,
      detail:
        recommendedOrderId !== null
          ? `${detail} The boys need one more beat before that call is available.`
          : "The wedge is settling after the last push. Hold ambient cover until the net clears.",
      tone: "cooldown",
      actionable: false
    };
  }

  if (recommendedOrderId !== null) {
    const order = FRONTLINE_SUPPORT_ORDERS[recommendedOrderId];
    return {
      orderId: recommendedOrderId,
      title,
      metric: `${order.hotkey} // ${order.title}`,
      detail,
      tone: recommendedOrderId,
      actionable: true
    };
  }

  return {
    orderId: null,
    title,
    metric: "Hold the net in reserve",
    detail,
    tone: "idle",
    actionable: false
  };
}

export function getFrontlineSupportOrderWorldCue(state: RaidState): FrontlineSupportOrderWorldCueState | null {
  const activeOrderId =
    state.activeFrontlineSupportOrderId !== null && state.frontlineSupportOrderTimer > 0
      ? state.activeFrontlineSupportOrderId
      : null;

  if (!activeOrderId) {
    if (state.extractionReady && state.activeExtractId !== null && state.extractionHoldTimer <= 0) {
      const focusedExtract = getFocusedExtractForState(state);
      return {
        orderId: null,
        label: `Planned Exfil // ${focusedExtract.label.toUpperCase()}`,
        detail: `The boys are already leaning screens and casualty pulls toward ${focusedExtract.label.toLowerCase()} before the beacon burns.`,
        position: focusedExtract.position,
        color: 0x2dd4bf,
        accent: 0xccfbf1,
        radius: Math.max(32, focusedExtract.radius - 18)
      };
    }

    return null;
  }

  if (activeOrderId === "shift-fire") {
    const focusedIncident = getFocusedFrontlineIncidentForState(state);
    return {
      orderId: activeOrderId,
      label: `Cover Me // ${(focusedIncident?.label ?? "Next hot lane").toUpperCase()}`,
      detail: focusedIncident
        ? `Suppressive mark fixed on ${focusedIncident.label.toLowerCase()} so the shove lands under cover.`
        : "Suppressive mark fixed on the next hot lane so the shove lands under cover.",
      position: getSupportObjectiveTargetForState(state),
      color: 0x38bdf8,
      accent: 0xe0f2fe,
      radius: focusedIncident ? Math.max(26, focusedIncident.radius * 0.42) : 42
    };
  }

  if (activeOrderId === "draw-heat") {
    return {
      orderId: activeOrderId,
      label: "Pull Eyes Off // WIDE FEINT",
      detail: "Decoy mark fixed on the loud-side pocket so hostile eyes drag away from your shoulder.",
      position: getSupportDecoyTargetForState(state),
      color: 0xf97316,
      accent: 0xffedd5,
      radius: 46
    };
  }

  if (activeOrderId === "secure-exfil") {
    const focusedExtract = getFocusedExtractForState(state);
    return {
      orderId: activeOrderId,
      label: `Screen Exfil // ${focusedExtract.label.toUpperCase()}`,
      detail: `Fallback mark fixed on ${focusedExtract.label.toLowerCase()} so the last hold reads like a squad pull.`,
      position: focusedExtract.position,
      color: 0x4ade80,
      accent: 0xdcfce7,
      radius: Math.max(34, focusedExtract.radius - 14)
    };
  }

  const breachObstacle = getPriorityBreachObstacleForState(state);
  const breachPoint = breachObstacle ? getObstacleBreachPoint(breachObstacle) : null;
  const breachLabel = breachObstacle?.breach?.label ?? "Live cut";
  return {
    orderId: activeOrderId,
    label: `Stack Breach // ${breachLabel.toUpperCase()}`,
    detail: breachObstacle?.breach?.breached
      ? `Interior flood mark fixed through ${breachLabel.toLowerCase()} while the boys hold the follow-through.`
      : `Breach mark fixed on ${breachLabel.toLowerCase()} so the stack crashes one live cut together.`,
    position: breachPoint,
    color: 0xfb7185,
    accent: 0xffe4e6,
    radius: breachObstacle?.breach?.breached ? 54 : 40
  };
}

function getExtractSupportStagePoint(
  extract: Pick<RaidExtractDefinition, "position" | "radius">,
  slot: number,
  role: "fireteam" | "recovery"
): Vec2 {
  const flankSign = slot % 2 === 0 ? -1 : 1;
  const depthOffset = role === "fireteam" ? 0.62 : 0.28;
  const sideOffset = role === "fireteam" ? 42 : 26;
  return {
    x: clamp(extract.position.x - extract.radius * depthOffset + Math.floor(slot / 2) * 22, 48, WORLD_WIDTH - 48),
    y: clamp(extract.position.y + flankSign * (sideOffset + Math.floor(slot / 2) * 18), 48, WORLD_HEIGHT - 48)
  };
}

function getPlannedExtractCueSupportLabel(label: string | null | undefined, fallback: string): string {
  if (!label) {
    return fallback;
  }

  const trimmed = label.trim();
  if (!trimmed) {
    return fallback;
  }

  return trimmed
    .replace(/\s+(team|fire|scouts|markers)$/i, "")
    .replace(/\s+/g, " ")
    .trim();
}

function getPlannedExtractCommitProfile(state: RaidState, availableFireteams: number): {
  bankLoaded: boolean;
  hotLoaded: boolean;
  emergencyPeel: boolean;
  screenCommitCount: number;
  hardCommitCount: number;
} {
  const pendingCrashSoon =
    state.pendingReinforcements.length > 0 &&
    state.pendingReinforcements.some((entry) => entry.timer <= 12 || entry.source === "extraction-wave");
  const carriedManifestCount =
    state.carriedManifest.intel +
    state.carriedManifest.medical +
    state.carriedManifest.munitions +
    state.carriedManifest.hardware;
  const recoveryDriven = isRecoveryDrivenRaidState(state);
  const bankLoaded =
    state.carriedValue >= 180 || carriedManifestCount > 0 || state.activeContract.completed || recoveryDriven;
  const criticalMateCount = state.squadMates.filter((mate) => mate.condition === "critical").length;
  const squadStrained = criticalMateCount > 0 || state.squadMates.filter((mate) => mate.condition === "heated").length >= 2;
  const hotLoaded =
    bankLoaded &&
    (pendingCrashSoon || state.soundPressure >= 0.78 || state.extractionContested || squadStrained || recoveryDriven);
  const screenCommitCount = Math.min(
    availableFireteams,
    pendingCrashSoon || state.soundPressure >= 0.82 || bankLoaded ? 2 : 1
  );
  const emergencyPeel = hotLoaded && availableFireteams >= 2 && (state.extractionContested || criticalMateCount > 0);

  return {
    bankLoaded,
    hotLoaded,
    emergencyPeel,
    screenCommitCount,
    hardCommitCount: hotLoaded ? Math.min(screenCommitCount, emergencyPeel ? 2 : 1) : 0
  };
}

function isPlannedExtractSupportActive(state: RaidState): boolean {
  const activeOrderId =
    state.activeFrontlineSupportOrderId !== null && state.frontlineSupportOrderTimer > 0
      ? state.activeFrontlineSupportOrderId
      : null;
  return activeOrderId === null && state.extractionReady && state.activeExtractId !== null && state.extractionHoldTimer <= 0;
}

function getPlannedExtractStageMetrics(state: RaidState): {
  focusedExtract: RaidExtractDefinition;
  fireteams: FrontlineSupportState[];
  logisticsTracks: FrontlineSupportState[];
  commitProfile: ReturnType<typeof getPlannedExtractCommitProfile>;
  stagedFireteams: number;
  stagedRecoveryTracks: number;
  stagedFallbacks: number;
} | null {
  if (!isPlannedExtractSupportActive(state)) {
    return null;
  }

  const focusedExtract = getFocusedExtractForState(state);
  const fireteams = state.frontlineSupports.filter((support) => support.kind === "fireteam" && !support.playerEscort);
  const logisticsTracks = state.frontlineSupports.filter(
    (support) => support.kind === "recovery" || support.kind === "convoy"
  );
  const commitProfile = getPlannedExtractCommitProfile(state, fireteams.length);
  const stagedFireteams = fireteams.filter((support, index) => {
    const stagePoint = getExtractSupportStagePoint(focusedExtract, index, "fireteam");
    return (
      distance(support.target, stagePoint) <= 96 || distance(support.position, focusedExtract.position) <= focusedExtract.radius + 120
    );
  }).length;
  const stagedRecoveryTracks = logisticsTracks.filter((support, index) => {
    const stagePoint = getExtractSupportStagePoint(focusedExtract, index, "recovery");
    return (
      distance(support.target, stagePoint) <= 104 ||
      distance(support.position, focusedExtract.position) <= focusedExtract.radius + 118
    );
  }).length;
  const stagedFallbacks = state.frontlineIncidents.filter((incident) => {
    if (incident.resolved || (incident.kind !== "convoy" && incident.kind !== "casualty")) {
      return false;
    }
    return (
      incident.status === "extracting" ||
      distance(incident.target, focusedExtract.position) <= focusedExtract.radius + 124 ||
      distance(incident.position, focusedExtract.position) <= focusedExtract.radius + 116
    );
  }).length;

  return {
    focusedExtract,
    fireteams,
    logisticsTracks,
    commitProfile,
    stagedFireteams,
    stagedRecoveryTracks,
    stagedFallbacks
  };
}

export function getPlannedExtractBenefit(state: RaidState): PlannedExtractBenefitState | null {
  const metrics = getPlannedExtractStageMetrics(state);
  if (!metrics) {
    return null;
  }

  const holdReliefSeconds = clamp(
    metrics.stagedRecoveryTracks * 0.18 +
      metrics.stagedFallbacks * 0.12 +
      (metrics.commitProfile.hardCommitCount > 0 ? 0.22 : 0) +
      (metrics.stagedFireteams >= 2 ? 0.18 : metrics.stagedFireteams >= 1 ? 0.08 : 0),
    0,
    0.9
  );
  const nearbyRingThreats = state.enemies.filter(
    (enemy) => distance(enemy.position, metrics.focusedExtract.position) <= metrics.focusedExtract.radius + 112
  ).length;
  const screenedThreats = Math.min(
    nearbyRingThreats,
    Math.max(
      0,
      metrics.stagedFireteams * 2 + metrics.commitProfile.hardCommitCount + (metrics.stagedFallbacks > 0 ? 1 : 0)
    )
  );
  const delayedWaveSeconds = clamp(
    metrics.stagedRecoveryTracks * 0.18 +
      metrics.commitProfile.hardCommitCount * 0.32 +
      metrics.stagedFallbacks * 0.08,
    0,
    1.1
  );

  return {
    holdReliefSeconds,
    screenedThreats,
    delayedWaveSeconds
  };
}

export function getSquadLaneReadout(state: RaidState, index: number): EscortCommandLaneReadout {
  const mate = state.squadMates[index];
  if (mate) {
    return getSquadMateCommandLaneReadout(mate.command);
  }

  const activeOrderId =
    state.activeFrontlineSupportOrderId !== null && state.frontlineSupportOrderTimer > 0
      ? state.activeFrontlineSupportOrderId
      : null;

  return getEscortCommandLaneReadout(activeOrderId, index, isPlannedExtractSupportActive(state));
}

export function getPlannedExtractPosture(state: RaidState): PlannedExtractPostureState | null {
  const metrics = getPlannedExtractStageMetrics(state);
  if (!metrics) {
    return null;
  }
  const { focusedExtract, commitProfile, stagedFireteams, stagedRecoveryTracks, stagedFallbacks } = metrics;
  const benefit = getPlannedExtractBenefit(state);
  const benefitDetail = benefit
    ? `${benefit.screenedThreats} ring threat${benefit.screenedThreats === 1 ? "" : "s"} softened, about ${benefit.holdReliefSeconds.toFixed(1)}s shaved off the eventual hold${benefit.delayedWaveSeconds > 0 ? `, and ${benefit.delayedWaveSeconds.toFixed(1)}s of extra sweep slack banked` : ""}.`
    : "";

  const detail =
    commitProfile.hardCommitCount >= 2 && stagedFireteams >= 2
      ? `The haul is already worth banking and the pull is breaking now, so two non-escort screen teams are hard-committed onto ${focusedExtract.label.toLowerCase()} before the beacon burns. ${benefitDetail}`.trim()
      : commitProfile.hardCommitCount > 0 && stagedFireteams >= 2
        ? `The haul is already worth banking, so one non-escort screen team is hard-committed onto ${focusedExtract.label.toLowerCase()} while a second stack shades the peel before the beacon burns. ${benefitDetail}`.trim()
      : commitProfile.hardCommitCount > 0 && stagedFireteams >= 1
        ? `The haul is already worth banking, so one non-escort screen team is hard-committed onto ${focusedExtract.label.toLowerCase()} before the beacon burns and the rest of the pull is bending that way. ${benefitDetail}`.trim()
        : commitProfile.hardCommitCount > 0
          ? `The haul is already worth banking, so the first non-escort screen team is being hard-committed onto ${focusedExtract.label.toLowerCase()} right now while recovery traffic and fallback lanes bend behind it. ${benefitDetail}`.trim()
        : stagedFireteams >= 2
          ? `Two non-escort screen teams are already shading ${focusedExtract.label.toLowerCase()} so the last move reads like a planned squad peel, not a panic sprint. ${benefitDetail}`.trim()
          : stagedFireteams === 1
            ? `One non-escort screen team and the recovery tracks are already staging toward ${focusedExtract.label.toLowerCase()} so the pull has bodies on it before you commit the hold. ${benefitDetail}`.trim()
            : stagedFallbacks > 0
              ? `The chosen pull is already dragging recovery traffic and fallback lanes toward ${focusedExtract.label.toLowerCase()} before the beacon burns. ${benefitDetail} Fire Screen Exfil if you want a dedicated screen team stacked on the ring now.`.trim()
              : `Recovery traffic is already bending toward ${focusedExtract.label.toLowerCase()}, but the wedge still needs an explicit Screen Exfil call before a dedicated screen team commits deeper onto the pull. ${benefitDetail}`.trim();
  const status = `${stagedFireteams} screen${stagedFireteams === 1 ? "" : "s"} | ${stagedRecoveryTracks} recovery${stagedRecoveryTracks === 1 ? " track" : " tracks"} | ${stagedFallbacks} fallback${stagedFallbacks === 1 ? "" : "s"}${commitProfile.hardCommitCount > 0 ? ` | ${commitProfile.hardCommitCount} hot-committed` : ""}${benefit ? ` | -${benefit.holdReliefSeconds.toFixed(1)}s hold | ${benefit.screenedThreats} softened` : ""}`;
  const tone: SquadBattleRead["tone"] =
    stagedFireteams >= 1 || stagedFallbacks > 0 ? "extract" : stagedRecoveryTracks > 0 ? "warning" : "steady";

  return {
    title: `Pre-Beacon Posture // ${focusedExtract.label.toUpperCase()}`,
    detail,
    status,
    tone,
    stagedFireteams,
    hardCommittedFireteams: commitProfile.hardCommitCount,
    stagedRecoveryTracks,
    stagedFallbacks
  };
}

export function getPlannedExtractStageCues(state: RaidState): PlannedExtractStageCueState[] {
  const metrics = getPlannedExtractStageMetrics(state);
  if (!metrics) {
    return [];
  }

  const { focusedExtract, fireteams, logisticsTracks, commitProfile } = metrics;
  const fallbackIncident = state.frontlineIncidents.find((incident) => {
    if (incident.resolved || (incident.kind !== "convoy" && incident.kind !== "casualty")) {
      return false;
    }

    return (
      incident.status === "extracting" ||
      distance(incident.target, focusedExtract.position) <= focusedExtract.radius + 124 ||
      distance(incident.position, focusedExtract.position) <= focusedExtract.radius + 116
    );
  });
  const plannedExtractFireteamCommitCount = commitProfile.screenCommitCount;
  const cues: PlannedExtractStageCueState[] = [];

  for (let index = 0; index < plannedExtractFireteamCommitCount; index += 1) {
    const fireteam = fireteams[index];
    const stagePoint = getExtractSupportStagePoint(focusedExtract, index, "fireteam");
    const supportLabel = getPlannedExtractCueSupportLabel(fireteam?.label, index === 0 ? "First screen" : `Screen ${index + 1}`);
    const position =
      fireteam &&
      (distance(fireteam.target, stagePoint) <= 120 || distance(fireteam.position, focusedExtract.position) <= focusedExtract.radius + 144)
        ? fireteam.position
        : stagePoint;
    const compactLabel =
      index === 0 && commitProfile.hardCommitCount > 0
        ? `${supportLabel} hard-committed`
        : index === 1 && commitProfile.hardCommitCount > 1
          ? `${supportLabel} hot second screen`
          : index === 0
            ? `${supportLabel} leaning first screen`
            : `${supportLabel} leaning screen`;
    cues.push({
      label:
        index === 0 && commitProfile.hardCommitCount > 0
          ? `Hard Screen // ${supportLabel.toUpperCase()}`
        : index === 1 && commitProfile.hardCommitCount > 1
            ? `Hard Screen // ${supportLabel.toUpperCase()}`
          : index === 0
            ? `Lean Screen // ${supportLabel.toUpperCase()}`
            : `Lean Screen // ${supportLabel.toUpperCase()}`,
      supportLabel,
      compactLabel,
      detail:
        index === 0 && commitProfile.hardCommitCount > 0
          ? `${supportLabel} is already hard-committed onto ${focusedExtract.label.toLowerCase()} because the haul is worth banking now.`
          : index === 1 && commitProfile.hardCommitCount > 1
            ? `${supportLabel} is also hard-committed onto ${focusedExtract.label.toLowerCase()} because the ring is breaking or a boy is critical.`
          : index === 0
            ? `${supportLabel} is already shading ${focusedExtract.label.toLowerCase()} before the beacon burns.`
          : `${supportLabel} is drifting toward ${focusedExtract.label.toLowerCase()} so the chosen pull reads rehearsed, not panicked.`,
      position,
      color: 0x4ade80,
      accent: 0xdcfce7,
      radius: 18 + index * 2
    });
  }

  if (logisticsTracks.length > 0) {
    const recoveryTrack = logisticsTracks[0];
    const stagePoint = getExtractSupportStagePoint(focusedExtract, 0, "recovery");
    const supportLabel = getPlannedExtractCueSupportLabel(recoveryTrack.label, "Recovery");
    const position =
      distance(recoveryTrack.target, stagePoint) <= 120 || distance(recoveryTrack.position, focusedExtract.position) <= focusedExtract.radius + 132
        ? recoveryTrack.position
        : stagePoint;
    cues.push({
      label: `Bag Pull // ${supportLabel.toUpperCase()}`,
      supportLabel,
      compactLabel: `${supportLabel} dragging bags`,
      detail: `${supportLabel} is already bending toward ${focusedExtract.label.toLowerCase()} so loose haul and bodies have a cleaner peel lane.`,
      position,
      color: 0xfbbf24,
      accent: 0xfef3c7,
      radius: 16
    });
  }

  if (fallbackIncident) {
    const supportLabel = getPlannedExtractCueSupportLabel(fallbackIncident.label, "Fallback lane");
    cues.push({
      label: `Fallback Lane // ${supportLabel.toUpperCase()}`,
      supportLabel,
      compactLabel: `${supportLabel} feeding fallback`,
      detail: `${supportLabel} is already feeding fallback traffic toward ${focusedExtract.label.toLowerCase()} before the hard Screen Exfil call lands.`,
      position: fallbackIncident.position,
      color: 0x38bdf8,
      accent: 0xe0f2fe,
      radius: Math.max(14, Math.min(20, fallbackIncident.radius * 0.45))
    });
  }

  return cues;
}

interface SquadStrainMetrics {
  escortSupport: FrontlineSupportState | null;
  criticalMates: SquadMateState[];
  heatedMates: SquadMateState[];
  hottestMate: SquadMateState | null;
  averageReadiness: number;
  totalMedCover: number;
  totalAmmoCover: number;
  waveSoon: boolean;
  bankLoaded: boolean;
  medTight: boolean;
  ammoTight: boolean;
  playerHurt: boolean;
  playerCritical: boolean;
  escortAmmoRatio: number;
  escortAmmoThin: boolean;
  escortDry: boolean;
  escortReloading: boolean;
  nearestEnemyDistance: number | null;
  closeHostiles: boolean;
  ringHot: boolean;
}

function formatReinforcementComposition(entries: ReadonlyArray<PendingReinforcementState>): string {
  const counts = new Map<EnemyArchetypeId, number>();

  for (const entry of entries) {
    counts.set(entry.archetypeId, (counts.get(entry.archetypeId) ?? 0) + 1);
  }

  return [...counts.entries()]
    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
    .map(([archetypeId, count]) => {
      const label =
        archetypeId === "rusher"
          ? count === 1
            ? "rusher"
            : "rushers"
          : archetypeId === "skirmisher"
            ? count === 1
              ? "skirmisher"
              : "skirmishers"
            : count === 1
              ? "rifleman"
              : "riflemen";
      return `${count} ${label}`;
    })
    .join(" | ");
}

function getSquadStrainMetrics(state: RaidState): SquadStrainMetrics {
  const criticalMates = state.squadMates.filter((mate) => mate.condition === "critical");
  const heatedMates = state.squadMates.filter((mate) => mate.condition === "heated");
  const averageReadiness =
    state.squadMates.reduce((total, mate) => total + mate.readiness, 0) / Math.max(1, state.squadMates.length);
  const hottestMate =
    criticalMates[0] ??
    heatedMates[0] ??
    state.squadMates.reduce<SquadMateState | null>(
      (lowest, mate) => (lowest === null || mate.readiness < lowest.readiness ? mate : lowest),
      null
    );
  const totalMedCover = state.player.medkits + state.carriedSupplies.medkits;
  const totalAmmoCover = state.player.reserveAmmo + state.carriedSupplies.ammoPacks * 18;
  const waveSoon =
    state.pendingReinforcements.length > 0 &&
    state.pendingReinforcements.some((entry) => entry.timer <= 12 || entry.source === "extraction-wave");
  const bankLoaded =
    state.carriedValue > 0 ||
    state.carriedManifest.intel +
      state.carriedManifest.medical +
      state.carriedManifest.munitions +
      state.carriedManifest.hardware >
      0 ||
    state.activeContract.completed;
  const medTight = totalMedCover <= 1;
  const ammoTight = totalAmmoCover <= 36;
  const playerHurt = state.player.health <= 60;
  const playerCritical = state.player.health <= 38;
  const escortSupport = state.frontlineSupports.find((support) => support.playerEscort) ?? null;
  const escortWeapon = escortSupport ? WEAPONS[escortSupport.weaponId] : null;
  const escortAmmoRatio =
    escortSupport !== null && escortWeapon !== null && escortWeapon.magazineSize > 0
      ? escortSupport.ammoInMag / escortWeapon.magazineSize
      : 1;
  const escortMagazineSize = escortWeapon?.magazineSize ?? 0;
  const escortAmmoThin =
    escortSupport !== null &&
    (escortSupport.reserveAmmo <= Math.max(escortMagazineSize, 14) || escortAmmoRatio <= 0.25);
  const escortDry = escortSupport !== null && escortSupport.ammoInMag <= 0 && escortSupport.reserveAmmo <= 0;
  const escortReloading = escortSupport !== null && escortSupport.reloadTimer > 0;
  const nearestEnemyDistance =
    state.enemies.length > 0
      ? state.enemies.reduce((best, enemy) => {
          const currentDistance = distance(enemy.position, state.player.position);
          return Math.min(best, currentDistance);
        }, Number.POSITIVE_INFINITY)
      : null;
  const closeHostiles = nearestEnemyDistance !== null && nearestEnemyDistance <= 190;
  const ringHot = state.extractionContested || waveSoon || state.soundPressure >= 0.82;

  return {
    escortSupport,
    criticalMates,
    heatedMates,
    hottestMate,
    averageReadiness,
    totalMedCover,
    totalAmmoCover,
    waveSoon,
    bankLoaded,
    medTight,
    ammoTight,
    playerHurt,
    playerCritical,
    escortAmmoRatio,
    escortAmmoThin,
    escortDry,
    escortReloading,
    nearestEnemyDistance,
    closeHostiles,
    ringHot
  };
}

export function getReinforcementPressureRead(state: RaidState): ReinforcementPressureRead | null {
  if (state.pendingReinforcements.length === 0) {
    return null;
  }

  const nextWave = state.pendingReinforcements.reduce((best, pending) => (pending.timer < best.timer ? pending : best));
  const matchingEntries = state.pendingReinforcements.filter(
    (pending) => pending.label === nextWave.label && pending.source === nextWave.source
  );
  const totalCount = state.pendingReinforcements.length;
  const composition = formatReinforcementComposition(matchingEntries);
  const otherStacks = totalCount - matchingEntries.length;
  const focusedExtract = getFocusedExtractForState(state);
  const targetLabel = nextWave.source === "extraction-wave" ? focusedExtract.label : "the hot lane";
  const leadWeapon = WEAPONS[getArchetypeWeaponId(nextWave.archetypeId)].name;
  const compositionVerb = matchingEntries.length === 1 ? "is" : "are";
  const tone: ReinforcementPressureRead["tone"] =
    nextWave.timer <= 0.7 || (nextWave.source === "extraction-wave" && nextWave.timer <= 1.2)
      ? "critical"
      : nextWave.timer <= 1.2 || matchingEntries.length >= 3
        ? "warning"
        : "steady";
  const title =
    nextWave.source === "extraction-wave" ? "Crash stack incoming" : `${nextWave.label} incoming`;
  const status = `${matchingEntries.length} inbound | ${nextWave.timer.toFixed(1)}s lead | ${composition}`;
  const detail =
    nextWave.source === "extraction-wave"
      ? `${composition} ${compositionVerb} stepping onto ${targetLabel.toLowerCase()} under red flares. ${leadWeapon} leads the first shoulder, so break the nearer arrival before the ring turns into a wipe.`
      : `${nextWave.label} is stepping in on the noise line with ${composition}. ${leadWeapon} leads the first shoulder, so cut the cleaner side before the sweep pins the route shut.`;
  const compactPrefix = nextWave.source === "extraction-wave" ? "Crash" : nextWave.label;
  const compact = `${compactPrefix} ${nextWave.timer.toFixed(1)}s | ${matchingEntries.length} inbound${otherStacks > 0 ? ` | +${otherStacks} elsewhere` : ""}`;
  const markerLabel =
    nextWave.source === "extraction-wave"
      ? `Crash ${nextWave.timer.toFixed(1)}s`
      : `${nextWave.label.replace(/\s+/g, " ").trim()} ${nextWave.timer.toFixed(1)}s`;

  return {
    title,
    status,
    detail,
    compact,
    tone,
    markerLabel
  };
}

export function getExtractSquadRiskRead(state: RaidState): ExtractSquadRiskState {
  const {
    criticalMates,
    heatedMates,
    hottestMate,
    averageReadiness,
    totalMedCover,
    waveSoon,
    bankLoaded,
    medTight,
    ammoTight,
    playerHurt,
    playerCritical,
    escortSupport,
    escortAmmoThin,
    escortDry,
    closeHostiles,
    ringHot
  } = getSquadStrainMetrics(state);

  let tone: ExtractSquadRiskState["tone"] = "steady";
  if (
    criticalMates.length >= 2 ||
    averageReadiness < 0.5 ||
    (criticalMates.length >= 1 && (waveSoon || state.extractionContested || playerCritical)) ||
    (escortDry && ringHot)
  ) {
    tone = "critical";
  } else if (
    criticalMates.length >= 1 ||
    heatedMates.length >= 2 ||
    averageReadiness < 0.72 ||
    (bankLoaded && (waveSoon || state.soundPressure >= 0.82)) ||
    playerHurt ||
    medTight ||
    escortAmmoThin ||
    closeHostiles
  ) {
    tone = "warning";
  }

  const hottestLabel = hottestMate
    ? `${hottestMate.name} ${Math.round(hottestMate.readiness * 100)}% ${hottestMate.condition}`
    : "No squad telemetry";
  const sustainBits: string[] = [];
  sustainBits.push(`${Math.round(averageReadiness * 100)}% ready`);
  sustainBits.push(criticalMates.length > 0 ? `${criticalMates.length} critical` : `${heatedMates.length} heated`);
  if (medTight) {
    sustainBits.push(totalMedCover <= 0 ? "no dressings" : `${totalMedCover} dressing left`);
  } else if (ammoTight) {
    sustainBits.push("ammo thin");
  }
  if (escortDry) {
    sustainBits.push("escort dry");
  } else if (escortAmmoThin) {
    sustainBits.push("escort mags low");
  }
  if (closeHostiles) {
    sustainBits.push("contact inside 190u");
  }
  const status = `${hottestLabel} | ${sustainBits.join(" | ")}`;

  let detail = "The boys can still afford one clean extra pocket if the lane stays disciplined.";
  if (tone === "critical" && escortDry && ringHot) {
    detail = `${escortSupport?.label ?? "The wedge"} is dry while the ring is collapsing. Extract before the boys get pinned into a body drag.`;
  } else if (tone === "critical") {
    detail =
      criticalMates.length >= 2
        ? `${criticalMates
            .slice(0, 2)
            .map((mate) => mate.name)
            .join(" and ")} are breaking. Extract before this becomes a body drag.`
        : `${hottestMate?.name ?? "The wedge"} is hanging on ${hottestMate?.assignment?.toLowerCase() ?? "the pull"}. Another loud pocket risks losing a boy on exit.`;
  } else if (criticalMates.length >= 1) {
    detail = `${hottestMate?.name ?? "The wedge"} is critical on ${hottestMate?.assignment?.toLowerCase() ?? "the fallback lane"}. Only stay if the next touch is cleaner than the pull.`;
  } else if (escortAmmoThin && ringHot) {
    detail = `${escortSupport?.label ?? "Your escort"} is burning through mags faster than the route is calming down. Pull clean unless the next touch cashes real value.`;
  } else if (heatedMates.length >= 2 || averageReadiness < 0.72) {
    detail = `${hottestMate?.name ?? "The boys"} and the wedge are burning down. Greed should buy real stash value.`;
  } else if (bankLoaded && (waveSoon || state.soundPressure >= 0.82)) {
    detail = "The route is heating faster than the boys are resetting. Treat the next touch as a gamble.";
  } else if (medTight) {
    detail = "Medical cover is thin. A clean extract locks the profit before the boys trade health for cargo.";
  } else if (closeHostiles) {
    detail = "Blue is already inside grenade distance. The squad still has legs, but the route has stopped being a free reset pocket.";
  }

  return {
    title: tone === "critical" ? "Boys about to break" : tone === "warning" ? "Boys running hot" : "Boys still steady",
    status,
    detail,
    compact: `${hottestMate?.name ?? "Net"} ${hottestMate?.condition ?? "steady"} | ${Math.round(averageReadiness * 100)}% ready`,
    tone
  };
}

export function getSquadStrainRead(state: RaidState): SquadStrainRead {
  const {
    escortSupport,
    hottestMate,
    averageReadiness,
    medTight,
    ammoTight,
    escortAmmoRatio,
    escortAmmoThin,
    escortDry,
    escortReloading,
    nearestEnemyDistance,
    closeHostiles,
    ringHot,
    playerCritical
  } = getSquadStrainMetrics(state);
  const distanceLabel =
    nearestEnemyDistance === null || !Number.isFinite(nearestEnemyDistance)
      ? "No close hostile"
      : `${nearestEnemyDistance.toFixed(0)}u hostile`;

  let tone: SquadStrainRead["tone"] = "steady";
  if ((escortDry && ringHot) || playerCritical || averageReadiness < 0.52) {
    tone = "critical";
  } else if (escortAmmoThin || closeHostiles || medTight || ammoTight || averageReadiness < 0.72) {
    tone = "warning";
  }

  const escortLabel = escortSupport?.label ?? "Escort wedge";
  const ammoLabel = escortDry
    ? "Dry on mags"
    : escortAmmoThin
      ? `Mag pressure ${Math.round(escortAmmoRatio * 100)}%`
      : escortReloading
        ? "Reloading through contact"
        : "Ammo holding";
  const hottestLabel = hottestMate
    ? `${hottestMate.name} ${Math.round(hottestMate.readiness * 100)}% ${hottestMate.condition}`
    : "No named boys online";
  const title =
    tone === "critical" ? "Net collapsing" : tone === "warning" ? "Net running hot" : "Net still disciplined";
  const status = `${escortLabel} | ${ammoLabel} | ${distanceLabel}`;
  let detail = `${hottestLabel}. The boys still have enough shape to push one cleaner pocket.`;

  if (tone === "critical") {
    detail = escortDry
      ? `${escortLabel} is out of mags while the route is still hot. ${hottestMate?.name ?? "The boys"} are one bad trade away from a body-drag extract.`
      : `${hottestMate?.name ?? "The boys"} are slipping under live pressure. The next decision should shorten the route, not widen it.`;
  } else if (escortAmmoThin) {
    detail = `${escortLabel} is burning its last comfortable magazines. ${hottestMate?.name ?? "The boys"} can still shove, but the next touch needs payoff.`;
  } else if (closeHostiles) {
    detail = `${distanceLabel}. The squad still looks coherent, but this is no longer a free reset pocket for meds, loot, or reloading.`;
  } else if (medTight || ammoTight) {
    detail = `Sustain is thinning behind the wedge. ${hottestMate?.name ?? "The boys"} should only stay if the route is still buying stash value.`;
  }

  return {
    title,
    status,
    detail,
    compact: `${ammoLabel} | ${distanceLabel} | ${Math.round(averageReadiness * 100)}% ready`,
    tone
  };
}

export function getSquadMateStrainRead(state: RaidState, index: number): SquadMateStrainRead {
  const mate = state.squadMates[index];
  if (!mate) {
    return {
      label: "No read",
      detail: "No named boy is staged in this slot.",
      tone: "steady"
    };
  }

  const squadStrain = getSquadStrainRead(state);
  const escortSupport = state.frontlineSupports.find((support) => support.playerEscort) ?? null;
  const laneReadout = getSquadLaneReadout(
    state,
    index
  );
  const escortWeapon = escortSupport ? WEAPONS[escortSupport.weaponId] : null;
  const escortAmmoRatio =
    escortSupport && escortWeapon?.magazineSize ? escortSupport.ammoInMag / escortWeapon.magazineSize : 1;
  const escortDry = escortSupport !== null && escortSupport.ammoInMag <= 0 && escortSupport.reserveAmmo <= 0;
  const escortAmmoThin =
    escortSupport !== null &&
    (escortDry || escortSupport.reserveAmmo <= Math.max(escortWeapon?.magazineSize ?? 0, 14) || escortAmmoRatio <= 0.25);
  const activePull =
    state.extractionHoldTimer > 0 || state.extractionContested
      ? "extract ring"
      : state.activeFrontlineIncidentAction !== null
        ? "live beat"
        : "route shoulder";

  if (mate.condition === "critical") {
    return {
      label: "Breaking",
      detail: `${mate.name} is hanging on ${laneReadout.slotLabel.toLowerCase()} while the ${activePull} stays hot.`,
      tone: "critical"
    };
  }

  if (escortDry) {
    return {
      label: "Cover gone",
      detail: `${mate.name} is still on ${laneReadout.slotLabel.toLowerCase()}, but the escort wedge is dry on mags.`,
      tone: "critical"
    };
  }

  if (escortAmmoThin) {
    return {
      label: "Mags thin",
      detail: `${mate.name} can still work ${laneReadout.slotLabel.toLowerCase()}, but the shared escort guns are running lean.`,
      tone: "warning"
    };
  }

  if (mate.condition === "heated" || squadStrain.tone === "warning") {
    return {
      label: "Running hot",
      detail: `${mate.name} is still controlling ${laneReadout.slotLabel.toLowerCase()}, but the lane is too hot for a lazy peek.`,
      tone: "warning"
    };
  }

  return {
    label: "Holding shape",
    detail: `${mate.name} has room to keep ${laneReadout.slotLabel.toLowerCase()} disciplined while the wedge stays coherent.`,
    tone: "steady"
  };
}

export function getEscortCommandPose(
  orderId: FrontlineSupportOrderId | null,
  flankSign: number,
  underPressure: boolean,
  plannedExtractLean = false
): EscortCommandPose {
  const lateralBias = flankSign >= 0 ? 1 : -1;

  if (orderId === "breach-push") {
    return {
      anchorOffset: { x: -30, y: 8 * lateralBias },
      targetOffset: { x: 58, y: 10 * lateralBias },
      holdRadius: 86,
      note: "The boys are tight on your shoulder and stacked to flood the cut the moment the lane opens."
    };
  }

  if (orderId === "secure-exfil") {
    return {
      anchorOffset: { x: -40, y: 28 * lateralBias },
      targetOffset: { x: 12, y: 26 * lateralBias },
      holdRadius: 108,
      note: "The boys are stretched across the fallback shoulder, screening the ring and catching the route collapse behind you."
    };
  }

  if (orderId === "draw-heat") {
    return {
      anchorOffset: { x: -18, y: 36 * lateralBias },
      targetOffset: { x: 76, y: 52 * lateralBias },
      holdRadius: 102,
      note: underPressure
        ? "The boys are pulling wide and dragging hostile eyes off your line so the route stops staring straight at you."
        : "The boys are widening into a loud shoulder feint, ready to drag the next pocket off your push."
    };
  }

  if (orderId === "shift-fire") {
    return {
      anchorOffset: { x: -28, y: 34 * lateralBias },
      targetOffset: { x: 64, y: 24 * lateralBias },
      holdRadius: 98,
      note: "The boys are fanned off your shoulder and leaning into suppressive lanes so your next step lands under cover."
    };
  }

  if (orderId === "hold-position") {
    return {
      anchorOffset: { x: -38, y: 30 * lateralBias },
      targetOffset: { x: 10, y: 34 * lateralBias },
      holdRadius: 114,
      note: underPressure
        ? "The boys are dug into the near shoulder, watching cross angles, and making Blue pry the pocket back open."
        : "The boys are settling into the near shoulder and turning it into a proper foothold before the next shove."
    };
  }

  if (plannedExtractLean) {
    return {
      anchorOffset: { x: -34, y: 20 * lateralBias },
      targetOffset: { x: 30, y: 32 * lateralBias },
      holdRadius: 100,
      note: underPressure
        ? "The boys are already canting toward the named pull so the fallback shoulder forms before the route fully collapses."
        : "The boys are leaning toward the named pull and rehearsing the exfil shoulder before you burn the beacon."
    };
  }

  return {
    anchorOffset: { x: -28, y: 24 * lateralBias },
    targetOffset: { x: 44, y: 24 * lateralBias },
    holdRadius: 92,
    note: underPressure
      ? "The boys are glued to your shoulder and trading through the live lane while you work the push."
      : "The boys are following your push in a live wedge and staying close enough to share the next peek."
  };
}

export function getEscortCommandLaneReadout(
  orderId: FrontlineSupportOrderId | null,
  index: number,
  plannedExtractLean = false
): EscortCommandLaneReadout {
  const directive = orderId ? getSupportOrderLaneDirective(orderId, index) : null;
  if (directive) {
    return {
      slotLabel: directive.slotLabel,
      shorthand: directive.shorthand,
      detail: directive.detail
    };
  }

  if (plannedExtractLean) {
    return index === 0
      ? {
          slotLabel: "Lean screen",
          shorthand: "LEAN LEFT",
          detail: "Shades the chosen exfil mouth before the beacon burns so the peel starts under a real screen."
        }
      : index === 1
        ? {
            slotLabel: "Peel trail",
            shorthand: "PEEL MID",
            detail: "Holds the collapse lane behind the named pull so the route can peel clean instead of sprinting blind."
          }
        : {
            slotLabel: "Bag hand",
            shorthand: "BAG RIGHT",
            detail: "Keeps haul, dressings, and casualty hands on the safe shoulder of the planned pull."
          };
  }

  return index === 0
    ? {
        slotLabel: "Lead peek",
        shorthand: "POINT LEFT",
        detail: "Leads the left shoulder into the next peek and keeps the wedge moving."
      }
    : index === 1
      ? {
          slotLabel: "Center anchor",
          shorthand: "ANCHOR MID",
          detail: "Holds the center of the wedge so the line stays coherent under pressure."
        }
      : {
          slotLabel: "Medic trail",
          shorthand: "MED RIGHT",
          detail: "Trails right with dressings, haul, and the first recovery hand."
        };
}

