function shouldSpawnAmbientCoffeePocket(
  route: RaidRouteDefinition,
  sector: FrontlineSectorState | null,
  activeFrontlineDefinition: FrontlineOperationDefinition | null
): boolean {
  if (activeFrontlineDefinition !== null) {
    return false;
  }

  if (!sector || sector.control === "lost") {
    return false;
  }

  const moderatePressure = sector.pressure >= 40 && sector.pressure <= 72;
  const enoughScars = sector.scars >= (route.id === "crosswind-docks" ? 24 : 34);
  return moderatePressure && enoughScars;
}

function ageDialogueMemories(memories: ReadonlyArray<DialogueMemory>): DialogueMemory[] {
  return memories
    .map((memory) => ({
      ...memory,
      ageRaids: memory.ageRaids + 1,
      emotionalWeight: clamp(memory.emotionalWeight - 0.18, 0.12, 1)
    }))
    .filter((memory) => memory.ageRaids <= 4 && memory.emotionalWeight > 0.14)
    .slice(0, DIALOGUE_MEMORY_LIMIT);
}

export function mergeDialogueMemories(
  existing: ReadonlyArray<DialogueMemory>,
  additions: ReadonlyArray<DialogueMemory>
): DialogueMemory[] {
  const seen = new Set<string>();
  const merged: DialogueMemory[] = [];
  for (const memory of [...additions, ...ageDialogueMemories(existing)]) {
    const key = `${memory.tag}|${memory.subjectName}|${memory.routeName}`;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    merged.push(memory);
    if (merged.length >= DIALOGUE_MEMORY_LIMIT) {
      break;
    }
  }
  return merged;
}

function getDialogueMemoryTags(memories: ReadonlyArray<DialogueMemory>): DialogueMemoryTag[] {
  return [...new Set(memories.map((memory) => memory.tag))];
}

function buildMemorialCarryoverMemory(
  target: Pick<SquadRosterState, "name" | "casualtyRecord" | "lastOutcome">,
  tag: "family-informed" | "wake-held",
  emotionalWeight: number
): DialogueMemory {
  return {
    tag,
    subjectName: target.name,
    routeName: target.casualtyRecord?.routeName ?? target.lastOutcome,
    ageRaids: 0,
    emotionalWeight
  };
}

function mergeMemorialCarryoverIntoRoster(
  roster: ReadonlyArray<SquadRosterState>,
  target: Pick<SquadRosterState, "id" | "name" | "casualtyRecord" | "lastOutcome">,
  tag: "family-informed" | "wake-held",
  emotionalWeight: number
): SquadRosterState[] {
  const memory = buildMemorialCarryoverMemory(target, tag, emotionalWeight);
  return roster.map((mate) => {
    if (mate.status === "killed" || mate.id === target.id) {
      return mate;
    }

    return {
      ...mate,
      dialogueMemories: mergeDialogueMemories(mate.dialogueMemories, [memory])
    };
  });
}

