export function getSquadCommandAgeSeconds(command: SquadMateState["command"], timerRemaining: number): number {
  return Math.max(0, Number((getSquadCommandIssuedAtSeconds(timerRemaining) - command.issuedAtSeconds).toFixed(1)));
}

export function getSquadTacticalActionAgeSeconds(
  tacticalAction: NonNullable<SquadMateState["tacticalAction"]>,
  timerRemaining: number
): number {
  return Math.max(0, Number((getRaidElapsedSeconds(timerRemaining) - tacticalAction.issuedAtSeconds).toFixed(1)));
}

