function rollSquadSuppressBurstSize(
  profile: SquadSuppressProfile,
  shotsFired: number,
  shotsPlanned: number | null
): number {
  const progress = shotsPlanned && shotsPlanned > 0 ? shotsFired / shotsPlanned : 0;
  const roll = Math.random();
  if (profile.mode === "committed") {
    if (roll < 0.1) {
      return 1;
    }
    if (roll < 0.38) {
      return 3;
    }
    if (roll < 0.68) {
      return 4;
    }
    if (roll < 0.9) {
      return 5;
    }
    return 6;
  }

  if (progress < 0.25) {
    if (roll < 0.08) {
      return 2;
    }
    if (roll < 0.34) {
      return 5;
    }
    if (roll < 0.7) {
      return 6;
    }
    if (roll < 0.92) {
      return 4;
    }
    return 7;
  }

  if (progress < 0.68) {
    if (roll < 0.12) {
      return 1;
    }
    if (roll < 0.38) {
      return 3;
    }
    if (roll < 0.74) {
      return 5;
    }
    if (roll < 0.9) {
      return 4;
    }
    return 6;
  }

  if (roll < 0.26) {
    return 1;
  }
  if (roll < 0.52) {
    return 2;
  }
  if (roll < 0.8) {
    return 3;
  }
  if (roll < 0.94) {
    return 4;
  }
  return 2;
}

