const SQUAD_TACTICAL_ACTION_DEFINITIONS: Record<SquadTacticalActionId, SquadTacticalActionDefinition> = {
  grenade: {
    title: "Frag",
    createLabel: (position) => `frag ${formatSquadCommandAnchorLabel(position)}`,
    createState: (_weaponId, position, options) => ({
      targetLabel: `frag ${formatSquadCommandAnchorLabel(position)}`,
      targetRadius: null,
      durationSeconds: null,
      shotsPlanned: null,
      shotsFired: 0,
      burstShotsRemaining: null,
      requiresLineOfSight: false,
      suppressionProfile: null,
      source: options.source ?? null
    })
  },
  suppress: {
    title: "Suppress",
    createLabel: (position) => `suppress ${formatSquadCommandAnchorLabel(position)}`,
    createState: (weaponId, position, options) => {
      const suppressProfile = getSquadSuppressProfile(weaponId, options.source ?? null);
      return {
        targetLabel: `suppress ${formatSquadCommandAnchorLabel(position)}`,
        targetRadius: suppressProfile.targetRadius,
        durationSeconds: suppressProfile.durationSeconds,
        shotsPlanned: suppressProfile.shotsPlanned,
        shotsFired: 0,
        burstShotsRemaining: null,
        requiresLineOfSight: suppressProfile.mode === "committed",
        suppressionProfile: suppressProfile.id,
        source: options.source ?? null
      };
    }
  }
};

function getSquadTacticalActionDefinition(actionId: SquadTacticalActionId): SquadTacticalActionDefinition {
  return SQUAD_TACTICAL_ACTION_DEFINITIONS[actionId];
}

function getSquadTacticalActionTitle(actionId: SquadTacticalActionId): string {
  return getSquadTacticalActionDefinition(actionId).title;
}

function getSquadMateCommandDirective(command: SquadMateState["command"]): { assignment: string; tag: string } {
  if (command.orderId === "brace-watch") {
    return {
      assignment: command.watchLabel
        ? `Braced on ${command.watchLabel} and waiting to punish that sector`
        : "Braced on the ordered sector and waiting to punish that lane",
      tag: "WATCH"
    };
  }

  if (command.orderId === "move-watch") {
    return {
      assignment: command.watchLabel
        ? `Covering the move toward ${command.watchLabel} with controlled fire`
        : "Covering the move with controlled fire on the ordered sector",
      tag: "COVER"
    };
  }

  if (command.orderId === "defend") {
    return {
      assignment: command.anchorLabel
        ? `Holding ordered cover at ${command.anchorLabel}`
        : "Holding ordered cover and refusing the chase",
      tag: "HOLD"
    };
  }

  if (command.orderId === "attack") {
    return {
      assignment: "Pushing the live lane hard and hunting the break",
      tag: "ATTACK"
    };
  }

  return {
    assignment: "Following your shoulder and ready to peel with the squad",
    tag: "FOLLOW"
  };
}

function getSquadMateCommandLaneReadout(command: SquadMateState["command"]): EscortCommandLaneReadout {
  if (command.orderId === "brace-watch") {
    return {
      slotLabel: "Brace lane",
      shorthand: "WATCH",
      detail: command.watchLabel
        ? `Planted and braced on ${command.watchLabel}, ready to kill anything that crosses that sector.`
        : "Planted and braced on the ordered sector, ready to kill anything that crosses that lane."
    };
  }

  if (command.orderId === "move-watch") {
    return {
      slotLabel: "Covering move",
      shorthand: "COVER",
      detail: command.watchLabel
        ? `Moving while putting controlled fire onto ${command.watchLabel}, buying crossing time without planting.`
        : "Moving while putting controlled fire onto the ordered sector, buying crossing time without planting."
    };
  }

  if (command.orderId === "defend") {
    return {
      slotLabel: "Hold point",
      shorthand: "HOLD",
      detail: command.anchorLabel
        ? `Anchored on ${command.anchorLabel} and leaning nearby cover instead of chasing the lane.`
        : "Anchored on the ordered pocket and leaning nearby cover instead of chasing the lane."
    };
  }

  if (command.orderId === "attack") {
    return {
      slotLabel: "Aggro push",
      shorthand: "ATTACK",
      detail: "Cuts loose from safe shoulder spacing and pushes into reachable hostiles to finish the lane."
    };
  }

  return {
    slotLabel: "On you",
    shorthand: "ON YOU",
    detail: "Falls back onto your shoulder stack and stops drifting into isolated fights."
  };
}

const createSquadMates = (
  roster: ReadonlyArray<SquadRosterState>,
  route: RaidRouteDefinition,
  threatLabel: string
): SquadMateState[] =>
  {
    const unresolvedMemorialPenalty = getUnresolvedMemorialPenalty(roster);
    return roster
    .filter((mate) => mate.status === "active")
    .slice(0, ACTIVE_SQUAD_MATE_LIMIT)
    .map((mate, index) => {
      const directive = getSquadDirective(index, "advance", route, threatLabel, null, null);
      const weaponId = mate.weaponId;
      return {
        id: mate.id,
        name: mate.name,
        role: mate.role,
        voiceTag: mate.voiceTag,
        voiceSignature: mate.voiceSignature,
        weaponId,
        combatProfileId: getCombatProfileIdForWeapon(weaponId),
        assignment: directive.assignment,
        assignmentTag: directive.tag,
        command: createDefaultSquadMateCommand(weaponId),
        tacticalAction: null,
        condition: "steady",
        casualtyState: "healthy",
        woundSeverity: "none",
        bleedoutTimer: 0,
        stabilized: false,
        readiness: clamp(mate.readiness - unresolvedMemorialPenalty, 0.25, 1),
        recentDialogueMemories: mate.dialogueMemories.map((memory) => ({ ...memory }))
      };
    });
  };

function getDefaultSquadMateWeaponId(role: string, index: number): WeaponId {
  const roleLower = role.toLowerCase();

  if (roleLower.includes("breach") || roleLower.includes("shotgun")) {
    return "shotgun";
  }

  if (roleLower.includes("medic") || roleLower.includes("signal")) {
    return "smg";
  }

  if (roleLower.includes("support gunner")) {
    return "pkm";
  }

  return index === 1 ? "smg" : "rifle";
}

const SQUAD_LOADOUT_CYCLE: WeaponId[] = ["rifle", "smg", "shotgun", "pkm", "amr"];

function getNextSquadMateWeaponId(currentWeaponId: WeaponId, direction: 1 | -1): WeaponId {
  const currentIndex = SQUAD_LOADOUT_CYCLE.indexOf(currentWeaponId);
  const fallbackIndex = currentIndex === -1 ? 0 : currentIndex;
  const nextIndex = (fallbackIndex + direction + SQUAD_LOADOUT_CYCLE.length) % SQUAD_LOADOUT_CYCLE.length;
  return SQUAD_LOADOUT_CYCLE[nextIndex];
}

function getSquadDirective(
  index: number,
  context:
    | "extract-hot"
    | "extract-live"
    | "intel"
    | "haul"
    | "contact"
    | "civilian"
    | "surrender"
    | "claim-breaking"
    | "claim-held"
    | "claim-loss"
    | "advance",
  route: RaidRouteDefinition,
  threatLabel: string,
  activeOrderId: FrontlineSupportOrderId | null,
  focusedLabel: string | null
): { assignment: string; tag: string } {
  const pointPocket = focusedLabel ?? route.combatPockets[0]?.label ?? route.extractLabel;
  const pointPocketLower = pointPocket.toLowerCase();
  const extractLabelLower = route.extractLabel.toLowerCase();
  const threatLabelLower = threatLabel.toLowerCase();

  if (activeOrderId) {
    const directive = getSupportOrderLaneDirective(activeOrderId, index);
    return {
      assignment: fillOrderAssignmentTemplate(directive.assignment, {
        focusLower: pointPocketLower,
        extractLower: extractLabelLower
      }),
      tag: directive.tag
    };
  }

  if (context === "extract-hot") {
    return index === 0
      ? { assignment: "Cutting into the extract ring", tag: "BREAK" }
      : index === 1
        ? { assignment: "Bracing the reinforcement lane", tag: "TRAIL" }
        : { assignment: "Dragging dressings to the beacon", tag: "DRAG" };
  }

  if (context === "extract-live") {
    return index === 0
      ? { assignment: "Holding the exfil mouth", tag: "SCREEN" }
      : index === 1
        ? { assignment: "Watching the back trail", tag: "TRAIL" }
        : { assignment: "Packing the haul for pullout", tag: "BAG" };
  }

  if (context === "intel") {
    return index === 0
      ? { assignment: "Stacked on the intel terminal", tag: "STACK" }
      : index === 1
        ? { assignment: "Locking the long angle", tag: "ANGLE" }
        : { assignment: "Screening the breach for casualties", tag: "SCREEN" };
  }

  if (context === "haul") {
    return index === 0
      ? { assignment: "Holding over the search body", tag: "HOLD" }
      : index === 1
        ? { assignment: "Watching the route collapse", tag: "WATCH" }
        : { assignment: "Bagging meds and loose haul", tag: "BAG" };
  }

  if (context === "contact") {
    return index === 0
      ? { assignment: `Pinning ${pointPocket}`, tag: "PIN" }
      : index === 1
        ? { assignment: "Bracing the rear flank", tag: "BRACE" }
        : { assignment: "Sliding forward with dressings", tag: "MED" };
  }

  if (context === "civilian") {
    return index === 0
      ? { assignment: `Walking the family out of ${pointPocketLower} under muzzle discipline.`, tag: "WALK" }
      : index === 1
        ? { assignment: "Watching the shell lane so the shelter run does not fold into collateral.", tag: "COVER" }
        : { assignment: "Dragging dressings and spare water for the cellar pull.", tag: "AID" };
  }

  if (context === "surrender") {
    return index === 0
      ? { assignment: `Holding ${pointPocketLower} at gunpoint until the pocket fully gives up.`, tag: "HOLD" }
      : index === 1
        ? { assignment: "Bagging route notes and watching for one last dirty peek.", tag: "BAG" }
        : { assignment: "Screening the rear lane so the surrender does not turn back into a firefight.", tag: "SCREEN" };
  }

  if (context === "claim-breaking") {
    return index === 0
      ? { assignment: `Planting the route flag in ${pointPocketLower} before Blue can walk back onto it.`, tag: "FLAG" }
      : index === 1
        ? { assignment: "Holding the break lane wide so the flag team gets real seconds to finish the claim.", tag: "LOCK" }
        : { assignment: "Dragging dressings and spare mags onto the half-held scar before it slips.", tag: "SEAL" };
  }

  if (context === "claim-held") {
    return index === 0
      ? { assignment: `Holding the planted claim over ${pointPocketLower} so the next shove has real cover.`, tag: "HOLD" }
      : index === 1
        ? { assignment: "Watching the reclaim edge for Blue trying to retake the pocket.", tag: "ANCHOR" }
        : { assignment: "Feeding ammo and casualty cover into the flagged lane.", tag: "FEED" };
  }

  if (context === "claim-loss") {
    return index === 0
      ? { assignment: `Recovering bodies and tags off ${pointPocketLower} before the lane disappears for good.`, tag: "BAG" }
      : index === 1
        ? { assignment: "Holding the dead strip just long enough for the recovery to clear.", tag: "COVER" }
        : { assignment: "Dragging black bags and dressings off the scar for stash follow-through.", tag: "DRAG" };
  }

  return index === 0
    ? { assignment: `Pointing into ${pointPocket}`, tag: "POINT" }
    : index === 1
      ? { assignment: `Holding the ${extractLabelLower} fallback`, tag: "ANCHOR" }
      : { assignment: `Packing med and haul for ${threatLabelLower}`, tag: "MED" };
}

interface FrontlineCombatProfile {
  weaponId: WeaponId;
  speed: number;
  radius: number;
  fireRange: number;
  fireDamage: number;
  firePressureType: EnemyPressureType;
  firePressureDuration: number;
  fireIntervalMin: number;
  fireIntervalMax: number;
  magazineSize: number;
  reserveAmmo: number;
  reloadTime: number;
}

interface FrontlineTacticalSteer {
  target: Vec2;
  facing: Vec2;
  moveSpeed: number;
  push: boolean;
}

interface AutonomousCombatantSteer {
  awareness: "patrol" | "investigating" | "engaged";
  desiredDirection: Vec2;
  moveScale: number;
  navigationGoal: Vec2;
}

function createFrontlineCombatProfile(
  kind: FrontlineSupportKind | FrontlineIncidentKind,
  combatProfileId: EnemyArchetypeId
): FrontlineCombatProfile {
  const archetype = SCAV_ARCHETYPES[combatProfileId];
  const weaponId = getArchetypeWeaponId(combatProfileId);
  const weapon = WEAPONS[weaponId];
  const combatProfile = getSharedWeaponCombatProfile(weaponId, combatProfileId);
  const isLineUnit = kind === "fireteam" || kind === "firefight";
  const reserveAmmoMultiplier = isLineUnit ? 2.2 : kind === "convoy" ? 1.8 : kind === "bunker" ? 0 : 1.6;

  return {
    weaponId,
    speed: Math.round(archetype.patrolSpeed * (isLineUnit ? 0.62 : kind === "convoy" ? 0.5 : kind === "bunker" ? 0.42 : 0.54)),
    radius: combatProfileId === "rifleman" ? 18 : combatProfileId === "rusher" ? 19 : 17,
    fireRange: Math.max(140, Math.round(combatProfile.engageRange * (isLineUnit ? 1 : 0.9))),
    fireDamage: Math.max(
      4,
      Math.round(weapon.damage * combatProfile.frontlineDamageMultiplier * (isLineUnit ? 1 : 0.9))
    ),
    firePressureType: combatProfile.pressureType,
    firePressureDuration: combatProfile.pressureDuration,
    fireIntervalMin: combatProfile.fireIntervalMin * (isLineUnit ? 1.06 : 1.14),
    fireIntervalMax: combatProfile.fireIntervalMax * (isLineUnit ? 1.12 : 1.2),
    magazineSize: weapon.magazineSize,
    reserveAmmo: Math.max(weapon.magazineSize, Math.round(weapon.magazineSize * reserveAmmoMultiplier)),
    reloadTime: weapon.reloadTime
  };
}

function getCombatProfileIdForWeapon(weaponId: WeaponId): EnemyArchetypeId {
  if (weaponId === "smg" || weaponId === "shotgun") {
    return "rusher";
  }

  return "rifleman";
}

function formatEscortWeaponMixSummary(
  weaponIds: ReadonlyArray<WeaponId>,
  fallback: string,
  limit = 3
): string {
  if (weaponIds.length === 0) {
    return fallback;
  }

  const counts = new Map<WeaponId, number>();
  weaponIds.forEach((weaponId) => {
    counts.set(weaponId, (counts.get(weaponId) ?? 0) + 1);
  });

  return [...counts.entries()]
    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
    .slice(0, limit)
    .map(([weaponId, count]) => `${count}x ${WEAPONS[weaponId].name}`)
    .join(" | ");
}

function buildSquadEscortCombatProfile(
  squadMates: ReadonlyArray<SquadMateState>
): {
  dominantWeaponId: WeaponId;
  dominantCombatProfileId: EnemyArchetypeId;
  weaponMixSummary: string;
  fireRange: number;
  fireDamage: number;
  firePressureType: EnemyPressureType;
  firePressureDuration: number;
  fireIntervalMin: number;
  fireIntervalMax: number;
  ammoInMag: number;
  reserveAmmo: number;
  speed: number;
  grenadeStock: number;
} {
  const armedMates = squadMates.filter((mate) => mate.weaponId !== "none");

  if (armedMates.length === 0) {
    const fallbackWeaponId: WeaponId = "rifle";
    const fallbackCombatProfileId: EnemyArchetypeId = "rifleman";
    const fallbackCombatProfile = getSharedWeaponCombatProfile(fallbackWeaponId, fallbackCombatProfileId);
    return {
      dominantWeaponId: fallbackWeaponId,
      dominantCombatProfileId: fallbackCombatProfileId,
      weaponMixSummary: "No staged squad guns",
      fireRange: Math.max(140, Math.round(fallbackCombatProfile.engageRange)),
      fireDamage: Math.max(4, Math.round(WEAPONS[fallbackWeaponId].damage * fallbackCombatProfile.frontlineDamageMultiplier)),
      firePressureType: fallbackCombatProfile.pressureType,
      firePressureDuration: fallbackCombatProfile.pressureDuration,
      fireIntervalMin: fallbackCombatProfile.fireIntervalMin * 1.06,
      fireIntervalMax: fallbackCombatProfile.fireIntervalMax * 1.12,
      ammoInMag: WEAPONS[fallbackWeaponId].magazineSize,
      reserveAmmo: Math.max(WEAPONS[fallbackWeaponId].magazineSize, Math.round(WEAPONS[fallbackWeaponId].magazineSize * 2.2)),
      speed: 168,
      grenadeStock: 1
    };
  }

  const weaponCounts = new Map<WeaponId, number>();
  let dominantWeaponId = armedMates[0]?.weaponId ?? "rifle";
  let dominantWeaponCount = 0;

  armedMates.forEach((mate) => {
    const nextCount = (weaponCounts.get(mate.weaponId) ?? 0) + 1;
    weaponCounts.set(mate.weaponId, nextCount);
    if (nextCount > dominantWeaponCount) {
      dominantWeaponId = mate.weaponId;
      dominantWeaponCount = nextCount;
    }
  });

  const dominantCombatProfileId = getCombatProfileIdForWeapon(dominantWeaponId);
  let totalWeight = 0;
  let weightedFireRange = 0;
  let weightedFireDamage = 0;
  let weightedPressureDuration = 0;
  let weightedFireIntervalMin = 0;
  let weightedFireIntervalMax = 0;
  let weightedSpeed = 0;
  let totalAmmoInMag = 0;
  let totalReserveAmmo = 0;
  let grenadeStock = 0;
  const pressureWeights: Record<EnemyPressureType, number> = { pinned: 0, suppressed: 0, staggered: 0 };

  armedMates.forEach((mate) => {
    const readinessWeight = clamp(mate.readiness, 0.55, 1);
    const weapon = WEAPONS[mate.weaponId];
    const combatProfile = getSharedWeaponCombatProfile(mate.weaponId, mate.combatProfileId);
    totalWeight += readinessWeight;
    weightedFireRange += combatProfile.engageRange * readinessWeight;
    weightedFireDamage += weapon.damage * combatProfile.frontlineDamageMultiplier * readinessWeight;
    weightedPressureDuration += combatProfile.pressureDuration * readinessWeight;
    weightedFireIntervalMin += combatProfile.fireIntervalMin * readinessWeight;
    weightedFireIntervalMax += combatProfile.fireIntervalMax * readinessWeight;
    weightedSpeed += weapon.moveSpeed * readinessWeight;
    totalAmmoInMag += weapon.magazineSize;
    totalReserveAmmo += Math.max(weapon.magazineSize, Math.round(weapon.magazineSize * 2.2));
    pressureWeights[combatProfile.pressureType] += readinessWeight;
    if (mate.weaponId === "smg" || mate.weaponId === "shotgun") {
      grenadeStock += 1;
    }
  });

  const firePressureType =
    pressureWeights.staggered >= pressureWeights.suppressed && pressureWeights.staggered >= pressureWeights.pinned
      ? "staggered"
      : pressureWeights.suppressed >= pressureWeights.pinned
        ? "suppressed"
        : "pinned";
  const weightDivisor = Math.max(1, totalWeight);
  return {
    dominantWeaponId,
    dominantCombatProfileId,
    weaponMixSummary: formatEscortWeaponMixSummary(
      armedMates.map((mate) => mate.weaponId),
      "No staged squad guns"
    ),
    fireRange: Math.max(140, Math.round(weightedFireRange / weightDivisor)),
    fireDamage: Math.max(4, Math.round(weightedFireDamage / weightDivisor)),
    firePressureType,
    firePressureDuration: Number((weightedPressureDuration / weightDivisor).toFixed(2)),
    fireIntervalMin: Number(((weightedFireIntervalMin / weightDivisor) * 1.06).toFixed(3)),
    fireIntervalMax: Number(((weightedFireIntervalMax / weightDivisor) * 1.12).toFixed(3)),
    ammoInMag: Math.max(8, totalAmmoInMag),
    reserveAmmo: Math.max(totalAmmoInMag, totalReserveAmmo),
    speed: clamp(Math.round((weightedSpeed / weightDivisor) * 0.72), 160, 184),
    grenadeStock: clamp(Math.max(1, grenadeStock), 1, 4)
  };
}

function getFrontlineBurstAmmoCost(weaponId: WeaponId, pushTimer: number): number {
  if (weaponId === "amr") {
    return 1;
  }

  if (weaponId === "pkm") {
    return pushTimer > 0 ? 10 : 7;
  }

  if (weaponId === "smg") {
    return pushTimer > 0 ? 7 : 5;
  }

  if (weaponId === "shotgun") {
    return 1;
  }

  return pushTimer > 0 ? 3 : 2;
}

function getFrontlineCarrierAmmoStock(kind: FrontlineSupportKind | FrontlineIncidentKind): number {
  if (kind === "convoy") {
    return 96;
  }

  if (kind === "recovery" || kind === "casualty") {
    return 40;
  }

  if (kind === "civilian") {
    return 0;
  }

  if (kind === "bunker") {
    return 0;
  }

  return 0;
}

function getEnemyGrenadeStock(archetypeId: EnemyArchetypeId, tapeId: EnemyTapeId): number {
  if (archetypeId === "rusher") {
    return tapeId === "yellow" ? 2 : 1;
  }

  if (archetypeId === "rifleman") {
    return tapeId === "green" ? 1 : 0;
  }

  return 0;
}

function getFrontlineGrenadeStock(kind: FrontlineSupportKind | FrontlineIncidentKind, combatProfileId: EnemyArchetypeId): number {
  if (kind === "fireteam" || kind === "firefight") {
    return combatProfileId === "rusher" ? 2 : 1;
  }

  return 0;
}

function getFrontlineResupplyNeed(
  unit: { weaponId: WeaponId; ammoInMag: number; reserveAmmo: number; reloadTimer: number; dryFireTimer: number }
): number {
  const weapon = WEAPONS[unit.weaponId];
  const lowReserveFloor = Math.max(weapon.magazineSize, Math.round(weapon.magazineSize * 1.25));

  if (unit.ammoInMag <= 0 && unit.reserveAmmo <= 0) {
    return Math.max(weapon.magazineSize * 2, 14);
  }

  if (unit.reloadTimer <= 0 && unit.reserveAmmo <= lowReserveFloor) {
    return Math.max(weapon.magazineSize, 10);
  }

  if (unit.dryFireTimer > 0) {
    return Math.max(weapon.magazineSize, 12);
  }

  return 0;
}

function getFrontlineResupplyTransferAmount(
  carrierStock: number,
  unit: { weaponId: WeaponId; reserveAmmo: number; dryFireTimer: number }
): number {
  const weapon = WEAPONS[unit.weaponId];
  const desiredReserve =
    unit.dryFireTimer > 0 ? Math.max(weapon.magazineSize * 2, 16) : Math.max(weapon.magazineSize, 12);
  const neededReserve = Math.max(0, desiredReserve - unit.reserveAmmo);
  return Math.min(carrierStock, Math.max(Math.round(weapon.magazineSize * 0.75), neededReserve));
}

function createFrontlineSupportState(
  routeId: RaidRouteId,
  id: number,
  kind: FrontlineSupportKind,
  combatProfileId: EnemyArchetypeId,
  label: string,
  note: string,
  strength: number,
  anchor: Vec2,
  target: Vec2,
  color: number
): FrontlineSupportState {
  const combatProfile = createFrontlineCombatProfile(kind, combatProfileId);
  const holdRadius = kind === "fireteam" ? 86 : kind === "recovery" ? 80 : 78;
  const coverBonus = kind === "fireteam" ? 0.18 : kind === "recovery" ? 0.12 : 0.08;
  const footholdProfile =
    routeId === "crosswind-docks"
      ? kind === "fireteam"
        ? {
            footholdLabel: "Container berm",
            footholdSummary: "Stacked containers and bollards catch long dock angles while the picket keeps the lane stitched together.",
            coverMitigation: 0.18
          }
        : kind === "recovery"
          ? {
              footholdLabel: "Pier casualty pocket",
              footholdSummary: "Recovery drags, tarp cover, and hard pier clutter soften the lane while med hands stay close.",
              coverMitigation: 0.14
            }
          : {
              footholdLabel: "Relief crate stack",
              footholdSummary: "Buried haul crates and van bulk give brief hard cover while the convoy keeps sustain moving.",
              coverMitigation: 0.12
            }
      : routeId === "broken-signal"
        ? kind === "fireteam"
          ? {
              footholdLabel: "Relay berm",
              footholdSummary: "Dish berms and cable trenches mask the long relay sightlines so this hold can actually absorb contact.",
              coverMitigation: 0.2
            }
          : kind === "recovery"
            ? {
                footholdLabel: "Ladder shadow",
                footholdSummary: "Chemlights, tape, and cut-down service cover make the ladder lane easier to reset under pressure.",
                coverMitigation: 0.15
              }
            : {
                footholdLabel: "Signal shadow",
                footholdSummary: "The van hull and relay clutter break the north kill box just enough to regroup before the next peek.",
                coverMitigation: 0.13
              }
        : kind === "fireteam"
          ? {
              footholdLabel: "Freight trench lip",
              footholdSummary: "A trench lip with scraped berm cover turns the freight lane into a real fighting position instead of open ground.",
              coverMitigation: 0.2
            }
          : kind === "recovery"
            ? {
                footholdLabel: "Gate triage cut",
                footholdSummary: "A med pocket tucked behind freight clutter keeps the south gate lane alive for casualty pulls and reset fights.",
                coverMitigation: 0.15
              }
            : {
                footholdLabel: "Haul wreck pocket",
                footholdSummary: "A battered convoy wreck and stacked freight give just enough steel to regroup and reload under fire.",
                coverMitigation: 0.13
              };
  const sustainStock =
    kind === "fireteam"
      ? { medkits: 0, ammoPacks: 1 }
      : kind === "recovery"
        ? { medkits: 1, ammoPacks: 0 }
        : { medkits: 1, ammoPacks: 1 };
  return {
    id,
    kind,
    momentumFlavor: "standard",
    combatProfileId,
    weaponId: combatProfile.weaponId,
    playerEscort: false,
    label,
    note,
    zoneLabel: `${label} hold`,
    footholdLabel: footholdProfile.footholdLabel,
    footholdSummary: footholdProfile.footholdSummary,
    strength,
    position: { ...anchor },
    anchor: { ...anchor },
    target: { ...target },
    facing: normalize(subtract(target, anchor)),
    speed: combatProfile.speed,
    radius: combatProfile.radius,
    holdRadius,
    coverBonus,
    coverMitigation: footholdProfile.coverMitigation,
    sustainDuration: kind === "convoy" ? 1.5 : 1.2,
    sustainStock,
    sustainUsed: false,
    color,
    status: "moving",
    fireRange: combatProfile.fireRange,
    fireDamage: combatProfile.fireDamage,
    firePressureType: combatProfile.firePressureType,
    firePressureDuration: combatProfile.firePressureDuration,
    fireIntervalMin: combatProfile.fireIntervalMin,
    fireIntervalMax: combatProfile.fireIntervalMax,
    fireCooldown: 0,
    grenadeStock: getFrontlineGrenadeStock(kind, combatProfileId),
    grenadeCooldown: 0,
    blindFireTimer: 0,
    ammoInMag: combatProfile.magazineSize,
    reserveAmmo: combatProfile.reserveAmmo,
    ammoCarrierStock: getFrontlineCarrierAmmoStock(kind),
    reloadTimer: 0,
    resupplyTimer: 0,
    dryFireTimer: 0,
    resupplyTargetId: null,
    navigationStallTime: 0,
    navigationRecoveryIndex: 0,
    lastNavigationSample: { ...anchor },
    navigationCommittedTarget: null,
    casualtyPressure: 0,
    retreatTimer: 0,
    contactTimer: 0,
    pushTimer: 0,
    breachFootholdTimer: 0,
    breachFootholdObstacleId: null
  };
}

function formatSquadEscortLabel(squadMates: ReadonlyArray<SquadMateState>): string {
  if (squadMates.length === 0) {
    return "Boys escort";
  }

  if (squadMates.length === 1) {
    return `${squadMates[0].name} escort`;
  }

  if (squadMates.length === 2) {
    return `${squadMates[0].name} + ${squadMates[1].name}`;
  }

  return `${squadMates[0].name}, ${squadMates[1].name} + ${squadMates.length - 2}`;
}

function createPlayerEscortSupport(
  routeId: RaidRouteId,
  squadMates: ReadonlyArray<SquadMateState>,
  player: PlayerState
): FrontlineSupportState | null {
  if (!ENABLE_LEGACY_PLAYER_SIDE_SUPPORTS) {
    return null;
  }

  if (squadMates.length === 0 || player.weaponId === "none") {
    return null;
  }

  const escortFacing = length(player.facing) > 0.001 ? normalize(player.facing) : { x: 1, y: 0 };
  const escortLateral = { x: -escortFacing.y, y: escortFacing.x };
  const escortAnchor = {
    x: clamp(player.position.x - escortFacing.x * 42 + escortLateral.x * 24, 48, WORLD_WIDTH - 48),
    y: clamp(player.position.y - escortFacing.y * 42 + escortLateral.y * 24, 48, WORLD_HEIGHT - 48)
  };
  const escortTarget = {
    x: clamp(player.position.x + escortFacing.x * 30 + escortLateral.x * 24, 48, WORLD_WIDTH - 48),
    y: clamp(player.position.y + escortFacing.y * 30 + escortLateral.y * 24, 48, WORLD_HEIGHT - 48)
  };
  const escortCombatProfile = buildSquadEscortCombatProfile(squadMates);
  const escort = createFrontlineSupportState(
    routeId,
    901,
    "fireteam",
    escortCombatProfile.dominantCombatProfileId,
    formatSquadEscortLabel(squadMates),
    `The boys are stacked on your shoulder with ${escortCombatProfile.weaponMixSummary.toLowerCase()} and ready to cross the first live lane with you.`,
    squadMates.length,
    escortAnchor,
    escortTarget,
    0xfda4af
  );
  escort.playerEscort = true;
  escort.zoneLabel = "Boys wedge";
  escort.footholdLabel = "Player wedge";
  escort.footholdSummary = `The squad is close enough to steady your push, share angles, and turn the raid into a live team move instead of a solo sprint. Current mix: ${escortCombatProfile.weaponMixSummary}.`;
  escort.coverBonus = Math.max(escort.coverBonus, 0.24);
  escort.coverMitigation = Math.max(escort.coverMitigation, 0.22);
  escort.holdRadius = Math.max(escort.holdRadius, 92);
  escort.speed = Math.max(escort.speed, player.mobilityMultiplier > 0.95 ? escortCombatProfile.speed : escortCombatProfile.speed - 6);
  escort.weaponId = escortCombatProfile.dominantWeaponId;
  escort.fireRange = escortCombatProfile.fireRange;
  escort.fireDamage = escortCombatProfile.fireDamage;
  escort.firePressureType = escortCombatProfile.firePressureType;
  escort.firePressureDuration = escortCombatProfile.firePressureDuration;
  escort.fireIntervalMin = escortCombatProfile.fireIntervalMin;
  escort.fireIntervalMax = escortCombatProfile.fireIntervalMax;
  escort.ammoInMag = escortCombatProfile.ammoInMag;
  escort.reserveAmmo = escortCombatProfile.reserveAmmo;
  escort.grenadeStock = escortCombatProfile.grenadeStock;
  return escort;
}

function createFrontlineIncidentState(
  id: number,
  kind: FrontlineIncidentKind,
  combatProfileId: EnemyArchetypeId,
  label: string,
  note: string,
  strength: number,
  anchor: Vec2,
  target: Vec2,
  color: number
): FrontlineIncidentState {
  const combatProfile = createFrontlineCombatProfile(kind, combatProfileId);
  const opportunityLabel =
    kind === "convoy"
      ? "Strip the relief haul before it slips."
      : kind === "casualty"
        ? "Pull the wounded clear and steady the route."
        : kind === "civilian"
          ? "Escort the family clear before Blue seals the block."
          : kind === "bunker"
            ? "Settle the basement hold and let the boys reset before the lane reheats."
          : null;
  const resolvedNote =
    kind === "convoy"
      ? "Relief crates are stripped and the lane just got richer."
      : kind === "casualty"
        ? "The casualty pull made it out and your exfil net will set faster."
        : kind === "civilian"
          ? "The family is clear, the basement route note is bagged, and the block finally reads quieter."
          : kind === "bunker"
            ? "The boys settle into the basement hold, steady the net, and bag one route note before the lane wakes back up."
          : null;
  const interactDuration = kind === "convoy" ? 1.8 : kind === "casualty" ? 1.6 : kind === "civilian" ? 1.9 : kind === "bunker" ? 2.1 : 0;
  return {
    id,
    kind,
    presentationVariant: "default",
    combatProfileId,
    weaponId: combatProfile.weaponId,
    label,
    note,
    strength,
    opportunityLabel,
    resolvedNote,
    interactDuration,
    resolved: false,
    position: { ...anchor },
    anchor: { ...anchor },
    target: { ...target },
    facing: normalize(subtract(target, anchor)),
    speed: combatProfile.speed,
    radius: combatProfile.radius,
    color,
    status: "sweeping",
    fireRange: combatProfile.fireRange,
    fireDamage: combatProfile.fireDamage,
    firePressureType: combatProfile.firePressureType,
    firePressureDuration: combatProfile.firePressureDuration,
    fireIntervalMin: combatProfile.fireIntervalMin,
    fireIntervalMax: combatProfile.fireIntervalMax,
    fireCooldown: 0,
    grenadeStock: getFrontlineGrenadeStock(kind, combatProfileId),
    grenadeCooldown: 0,
    blindFireTimer: 0,
    ammoInMag: combatProfile.magazineSize,
    reserveAmmo: combatProfile.reserveAmmo,
    ammoCarrierStock: getFrontlineCarrierAmmoStock(kind),
    reloadTimer: 0,
    resupplyTimer: 0,
    dryFireTimer: 0,
    resupplyTargetId: null,
    navigationStallTime: 0,
    navigationRecoveryIndex: 0,
    lastNavigationSample: { ...anchor },
    navigationCommittedTarget: null,
    resolveProgress: 0,
    casualtyPressure: 0,
    collapseTimer: 0,
    contactTimer: 0,
    pushTimer: 0,
    territoryState: "none",
    territoryRadius: kind === "firefight" ? 82 : 0,
    territoryNote: kind === "firefight" ? "Ground is still contested and nobody has locked the lane yet." : "",
    actionVerb:
      kind === "firefight" ? "plant" : kind === "casualty" ? "recover" : kind === "civilian" ? "evacuate" : kind === "bunker" ? "settle" : "strip",
    markerState: "none",
    markerNote: ""
  };
}

function getFrontlineIncidentActionLabel(incident: FrontlineIncidentState): string | null {
  if (incident.kind === "convoy") {
    return "Strip the relief haul before it slips.";
  }

  if (incident.kind === "casualty") {
    return "Pull the wounded clear and steady the route.";
  }

  if (incident.kind === "civilian") {
    return "Escort the family clear before Blue seals the block.";
  }

  if (incident.kind === "bunker") {
    if (incident.presentationVariant === "cellar-counterhold") {
      return "Hold the cellar mouth until the reserve shove dies.";
    }
    if (incident.presentationVariant === "shed-hide") {
      return "Stay dark in the shed until the sweep passes the village lip.";
    }
    return "Settle the basement hold and let the boys reset before the lane reheats.";
  }

  if (incident.kind !== "firefight") {
    return null;
  }

  if (incident.presentationVariant === "amr-counter-lane") {
    return "Break the plated anchor before the repeek hardens.";
  }

  if (incident.presentationVariant === "dish-house-breach") {
    return "Flood the dish houses before the reserve shove reseats the block.";
  }

  if (incident.status === "routed" && incident.territoryState === "reclaimed") {
    return "Force the surrender, bag route intel, and lock the pocket.";
  }

  if (incident.territoryState === "reclaimed" || incident.territoryState === "breaking") {
    return "Plant the route flag and lock the pocket.";
  }

  if (incident.territoryState === "lost") {
    return "Recover the bodies from the wiped lane.";
  }

  return null;
}

function getFrontlineIncidentInteractDuration(incident: FrontlineIncidentState): number {
  if (incident.kind === "convoy") {
    return 1.8;
  }

  if (incident.kind === "casualty") {
    return 1.6;
  }

  if (incident.kind === "civilian") {
    return 1.9;
  }

  if (incident.kind === "bunker") {
    return 2.1;
  }

  if (incident.kind === "firefight") {
    if (incident.status === "routed" && incident.territoryState === "reclaimed") {
      return 1.95;
    }
    return incident.territoryState === "lost" ? 2.1 : 1.7;
  }

  return 0;
}

function getFrontlineIncidentActionVerbId(incident: FrontlineIncidentState): FrontlineIncidentActionVerb {
  if (incident.kind === "convoy") {
    return "strip";
  }

  if (incident.kind === "casualty") {
    return "recover";
  }

  if (incident.kind === "civilian") {
    return "evacuate";
  }

  if (incident.kind === "bunker") {
    return "settle";
  }

  if (incident.status === "routed" && incident.territoryState === "reclaimed") {
    return "secure";
  }

  return incident.territoryState === "lost" ? "recover" : "plant";
}

function getFrontlineIncidentActionVerb(
  incident: FrontlineIncidentState,
  activeVerb?: FrontlineIncidentActionVerb | null
): string {
  const verb = activeVerb ?? incident.actionVerb ?? getFrontlineIncidentActionVerbId(incident);

  if (verb === "strip") {
    return "Stripping";
  }

  if (verb === "recover") {
    return "Recovering";
  }

  if (verb === "secure") {
    return "Securing";
  }

  if (verb === "evacuate") {
    return "Evacuating";
  }

  if (verb === "settle") {
    return "Settling";
  }

  return "Planting";
}

export function getFrontlineIncidentActionRead(state: RaidState): FrontlineIncidentActionRead | null {
  const activeAction = state.activeFrontlineIncidentAction;
  if (!activeAction) {
    return null;
  }

  const incident = state.frontlineIncidents.find(
    (entry) => entry.id === activeAction.incidentId && !entry.resolved && Boolean(entry.opportunityLabel)
  );
  if (!incident) {
    return null;
  }

  const seconds = activeAction.timer.toFixed(1);
  const verb = activeAction.verb ?? incident.actionVerb ?? getFrontlineIncidentActionVerbId(incident);

  if (incident.kind === "convoy" || verb === "strip") {
    return {
      incidentId: incident.id,
      title: `Strip ${incident.label}`,
      status: `${seconds}s left | stay on the truck lane`,
      detail: "Hold the convoy pocket until the relief haul is yours and the route pays out in ammo instead of panic.",
      compact: `STRIP ${seconds}s`,
      tone: "support"
    };
  }

  if (incident.kind === "casualty") {
    return {
      incidentId: incident.id,
      title: `Drag ${incident.label} clear`,
      status: `${seconds}s left | keep the casualty lane open`,
      detail: "Stay in the pocket long enough for the boys to pull the wounded out and bank the calmer extract read.",
      compact: `DRAG ${seconds}s`,
      tone: "loss"
    };
  }

  if (incident.kind === "civilian" || verb === "evacuate") {
    if (incident.presentationVariant === "hunter-search") {
      return {
        incidentId: incident.id,
        title: `Guide ${incident.label}`,
        status: `${seconds}s left | quiet voices and covered angles`,
        detail:
          "Stay with the old hunter long enough to pull him off the search lane, bag his son's last route note, and keep the zone from swallowing the story whole.",
        compact: `GUIDE ${seconds}s`,
        tone: "support"
      };
    }

    return {
      incidentId: incident.id,
      title: `Walk out ${incident.label}`,
      status: `${seconds}s left | disciplined guns only`,
      detail: "Keep the shelter pocket steady so the family clears the block and the cellar route note turns into real intel.",
      compact: `EVAC ${seconds}s`,
      tone: "support"
    };
  }

  if (incident.kind === "bunker" || verb === "settle") {
    if (incident.presentationVariant === "cellar-counterhold") {
      return {
        incidentId: incident.id,
        title: `Lock ${incident.label}`,
        status: `${seconds}s left | keep the cellar mouth screened`,
        detail:
          "Stay in the relay cellar long enough to bank the route note, pass the battery bricks, and stop the reserve shove from reopening the whole foothold.",
        compact: `LOCK ${seconds}s`,
        tone: "support"
      };
    }
    if (incident.presentationVariant === "shed-hide") {
      return {
        incidentId: incident.id,
        title: `Hide inside ${incident.label}`,
        status: `${seconds}s left | stay dark and let the sweep pass`,
        detail:
          "Stay tucked in long enough for Blue to sweep past the shed mouth, keep the boys quiet, and steal one cleaner move back into the village once the lane loosens.",
        compact: `HIDE ${seconds}s`,
        tone: "support"
      };
    }
    return {
      incidentId: incident.id,
      title: `Hold ${incident.label}`,
      status: `${seconds}s left | keep the bunker quiet`,
      detail:
        "Stay in the basement long enough for the boys to catch breath, pass one taped mag, throw a movie on the laptop, and bag the route note before the lane turns loud again.",
      compact: `HOLD ${seconds}s`,
      tone: "support"
    };
  }

  if (verb === "secure") {
    if (incident.presentationVariant === "dish-house-breach") {
      return {
        incidentId: incident.id,
        title: `Flood ${incident.label}`,
        status: `${seconds}s left | first door still half-owned`,
        detail:
          "Stay on the block long enough to clear the first room, let the shotgun win the hard corner, and stop the reserve shove from turning the relay houses back into a long-angle fight.",
        compact: `FLOOD ${seconds}s`,
        tone: "pressure"
      };
    }
    return {
      incidentId: incident.id,
      title: `Lock ${incident.label}`,
      status: `${seconds}s left | own the surrender scar`,
      detail: "Hold the broken pocket until the surrender sticks, the route notes are bagged, and Blue cannot reheat the lane.",
      compact: `LOCK ${seconds}s`,
      tone: "pressure"
    };
  }

  if (verb === "recover" || incident.territoryState === "lost") {
    return {
      incidentId: incident.id,
      title: `Recover ${incident.label}`,
      status: `${seconds}s left | keep the dead strip covered`,
      detail: "Stay on the scar long enough to drag the bodies clear before the lane seals and the squad loses the chance.",
      compact: `RECOVER ${seconds}s`,
      tone: "loss"
    };
  }

  return {
    incidentId: incident.id,
    title: `Flag ${incident.label}`,
    status: `${seconds}s left | pin the reclaimed lane`,
    detail: "Hold the pocket until the route flag sticks and the squad turns a hot break into a bankable claim.",
    compact: `FLAG ${seconds}s`,
    tone: "pressure"
  };
}

function getFrontlineTerritoryMarkerState(incident: FrontlineIncidentState): FrontlineTerritoryMarkerState {
  if (incident.kind === "convoy") {
    return "none";
  }

  if (incident.kind === "casualty") {
    return incident.resolved ? "bagged" : "none";
  }

  if (incident.kind === "civilian") {
    return "none";
  }

  if (incident.kind === "bunker") {
    return "none";
  }

  if (incident.resolved) {
    return incident.territoryState === "lost" ? "bagged" : "planted";
  }

  if (incident.territoryState === "reclaimed" || incident.territoryState === "breaking") {
    return "raising";
  }

  return incident.territoryState === "lost" ? "bagged" : "none";
}

function getPocketLaneFrame(
  route: RaidRouteDefinition,
  pocketIndex: number
): { previous: Vec2; next: Vec2; forward: Vec2; side: Vec2 } {
  const pocket = route.combatPockets[pocketIndex];
  const previous = route.combatPockets[pocketIndex - 1]?.position ?? route.insertionPoints[0]?.position ?? pocket.position;
  const next = route.combatPockets[pocketIndex + 1]?.position ?? route.extractZone.position;
  const forward = normalize(subtract(next, previous));
  const safeForward = length(forward) > 0.01 ? forward : { x: 1, y: 0 };
  return {
    previous,
    next,
    forward: safeForward,
    side: perpendicular(safeForward)
  };
}

function createSupplementalFrontlineSupports(route: RaidRouteDefinition): FrontlineSupportState[] {
  return route.combatPockets.slice(2).map((pocket, index) => {
    const pocketIndex = route.combatPockets.findIndex((entry) => entry.label === pocket.label);
    const { next, forward, side } = getPocketLaneFrame(route, pocketIndex);
    const sideBias = index % 2 === 0 ? 1 : -1;
    const laneSpread = Math.min(208, 58 + index * 22);
    const lanePull = Math.min(128, 34 + index * 12);
    const anchor = add(
      add(pocket.position, multiply(forward, -pocket.radius * 0.52)),
      multiply(side, sideBias * laneSpread)
    );
    const target = add(next, multiply(side, sideBias * lanePull));
    const kind: FrontlineSupportKind = index % 3 === 1 ? "recovery" : "fireteam";
    const combatProfileId: EnemyArchetypeId =
      kind === "fireteam" ? (index % 2 === 0 ? "rifleman" : "rusher") : "skirmisher";
    const color =
      route.id === "crosswind-docks"
        ? index % 2 === 0
          ? 0x67e8f9
          : 0xc4b5fd
        : route.id === "broken-signal"
          ? index % 2 === 0
            ? 0x93c5fd
            : 0xfacc15
          : index % 2 === 0
            ? 0x4ade80
            : 0xf59e0b;

    return createFrontlineSupportState(
      route.id,
      10 + index,
      kind,
      combatProfileId,
      `${pocket.label} ${kind === "fireteam" ? "screen" : "reset team"}`,
      `${pocket.label} is already occupied, which stretches the route into a wider multi-pocket fight instead of one tight box.`,
      kind === "fireteam" ? 5 : 4,
      anchor,
      target,
      color
    );
  });
}

function createSupplementalFrontlineIncidents(route: RaidRouteDefinition): FrontlineIncidentState[] {
  return route.combatPockets.slice(2).map((pocket, index) => {
    const pocketIndex = route.combatPockets.findIndex((entry) => entry.label === pocket.label);
    const { next, forward, side } = getPocketLaneFrame(route, pocketIndex);
    const sideBias = index % 2 === 0 ? -1 : 1;
    const laneSpread = Math.min(176, 48 + index * 18);
    const lanePull = Math.min(106, 24 + index * 10);
    const anchor = add(
      add(pocket.position, multiply(forward, -pocket.radius * 0.24)),
      multiply(side, sideBias * laneSpread)
    );
    const target = add(next, multiply(side, sideBias * lanePull));
    const combatProfileId: EnemyArchetypeId = index % 2 === 0 ? "rifleman" : "rusher";
    const color = route.id === "sundered-run" ? 0xfb7185 : route.id === "broken-signal" ? 0x7dd3fc : 0xfda4af;

    return createFrontlineIncidentState(
      20 + index,
      "firefight",
      combatProfileId,
      `${pocket.label} crossfire`,
      `${pocket.label} is trading hard and keeps the route reading like a longer frontline with real depth behind the player.`,
      combatProfileId === "rusher" ? 5 : 6,
      anchor,
      target,
      color
    );
  });
}

function createFrontlineSupports(
  route: RaidRouteDefinition,
  sector: FrontlineSectorState | null,
  activeFrontlineDefinition: FrontlineOperationDefinition | null
): FrontlineSupportState[] {
  if (!ENABLE_LEGACY_PLAYER_SIDE_SUPPORTS) {
    return [];
  }

  const supports: FrontlineSupportState[] = [];
  const ambientCoffeePocket = shouldSpawnAmbientCoffeePocket(route, sector, activeFrontlineDefinition);

  if (route.id === "crosswind-docks") {
    supports.push(
      createFrontlineSupportState(
        route.id,
        1,
        "fireteam",
        "rifleman",
        "Dock picket",
        activeFrontlineDefinition?.id === "reinforce-pickets"
          ? "Fresh pickets are tying up the first dock angle so the raid opens under thinner fire."
          : "A dockside fireteam is already trading shots across the first cargo lane.",
        5,
        { x: 520, y: 470 },
        { x: 1010, y: 690 },
        0x86efac
      )
    );
    const supportTwo = createFrontlineSupportState(
      route.id,
      2,
      activeFrontlineDefinition?.id === "smuggle-cache" ? "convoy" : "recovery",
      "skirmisher",
      activeFrontlineDefinition?.id === "smuggle-cache"
        ? "Relief haul"
        : activeFrontlineDefinition?.id === "burner-coffee"
          ? "Pier coffee fire"
          : "Pier recovery",
      activeFrontlineDefinition?.id === "smuggle-cache"
        ? "A relief haul is creeping up the lower pier with buried sustain for the next ugly pocket."
        : activeFrontlineDefinition?.id === "burner-coffee"
          ? "A burner crew has already tucked into the lower pier clutter with hot coffee and spare rounds for the first hard reset."
          : "Recovery bodies are already drifting around the pier lanes waiting for a live exfil call.",
      4,
      { x: 350, y: 1040 },
      { x: 1460, y: 980 },
      activeFrontlineDefinition?.id === "burner-coffee" ? 0xf59e0b : 0xfbbf24
    );
    supports.push(
      activeFrontlineDefinition?.id === "burner-coffee"
        ? configureBurnerCoffeeSupport(route.id, supportTwo)
        : ambientCoffeePocket
          ? configureAmbientCoffeeSupport(route.id, supportTwo)
        : supportTwo
    );
    supports.push(
      createFrontlineSupportState(
        route.id,
        4,
        "fireteam",
        "skirmisher",
        "Crane ladder rifles",
        "A second rifle pair keeps the mid dock ladders live, so the route feels like a staffed push instead of one isolated duel.",
        3,
        { x: 880, y: 760 },
        { x: 1550, y: 760 },
        0x5eead4
      )
    );
  } else if (route.id === "broken-signal") {
    supports.push(
      createFrontlineSupportState(
        route.id,
        1,
        "fireteam",
        "rifleman",
        "Relay cut team",
        activeFrontlineDefinition?.id === "reinforce-pickets"
          ? "A cut team is bracing the relay mouth so the north kill box is not fully yours to solve alone."
          : "Friendly rifles are already peeking the relay mouth and keeping Blue from owning every long angle.",
        5,
        { x: 760, y: 440 },
        { x: 1420, y: 560 },
        0x7dd3fc
      )
    );
    const supportTwo = createFrontlineSupportState(
      route.id,
      2,
      activeFrontlineDefinition?.id === "mark-exfil" || activeFrontlineDefinition?.id === "burner-coffee"
        ? "recovery"
        : "convoy",
      "skirmisher",
      activeFrontlineDefinition?.id === "mark-exfil"
        ? "Ladder markers"
        : activeFrontlineDefinition?.id === "burner-coffee"
          ? "Dish burner fire"
          : "Signal van",
      activeFrontlineDefinition?.id === "mark-exfil"
        ? "Recovery markers are already moving toward the cleaner ladder route before the north box fully hardens."
        : activeFrontlineDefinition?.id === "burner-coffee"
          ? "A burner team is already tucked under the upper dish berm with coffee and a taped mag stack for the first bad relay reset."
          : "A signal van is shuffling between relay pockets, making the line feel staffed instead of dead.",
      4,
      { x: 980, y: 250 },
      { x: 1680, y: 720 },
      activeFrontlineDefinition?.id === "burner-coffee" ? 0xf59e0b : 0xfacc15
    );
    supports.push(
      activeFrontlineDefinition?.id === "burner-coffee"
        ? configureBurnerCoffeeSupport(route.id, supportTwo)
        : ambientCoffeePocket
          ? configureAmbientCoffeeSupport(route.id, supportTwo)
        : supportTwo
    );
    supports.push(
      createFrontlineSupportState(
        route.id,
        4,
        "fireteam",
        "skirmisher",
        "Dish flank scouts",
        "A scout pair keeps cutting across the upper dish berm, which helps the relay route read like a longer coordinated line fight.",
        3,
        { x: 1180, y: 300 },
        { x: 1820, y: 520 },
        0x93c5fd
      )
    );
  } else {
    supports.push(
      createFrontlineSupportState(
        route.id,
        1,
        "fireteam",
        "rifleman",
        "Freight trench team",
        activeFrontlineDefinition?.id === "reinforce-pickets"
          ? "A trench team is already stacked in the first freight cut, stretching the fight before it reaches you."
          : "Freight trench fighters are visible in the lane, keeping the map from reading like an empty solo run.",
        5,
        { x: 760, y: 500 },
        { x: 1460, y: 930 },
        0x4ade80
      )
    );
    const supportTwo = createFrontlineSupportState(
      route.id,
      2,
      activeFrontlineDefinition?.id === "smuggle-cache" ? "convoy" : "recovery",
      "skirmisher",
      activeFrontlineDefinition?.id === "smuggle-cache"
        ? "Casualty haul"
        : activeFrontlineDefinition?.id === "burner-coffee"
          ? "Trench coffee fire"
          : "Gate med team",
      activeFrontlineDefinition?.id === "smuggle-cache"
        ? "A battered casualty haul is inching forward with extra sustain hidden in the convoy clutter."
        : activeFrontlineDefinition?.id === "burner-coffee"
          ? "A trench burner is already glowing behind the south gate clutter with hot coffee and one taped mag for the next shove."
          : "A med team is hugging the south gate lane so the exfil corridor feels manned and unstable.",
      4,
      { x: 420, y: 980 },
      { x: 1640, y: 1010 },
      0xf59e0b
    );
    supports.push(
      activeFrontlineDefinition?.id === "burner-coffee"
        ? configureBurnerCoffeeSupport(route.id, supportTwo)
        : ambientCoffeePocket
          ? configureAmbientCoffeeSupport(route.id, supportTwo)
        : supportTwo
    );
    supports.push(
      createFrontlineSupportState(
        route.id,
        4,
        "fireteam",
        "rusher",
        "Berm watch",
        "A berm watch pair is already trading short bursts over the south approach, stretching the freight fight across more than one trench mouth.",
        4,
        { x: 920, y: 860 },
        { x: 1810, y: 1180 },
        0x86efac
      )
    );
  }

  if (sector?.control === "held" || activeFrontlineDefinition?.id === "mark-exfil") {
    const primaryExtract = route.extractOptions[0] ?? {
      position: route.extractZone.position
    };
    supports.push(
      createFrontlineSupportState(
        route.id,
        4,
        "recovery",
        "skirmisher",
        activeFrontlineDefinition?.id === "mark-exfil" ? "Cold exfil tape" : "Fallback team",
        activeFrontlineDefinition?.id === "mark-exfil"
          ? "Cold chemlights and tape crews are already edging toward the extract before the beacon goes hot."
          : "A fallback team is lingering close enough to the extract lane to make the district feel occupied.",
        3,
        {
          x: primaryExtract.position.x - route.extractZone.radius * 0.9,
          y: primaryExtract.position.y + (route.id === "broken-signal" ? 120 : 40)
        },
        {
          x: primaryExtract.position.x + route.extractZone.radius * 0.15,
          y: primaryExtract.position.y - 10
        },
        0xc4b5fd
      )
    );
  }

  return [...supports, ...createSupplementalFrontlineSupports(route)];
}

