const SQUAD_SPEAKER_FLAVOR = {
  Rook: {
    default: [" Stay sharp.", " Keep shape.", " No lazy cross."],
    hot: [" Clean shove.", " No hero play.", " Win first."],
    humane: [" Easy muzzles.", " No panic.", " Gentle hands."]
  },
  Makar: {
    default: [" Let me bark.", " I have noise.", " Give me loud."],
    hot: [" I have the loud part.", " Let me scare them.", " I keep them down."],
    humane: [" I cover them.", " I bark, they move.", " Nobody touches them."]
  },
  Yara: {
    default: [" Save me a bag.", " Keep it patchable.", " I am not dragging fools."],
    hot: [" I need seconds.", " Keep somebody standing.", " Do not fold on me."],
    humane: [" Gentle route.", " We get them out whole.", " No open-air triage."]
  }
} as const;

function addSquadSpeakerFlavor(
  line: string,
  speaker: string,
  context:
    | "advance"
    | "contact"
    | "mate-down"
    | "body-sighted"
    | "coffee"
    | "civilian"
    | "haul"
    | "intel"
    | "surrender"
    | "claim-breaking"
    | "claim-held"
    | "claim-loss"
    | "extract-live"
    | "extract-hot"
    | `order-${FrontlineSupportOrderId}`
): string {
  const flavor = SQUAD_SPEAKER_FLAVOR[speaker as keyof typeof SQUAD_SPEAKER_FLAVOR];
  if (!flavor) {
    return line;
  }

  const pool =
    context === "civilian" || context === "coffee" || context === "haul"
      ? flavor.humane
      : context === "contact" ||
          context === "mate-down" ||
          context === "body-sighted" ||
          context === "surrender" ||
          context === "claim-breaking" ||
          context === "claim-held" ||
          context === "claim-loss" ||
          context === "extract-hot" ||
          context.startsWith("order-")
        ? flavor.hot
        : flavor.default;

  if (line.length >= 52) {
    return line;
  }

  return `${line}${randomItem([...pool])}`;
}

