function fillSquadCallTemplate(
  template: string,
  values: Record<
    | "focus"
    | "focusLower"
    | "extract"
    | "extractLower"
    | "breach"
    | "breachLower"
    | "enemyTape"
    | "memoryMate"
    | "addressee"
    | "addresseeLower",
    string
  >
): string {
  return template
    .split("{focus}")
    .join(values.focus)
    .split("{focusLower}")
    .join(values.focusLower)
    .split("{extract}")
    .join(values.extract)
    .split("{extractLower}")
    .join(values.extractLower)
    .split("{breach}")
    .join(values.breach)
    .split("{breachLower}")
    .join(values.breachLower)
    .split("{enemyTape}")
    .join(values.enemyTape)
    .split("{memoryMate}")
    .join(values.memoryMate)
    .split("{addressee}")
    .join(values.addressee)
    .split("{addresseeLower}")
    .join(values.addresseeLower);
}

function buildDialogueEventPacketFromContext(params: {
  context:
    | "advance"
    | "contact"
    | "mate-down"
    | "body-sighted"
    | "coffee"
    | "civilian"
    | "haul"
    | "intel"
    | "surrender"
    | "claim-breaking"
    | "claim-held"
    | "claim-loss"
    | "extract-live"
    | "extract-hot"
    | `order-${FrontlineSupportOrderId}`;
  focusedLabel: string;
  extractLabel: string;
  breachLabel: string;
  dominantTapeId: EnemyTapeId | null;
  playerCritical: boolean;
  squadMates: ReadonlyArray<SquadMateState>;
}): DialogueEventPacket | null {
  const kind =
    params.context === "haul"
      ? "loot"
      : params.context === "intel"
        ? "intel"
        : params.context === "civilian"
          ? "civilian"
          : params.context === "coffee"
            ? "coffee"
            : params.context === "claim-breaking"
              ? "claim-breaking"
              : params.context === "claim-held"
                ? "claim-held"
                : params.context === "claim-loss"
                  ? "claim-loss"
      : params.context === "extract-live"
        ? "extract-open"
        : params.context === "extract-hot"
          ? "extract-hot"
          : params.context === "surrender"
            ? "surrender"
            : params.context === "contact"
              ? "contact"
              : params.context === "advance"
                ? "advance"
                : null;

  if (!kind) {
    return null;
  }

  return {
    id: `${kind}:${params.focusedLabel}:${params.extractLabel}:${params.dominantTapeId ?? "none"}`,
    kind,
    locationLabel: params.focusedLabel,
    extractLabel: params.extractLabel,
    breachLabel: params.breachLabel,
    intensity:
      params.context === "extract-hot" || params.playerCritical
        ? "critical"
        : params.context === "contact" ||
            params.context === "surrender" ||
            params.context === "haul" ||
            params.context === "claim-breaking" ||
            params.context === "claim-loss"
          ? "high"
        : params.context === "extract-live"
            ? "medium"
            : "low",
    dominantTapeId: params.dominantTapeId,
    playerCritical: params.playerCritical,
    greedPressure: params.context === "haul" ? 0.82 : params.context === "extract-hot" ? 0.6 : 0.28,
    memoryTags: getDialogueMemoryTags(params.squadMates.flatMap((mate) => mate.recentDialogueMemories))
  };
}

function buildHostileDialogueEventPacket(params: {
  context: "advance" | "contact" | "surrender" | "civilian" | "extract";
  focusedLabel: string;
  extractLabel: string;
  dominantTapeId: EnemyTapeId;
}): DialogueEventPacket {
  return {
    id: `hostile:${params.context}:${params.focusedLabel}:${params.dominantTapeId}`,
    kind:
      params.context === "extract"
        ? "extract-hot"
        : params.context === "civilian"
          ? "civilian"
          : params.context === "surrender"
            ? "surrender"
            : params.context === "contact"
              ? "contact"
              : "advance",
    locationLabel: params.focusedLabel,
    extractLabel: params.extractLabel,
    breachLabel: params.focusedLabel,
    intensity: params.context === "extract" || params.context === "surrender" ? "critical" : params.context === "contact" ? "high" : "medium",
    dominantTapeId: params.dominantTapeId,
    playerCritical: params.context === "extract",
    greedPressure: params.context === "extract" ? 0.6 : 0.2,
    memoryTags: []
  };
}

function getDialogueFocusOverlap(
  profile: DialogueVoiceProfile | undefined,
  focusTags: ReadonlyArray<DialogueFocusTag>
): number {
  if (!profile) {
    return 0;
  }

  return focusTags.filter((tag) => profile.focusBias.includes(tag)).length;
}

function getDialogueWordCount(line: string): number {
  return line
    .trim()
    .split(/\s+/)
    .filter(Boolean).length;
}

function getDialogueSignature(line: string): string {
  return line
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((word) => word.length >= 3)
    .slice(0, 5)
    .join(" ");
}

function pickDialogueAddressee(
  speaker: SquadMateState,
  squadMates: ReadonlyArray<SquadMateState>,
  packet: DialogueEventPacket
): SquadMateState | null {
  const others = squadMates.filter((mate) => mate.id !== speaker.id);
  if (others.length === 0) {
    return null;
  }

  const preferredName =
    packet.kind === "body-recovery" || packet.kind === "civilian" || packet.kind === "claim-loss"
      ? speaker.name === "Yara"
        ? "Rook"
        : "Yara"
      : packet.kind === "extract-hot" || packet.kind === "extract-open" || packet.kind === "contact"
        ? speaker.name === "Makar"
          ? "Rook"
          : "Makar"
        : speaker.name === "Rook"
          ? "Makar"
          : "Rook";

  return others.find((mate) => mate.name === preferredName) ?? others[0] ?? null;
}

function maybeAddressDialogueLine(
  line: string,
  addressee: SquadMateState | null
): string {
  const normalized = line.trim();
  if (!addressee) {
    return normalized;
  }

  const escapedName = addressee.name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const stripped = normalized.replace(new RegExp(`^${escapedName},\\s*`, "i"), "");
  return stripped.charAt(0).toUpperCase() + stripped.slice(1);
}

function getFallbackDialogueAddresseeName(
  speaker: string,
  context:
    | "advance"
    | "contact"
    | "mate-down"
    | "body-sighted"
    | "coffee"
    | "civilian"
    | "haul"
    | "intel"
    | "surrender"
    | "claim-breaking"
    | "claim-held"
    | "claim-loss"
    | "extract-live"
    | "extract-hot"
    | `order-${FrontlineSupportOrderId}`
): string | null {
  if (context === "advance" || context === "coffee") {
    return null;
  }

  if (speaker === "Yara") {
    return context === "civilian" || context === "claim-loss" ? "Rook" : "Makar";
  }

  if (speaker === "Makar") {
    return context === "extract-hot" || context === "contact" || context === "mate-down" ? "Rook" : "Yara";
  }

  return context === "claim-loss" || context === "body-sighted" ? "Yara" : "Makar";
}

function resolveSquadDialogueEvent(
  packet: DialogueEventPacket,
  squadMates: ReadonlyArray<SquadMateState>,
  previousSpeaker: string | null,
  recentTemplateIds: ReadonlyArray<string>,
  recentChannels: ReadonlyArray<string>,
  recentSignatures: ReadonlyArray<string>
): ResolvedSquadDialogue | null {
  let bestCandidate:
    | {
        score: number;
        speaker: SquadMateState;
        template: SquadDialogueTemplate;
        memory: DialogueMemory | null;
      }
    | null = null;

  for (const template of SQUAD_DIALOGUE_TEMPLATES) {
    if (template.kind !== packet.kind) {
      continue;
    }
    if (template.requiredSubjectName && template.requiredSubjectName !== packet.locationLabel) {
      continue;
    }
    if (template.enemyTapeId && packet.dominantTapeId !== template.enemyTapeId) {
      continue;
    }

    for (const speaker of squadMates) {
      if (template.allowedSpeakers && !template.allowedSpeakers.includes(speaker.name)) {
        continue;
      }

      const memory =
        template.requiredMemoryTag
          ? speaker.recentDialogueMemories.find((entry) => entry.tag === template.requiredMemoryTag) ?? null
          : null;
      if (template.requiredMemoryTag && !memory) {
        continue;
      }

      const profile = SQUAD_DIALOGUE_VOICE_PROFILES[speaker.name];
      let score = template.weight + getDialogueFocusOverlap(profile, template.focusTags) * 0.7 + Math.random() * 0.35;
      if (previousSpeaker === speaker.name) {
        score -= 0.9;
      }
      if (packet.playerCritical && profile?.stressStyle !== "quieter") {
        score += 0.45;
      }
      if (packet.kind === "loot" && profile?.focusBias.includes("greed")) {
        score += packet.greedPressure;
      }
      if (memory) {
        score += 1.65 + memory.emotionalWeight * 0.75;
      }
      if (packet.intensity === "critical") {
        score += template.focusTags.includes("body") ? 0.32 : template.focusTags.includes("noise") ? 0.18 : 0;
      }
      const recentIndex = recentTemplateIds.indexOf(template.id);
      if (recentIndex !== -1) {
        score -= 2.15 - recentIndex * 0.28;
      }
      const recentChannelIndex = recentChannels.indexOf(template.channel);
      if (recentChannelIndex !== -1) {
        score -= 1.3 - recentChannelIndex * 0.18;
      }

      const wordCount = getDialogueWordCount(template.text);
      if (wordCount > 12) {
        score -= (wordCount - 12) * 0.2;
      }
      if (wordCount <= 8) {
        score += 0.16;
      }
      if (recentSignatures.includes(getDialogueSignature(template.text))) {
        score -= 1.45;
      }

      if (!bestCandidate || score > bestCandidate.score) {
        bestCandidate = {
          score,
          speaker,
          template,
          memory
        };
      }
    }
  }

  if (!bestCandidate) {
    return null;
  }

  const enemyTapeLabel = packet.dominantTapeId ? getEnemyTapeDefinition(packet.dominantTapeId).label : "Blue";
  const addressee = pickDialogueAddressee(bestCandidate.speaker, squadMates, packet);
  return {
    templateId: bestCandidate.template.id,
    speaker: bestCandidate.speaker.name,
    tone: bestCandidate.template.tone,
    channel: bestCandidate.template.channel,
    line: maybeAddressDialogueLine(
      fillSquadCallTemplate(bestCandidate.template.text, {
        focus: packet.locationLabel,
        focusLower: packet.locationLabel.toLowerCase(),
        extract: packet.extractLabel,
        extractLower: packet.extractLabel.toLowerCase(),
        breach: packet.breachLabel,
        breachLower: packet.breachLabel.toLowerCase(),
        enemyTape: enemyTapeLabel,
        memoryMate: bestCandidate.memory?.subjectName ?? "the last one",
        addressee: addressee?.name ?? "brother",
        addresseeLower: addressee?.name.toLowerCase() ?? "brother"
      }),
      addressee
    )
  };
}

function resolveHostileDialogueEvent(
  packet: DialogueEventPacket,
  previousSpeaker: string | null,
  recentTemplateIds: ReadonlyArray<string>,
  recentChannels: ReadonlyArray<string>,
  recentSignatures: ReadonlyArray<string>
): ResolvedHostileDialogue | null {
  const tapeId = packet.dominantTapeId;
  if (!tapeId) {
    return null;
  }

  const context: "advance" | "contact" | "surrender" | "civilian" | "extract" =
    packet.kind === "extract-hot" || packet.kind === "extract-open"
      ? "extract"
      : packet.kind === "civilian"
        ? "civilian"
        : packet.kind === "surrender"
          ? "surrender"
          : packet.kind === "contact"
            ? "contact"
            : "advance";

  const profile = HOSTILE_SPEAKER_PROFILE[tapeId];
  let bestTemplate: HostileDialogueTemplate | null = null;
  let bestScore = Number.NEGATIVE_INFINITY;

  for (const template of HOSTILE_DIALOGUE_TEMPLATES) {
    if (template.kind !== context) {
      continue;
    }
    if (template.tapeId && template.tapeId !== tapeId) {
      continue;
    }
    let score = template.weight + Math.random() * 0.35;
    if (previousSpeaker === profile.speaker) {
      score -= 0.7;
    }
    const recentIndex = recentTemplateIds.indexOf(template.id);
    if (recentIndex !== -1) {
      score -= 1.85 - recentIndex * 0.24;
    }
    const recentChannelIndex = recentChannels.indexOf(template.channel);
    if (recentChannelIndex !== -1) {
      score -= 1.15 - recentChannelIndex * 0.16;
    }
    const wordCount = getDialogueWordCount(template.text);
    if (wordCount > 11) {
      score -= (wordCount - 11) * 0.18;
    }
    if (wordCount <= 8) {
      score += 0.12;
    }
    if (recentSignatures.includes(getDialogueSignature(template.text))) {
      score -= 1.3;
    }
    if (score > bestScore) {
      bestScore = score;
      bestTemplate = template;
    }
  }

  if (!bestTemplate) {
    return null;
  }

  return {
    templateId: bestTemplate.id,
    speaker: profile.speaker,
    role: profile.role,
    tapeId,
    tone: bestTemplate.tone,
    channel: bestTemplate.channel,
    line: fillSquadCallTemplate(bestTemplate.text, {
      focus: packet.locationLabel,
      focusLower: packet.locationLabel.toLowerCase(),
      extract: packet.extractLabel,
      extractLower: packet.extractLabel.toLowerCase(),
      breach: packet.breachLabel,
      breachLower: packet.breachLabel.toLowerCase(),
      enemyTape: getEnemyTapeDefinition(tapeId).label,
      memoryMate: "",
      addressee: "",
      addresseeLower: ""
    })
  };
}

function buildLegacyAmbientSquadCall(params: {
  context:
    | "advance"
    | "contact"
    | "mate-down"
    | "body-sighted"
    | "coffee"
    | "civilian"
    | "haul"
    | "intel"
    | "surrender"
    | "claim-breaking"
    | "claim-held"
    | "claim-loss"
    | "extract-live"
    | "extract-hot"
    | `order-${FrontlineSupportOrderId}`;
  focusedLabel: string;
  extractLabel: string;
  breachLabel: string;
  dominantTapeId: EnemyTapeId | null;
  playerCritical: boolean;
}): { speaker: string; tone: SquadCommsTone; channel: string; line: string } {
  const templates =
    SQUAD_AMBIENT_CALLS[params.context] ??
    SQUAD_AMBIENT_CALLS[(params.context.startsWith("order-") ? params.context : "advance") as keyof typeof SQUAD_AMBIENT_CALLS] ??
    SQUAD_AMBIENT_CALLS.advance;
  const tone: SquadCommsTone =
    params.context === "extract-live" || params.context === "order-secure-exfil"
      ? "extract"
      : params.context === "extract-hot" || params.context === "claim-breaking" || params.playerCritical
        ? "critical"
        : params.context === "contact" ||
            params.context === "mate-down" ||
            params.context === "body-sighted" ||
            params.context === "civilian" ||
            params.context === "intel" ||
            params.context === "haul" ||
            params.context === "surrender" ||
            params.context === "claim-held" ||
            params.context === "claim-loss" ||
            params.context === "coffee" ||
            params.context.startsWith("order-")
          ? "warning"
          : "steady";
  const speaker =
    params.context === "mate-down"
      ? "Yara"
      : params.context === "body-sighted"
        ? "Rook"
      : params.context === "order-draw-heat"
      ? "Makar"
      : params.context === "civilian" ||
          params.context === "haul" ||
          params.context === "coffee" ||
          params.context === "claim-loss" ||
          params.context === "order-secure-exfil"
        ? "Yara"
        : params.context === "surrender" || params.context === "claim-breaking" || params.context === "claim-held"
          ? "Rook"
        : params.context === "extract-live" || params.context === "extract-hot"
          ? "Makar"
          : "Rook";
  const dominantTape = params.dominantTapeId ? getEnemyTapeDefinition(params.dominantTapeId) : null;
  const tapeClause =
    params.context === "contact" ||
    params.context === "mate-down" ||
    params.context === "body-sighted" ||
    params.context === "civilian" ||
    params.context === "surrender" ||
    params.context === "claim-breaking" ||
    params.context === "claim-held" ||
    params.context === "claim-loss" ||
    params.context === "extract-hot" ||
    params.context.startsWith("order-")
      ? dominantTape
        ? params.dominantTapeId === "yellow"
          ? ` ${dominantTape.label} is in this lane and they do not miss.`
          : params.dominantTapeId === "green"
            ? ` ${dominantTape.label} is stacked here. Expect a cleaner enemy shove.`
            : ` ${dominantTape.label} regulars are the main body in this pocket.`
        : ""
      : "";
  const channel =
    params.context === "advance"
      ? "Quiet Walk"
      : params.context === "contact"
        ? dominantTape?.label ?? "Contact"
        : params.context === "mate-down"
          ? "Loss"
          : params.context === "body-sighted"
            ? "Memory"
        : params.context === "civilian"
          ? "Civilians"
        : params.context === "haul"
          ? "Loot Fever"
          : params.context === "claim-breaking"
            ? "Flag Team"
            : params.context === "claim-held"
              ? "Claim Hold"
              : params.context === "claim-loss"
                ? "Body Recovery"
          : params.context === "coffee"
            ? "Warm Hands"
          : params.context === "surrender"
            ? "Surrender"
          : params.context === "intel"
            ? "Intel Touch"
            : params.context === "extract-live"
              ? "Extract Live"
              : params.context === "extract-hot"
                ? "Hot Extract"
                : params.context === "order-breach-push"
                  ? "Breach Stack"
                  : params.context === "order-hold-position"
                    ? "Hold Position"
                  : params.context === "order-secure-exfil"
                    ? "Screen Exfil"
                    : params.context === "order-draw-heat"
                      ? "Heat Draw"
                      : params.context === "order-shift-fire"
                        ? "Shift Fire"
                        : "Net";

  const addresseeName = getFallbackDialogueAddresseeName(speaker, params.context);

  return {
    speaker,
    tone,
    channel,
    line: addSquadSpeakerFlavor(
      fillSquadCallTemplate(randomItem([...templates]), {
        focus: params.focusedLabel,
        focusLower: params.focusedLabel.toLowerCase(),
        extract: params.extractLabel,
        extractLower: params.extractLabel.toLowerCase(),
        breach: params.breachLabel,
        breachLower: params.breachLabel.toLowerCase(),
        enemyTape: dominantTape?.label ?? "Blue",
        memoryMate: "the last one",
        addressee: addresseeName ?? "",
        addresseeLower: addresseeName?.toLowerCase() ?? ""
      }) + tapeClause,
      speaker,
      params.context
    )
  };
}

function buildAmbientSquadCall(params: {
  context:
    | "advance"
    | "contact"
    | "coffee"
    | "civilian"
    | "haul"
    | "intel"
    | "surrender"
    | "claim-breaking"
    | "claim-held"
    | "claim-loss"
    | "extract-live"
    | "extract-hot"
    | `order-${FrontlineSupportOrderId}`;
  focusedLabel: string;
  extractLabel: string;
  breachLabel: string;
  dominantTapeId: EnemyTapeId | null;
  playerCritical: boolean;
  squadMates: ReadonlyArray<SquadMateState>;
  previousSpeaker: string | null;
  recentTemplateIds: ReadonlyArray<string>;
  recentChannels: ReadonlyArray<string>;
  recentSignatures: ReadonlyArray<string>;
}): {
  templateId?: string;
  speaker: string;
  tone: SquadCommsTone;
  channel: string;
  line: string;
  packet: DialogueEventPacket | null;
} {
  const packet = buildDialogueEventPacketFromContext(params);
  const resolved = packet
    ? resolveSquadDialogueEvent(
        packet,
        params.squadMates,
        params.previousSpeaker,
        params.recentTemplateIds,
        params.recentChannels,
        params.recentSignatures
      )
    : null;

  if (resolved) {
    return {
      ...resolved,
      packet
    };
  }

  return {
    ...buildLegacyAmbientSquadCall(params),
    packet
  };
}

function getEnemyTapePriority(tapeId: EnemyTapeId): number {
  return tapeId === "yellow" ? 3 : tapeId === "green" ? 2 : 1;
}

export function getDominantEnemyTapeId(
  enemies: ReadonlyArray<Pick<EnemyState, "tapeId" | "position">>,
  point: Vec2,
  radius = 420
): EnemyTapeId | null {
  const nearbyEnemies = enemies.filter((enemy) => distance(enemy.position, point) <= radius);

  if (nearbyEnemies.length === 0) {
    return null;
  }

  return [...nearbyEnemies].sort((left, right) => getEnemyTapePriority(right.tapeId) - getEnemyTapePriority(left.tapeId))[0]?.tapeId ?? null;
}

export function getSquadBattleRead(state: RaidState): SquadBattleRead {
  const dominantTapeId = getDominantEnemyTapeId(state.enemies, state.player.position);
  const dominantTape = dominantTapeId ? getEnemyTapeDefinition(dominantTapeId) : null;
  const coffeeRead = getFrontlineCoffeePocketRead(state);
  const focusedIncident = getFocusedFrontlineIncidentForState(state);
  const activeOrderId =
    state.activeFrontlineSupportOrderId && state.frontlineSupportOrderTimer > 0
      ? state.activeFrontlineSupportOrderId
      : null;

  if (state.extractionHoldTimer > 0 && state.extractionContested) {
    return {
      label: "Hold the Ring",
      detail: `${state.extractionContesters} hostile body${state.extractionContesters === 1 ? "" : "ies"} are inside the pull and the boys need the ring cleared now.`,
      tone: "critical"
    };
  }

  if (state.extractionHoldTimer > 0) {
    return {
      label: "Beacon Burning",
      detail: "The exfil beacon is already live. Staying in the ring matters more than one more greedy touch.",
      tone: "extract"
    };
  }

  if (activeOrderId === "breach-push") {
    return {
      label: "Breach Stack",
      detail: "The boys are compressed on the cut and want a full room shove, not a doorway stall.",
      tone: "warning"
    };
  }

  if (activeOrderId === "secure-exfil") {
    return {
      label: "Screen the Pull",
      detail: "Your escort is shaping the fallback lane first so the haul survives the walk home.",
      tone: "extract"
    };
  }

  if (activeOrderId === "draw-heat") {
    return {
      label: "Sell the Fake",
      detail: "The boys are leaning loud to drag eyes off the true lane and buy the real shove clean space.",
      tone: "warning"
    };
  }

  if (activeOrderId === "shift-fire") {
    return {
      label: "Pin the Lane",
      detail: "Your escort is suppressing the hot pocket so the player can cross under shared gun pressure.",
      tone: "warning"
    };
  }

  if (state.pendingReinforcements.length > 0) {
    const nextWave = state.pendingReinforcements.reduce((best, entry) => (entry.timer < best.timer ? entry : best));
    return {
      label: "Crash Building",
      detail: `${nextWave.label} is ${nextWave.timer.toFixed(1)}s out. The frontline is about to get louder whether you want it or not.`,
      tone: "critical"
    };
  }

  if (coffeeRead && !state.activeIntelCapture && !state.activeLootPickup && !state.activeSearch) {
    return {
      label: coffeeRead.title,
      detail: coffeeRead.detail,
      tone: coffeeRead.tone
    };
  }

  if (focusedIncident?.kind === "firefight") {
    if (focusedIncident.markerState === "raising" || focusedIncident.territoryState === "breaking") {
      return {
        label: "Lock the Scar",
        detail: "The pocket is only half-held. Plant the route flag, keep Blue off the lane, and turn the break into owned ground before it collapses.",
        tone: "critical"
      };
    }

    if (focusedIncident.markerState === "planted" || focusedIncident.territoryState === "reclaimed") {
      return {
        label: "Flag Hold",
        detail: "The claim is buying cover right now. Keep the planted pocket owned and push the next move off that fresh foothold instead of drifting away from it.",
        tone: "warning"
      };
    }

    if (focusedIncident.markerState === "bagged" || focusedIncident.territoryState === "lost") {
      return {
        label: "Bodies Off Lane",
        detail: "This scar is memory, not safety. Clear the recovery cleanly, then decide whether the squad can afford one more shove to reclaim it.",
        tone: "warning"
      };
    }
  }

  if (focusedIncident?.kind === "civilian") {
    return {
      label: "Walk the Family",
      detail: "A shelter beat is live. Keep muzzles disciplined, escort the family through the shell lane, and turn the block into a human win instead of collateral.",
      tone: "warning"
    };
  }

  if (
    focusedIncident?.kind === "firefight" &&
    focusedIncident.status === "routed" &&
    focusedIncident.territoryState === "reclaimed" &&
    focusedIncident.opportunityLabel
  ) {
    return {
      label: "Surrender Window",
      detail: "The pocket is broken. Keep the lane covered, force the surrender, and bag the route notes before one last dirty peek reopens the firefight.",
      tone: "warning"
    };
  }

  if (dominantTape && state.enemies.some((enemy) => enemy.awareness === "engaged")) {
    return {
      label: `${dominantTape.shortLabel} Tape Close`,
      detail:
        dominantTapeId === "yellow"
          ? "Foreign volunteers are the sharpest nearby read. They crowd angles, recover faster under pressure, and punish greedy peeks."
          : dominantTapeId === "green"
            ? "Elite Blue pushers are stacked in this pocket. They reacquire fast and keep cleaner spacing through the room fight."
            : "Regular Blue tape is the main body here. The lane is workable if you keep them pinned before they settle again.",
      tone: dominantTapeId === "blue" ? "warning" : "critical"
    };
  }

  if (state.activeIntelCapture) {
    return {
      label: "Intel Touch",
      detail: "The uplink is live. The boys need a few calm seconds on the terminal before the route is worth extracting.",
      tone: "warning"
    };
  }

  if (state.activeLootPickup || state.activeSearch) {
    return {
      label: "Hands on Haul",
      detail: "Loot is being stripped in the open. The squad only needs a short quiet window to turn it into real stash weight.",
      tone: "warning"
    };
  }

  return {
    label: "Quiet Walk",
    detail: "The lane is calm enough to breathe, but the boys still expect the sector to snap loud without warning.",
    tone: "steady"
  };
}

const getNearestPocket = (
  route: RaidRouteDefinition,
  point: Vec2
): RaidRouteDefinition["combatPockets"][number] | null => {
  let nearestPocket: RaidRouteDefinition["combatPockets"][number] | null = null;
  let nearestDistance = Number.POSITIVE_INFINITY;

  for (const pocket of route.combatPockets) {
    const pocketDistance = distance(point, pocket.position);

    if (pocketDistance < nearestDistance) {
      nearestDistance = pocketDistance;
      nearestPocket = pocket;
    }
  }

  return nearestPocket;
};

const getFarthestPocket = (
  route: RaidRouteDefinition,
  referencePocket: RaidRouteDefinition["combatPockets"][number]
): RaidRouteDefinition["combatPockets"][number] | null => {
  let farthestPocket: RaidRouteDefinition["combatPockets"][number] | null = null;
  let farthestDistance = -1;

  for (const pocket of route.combatPockets) {
    if (pocket.label === referencePocket.label) {
      continue;
    }

    const pocketDistance = distance(referencePocket.position, pocket.position);

    if (pocketDistance > farthestDistance) {
      farthestDistance = pocketDistance;
      farthestPocket = pocket;
    }
  }

  return farthestPocket;
};

const getPocketCandidates = (
  route: RaidRouteDefinition,
  excludedLabels: ReadonlyArray<string>
): RaidRouteDefinition["combatPockets"] =>
  route.combatPockets.filter((pocket) => !excludedLabels.includes(pocket.label));

const getMiddlePocket = (
  route: RaidRouteDefinition,
  entryPocket: RaidRouteDefinition["combatPockets"][number] | null,
  extractPocket: RaidRouteDefinition["combatPockets"][number] | null
): RaidRouteDefinition["combatPockets"][number] | null =>
  route.combatPockets.find(
    (pocket) => pocket.label !== entryPocket?.label && pocket.label !== extractPocket?.label
  ) ?? route.combatPockets.find((pocket) => pocket.label !== entryPocket?.label) ?? route.combatPockets[0] ?? null;

const clampChance = (value: number): number => clamp(value, 0.1, 0.92);

const pickPocketByPreference = (
  route: RaidRouteDefinition,
  preference: RouteThreatIdentity["pressurePocket"],
  entryPocket: RaidRouteDefinition["combatPockets"][number] | null,
  middlePocket: RaidRouteDefinition["combatPockets"][number] | null,
  extractPocket: RaidRouteDefinition["combatPockets"][number] | null,
  fallback: RaidRouteDefinition["combatPockets"][number] | null
): RaidRouteDefinition["combatPockets"][number] | null => {
  if (preference === "entry") {
    return entryPocket ?? middlePocket ?? extractPocket ?? fallback;
  }

  if (preference === "middle") {
    return middlePocket ?? entryPocket ?? extractPocket ?? fallback;
  }

  if (preference === "extract") {
    return extractPocket ?? middlePocket ?? entryPocket ?? fallback;
  }

  return route.combatPockets.length > 0 ? randomItem(route.combatPockets) : fallback;
};

