const buildEnemyAnchorPlan = (
  route: RaidRouteDefinition,
  playerPosition: Vec2
): {
  spawns: StagedEnemySpawnPlan[];
  threatLabel: string;
  threatSummary: string;
  pressurePocket: RaidRouteDefinition["combatPockets"][number] | null;
  secondaryPressurePocket: RaidRouteDefinition["combatPockets"][number] | null;
  thinPocket: RaidRouteDefinition["combatPockets"][number] | null;
  sweepPocket: RaidRouteDefinition["combatPockets"][number] | null;
  reservePocket: RaidRouteDefinition["combatPockets"][number] | null;
  pocketPlan: RaidPocketPlanState[];
  sweepCount: number;
  holdCount: number;
  patrolCount: number;
  reserveCount: number;
} => {
  const threatPatterns = [
    {
      label: "Crossfire Nest",
      summary: "One combat pocket is stacked hard while a second lane runs an early crossing sweep.",
      clusterPull: RAID_STAGE_CLUSTER_PULL + 28,
      restlessPull: RAID_STAGE_RESTLESS_PULL - 12,
      withdrawalPull: RAID_STAGE_CLUSTER_PULL * 0.5,
      reservePull: RAID_STAGE_RESERVE_PULL * 0.72,
      sweepChance: 0.5,
      splitSweep: false,
      holdChance: 0.9,
      patrolChance: 0.08
    },
    {
      label: "Split Net",
      summary: "Pressure is split across two angles, so the route asks for cleaner scouting between pockets.",
      clusterPull: RAID_STAGE_CLUSTER_PULL - 12,
      restlessPull: RAID_STAGE_RESTLESS_PULL + 18,
      withdrawalPull: RAID_STAGE_CLUSTER_PULL * 0.34,
      reservePull: RAID_STAGE_RESERVE_PULL * 0.84,
      sweepChance: 0.62,
      splitSweep: true,
      holdChance: 0.68,
      patrolChance: 0.24
    },
    {
      label: "Late Collapse",
      summary: "Front pockets open looser, but a deeper reserve lane holds bodies for the mid-raid collapse.",
      clusterPull: RAID_STAGE_CLUSTER_PULL - 18,
      restlessPull: RAID_STAGE_RESTLESS_PULL - 10,
      withdrawalPull: RAID_STAGE_CLUSTER_PULL * 0.58,
      reservePull: RAID_STAGE_RESERVE_PULL + 34,
      sweepChance: 0.34,
      splitSweep: false,
      holdChance: 0.58,
      patrolChance: 0.14
    },
    {
      label: "Restless Hunt",
      summary: "Scavs drift wider off their anchors, making the opening lane feel less scripted even before reinforcements hit.",
      clusterPull: RAID_STAGE_CLUSTER_PULL - 4,
      restlessPull: RAID_STAGE_RESTLESS_PULL + 42,
      withdrawalPull: RAID_STAGE_CLUSTER_PULL * 0.38,
      reservePull: RAID_STAGE_RESERVE_PULL * 0.92,
      sweepChance: 0.44,
      splitSweep: true,
      holdChance: 0.48,
      patrolChance: 0.38
    }
  ] as const;
  const threatPattern = randomItem(threatPatterns);
  const routeIdentity = randomItem(ROUTE_THREAT_IDENTITIES[route.id]);
  const entryPocket = getNearestPocket(route, playerPosition);
  const extractPocket = getNearestPocket(route, route.extractZone.position);
  const middlePocket = getMiddlePocket(route, entryPocket, extractPocket);
  const pressurePocket = pickPocketByPreference(
    route,
    routeIdentity.pressurePocket,
    entryPocket,
    middlePocket,
    extractPocket,
    route.combatPockets.length > 0 ? randomItem(route.combatPockets) : null
  );
  const thinPocket = pressurePocket ? getFarthestPocket(route, pressurePocket) : null;
  const splitSweep = routeIdentity.forceSplitSweep ?? threatPattern.splitSweep;
  const secondaryPressurePocket = pickSecondaryPressurePocket(
    route,
    pressurePocket,
    thinPocket,
    null,
    splitSweep || threatPattern.label === "Split Net"
  );
  const sweepExclusions = [thinPocket?.label, splitSweep ? undefined : pressurePocket?.label].filter(
    (label): label is string => Boolean(label)
  );
  const sweepCandidates = getPocketCandidates(route, sweepExclusions);
  const sweepPocket =
    sweepCandidates.length > 0 ? randomItem(sweepCandidates) : pressurePocket;
  const reservePocket = pickPocketByPreference(
    route,
    routeIdentity.reservePocket,
    entryPocket,
    middlePocket,
    extractPocket,
    getPocketCandidates(
      route,
      [pressurePocket?.label, secondaryPressurePocket?.label, thinPocket?.label, sweepPocket?.label].filter(
        (label): label is string => Boolean(label)
      )
    )[0] ?? null
  );
  const pressureTargets = [pressurePocket, secondaryPressurePocket].filter(
    (pocket): pocket is RaidRouteDefinition["combatPockets"][number] => Boolean(pocket)
  );
  const pressureAnchor =
    pressureTargets.length > 0
      ? {
          x: pressureTargets.reduce((sum, pocket) => sum + pocket.position.x, 0) / pressureTargets.length,
          y: pressureTargets.reduce((sum, pocket) => sum + pocket.position.y, 0) / pressureTargets.length
        }
      : null;
  const biasDirection = pressureAnchor ? normalize(subtract(pressureAnchor, playerPosition)) : { x: 0, y: 0 };
  const routeDirection = normalize(subtract(route.extractZone.position, playerPosition));
  const clusterPull = threatPattern.clusterPull + routeIdentity.clusterPullDelta;
  const restlessPull = threatPattern.restlessPull + routeIdentity.restlessPullDelta;
  const withdrawalPull = Math.max(18, threatPattern.withdrawalPull + routeIdentity.withdrawalPullDelta);
  const reservePull = Math.max(32, threatPattern.reservePull + routeIdentity.reservePullDelta);
  const sweepChance = clampChance(threatPattern.sweepChance + routeIdentity.sweepChanceDelta);
  const patrolChance = clampChance(threatPattern.patrolChance + routeIdentity.patrolChanceDelta);
  const holdChance = clampChance(threatPattern.holdChance + routeIdentity.holdChanceDelta);
  let sweepCount = 0;
  let holdCount = 0;
  let patrolCount = 0;
  let reserveCount = 0;
  const spawns = route.enemySpawnPoints.map((anchor, index) => {
    const nearestPocket = getNearestPocket(route, anchor);
    let plannedAnchor = { ...anchor };

    if (pressurePocket && nearestPocket?.label === pressurePocket.label) {
      const pocketVector = normalize(subtract(pressurePocket.position, anchor));
      plannedAnchor = add(plannedAnchor, multiply(pocketVector, clusterPull));
    } else if (secondaryPressurePocket && nearestPocket?.label === secondaryPressurePocket.label) {
      const secondaryVector = normalize(subtract(secondaryPressurePocket.position, anchor));
      plannedAnchor = add(plannedAnchor, multiply(secondaryVector, Math.max(28, clusterPull * 0.72)));
    } else if (thinPocket && nearestPocket?.label === thinPocket.label) {
      const withdrawalVector = normalize(subtract(anchor, thinPocket.position));
      plannedAnchor = add(plannedAnchor, multiply(withdrawalVector, withdrawalPull));
    } else if (reservePocket && nearestPocket?.label === reservePocket.label) {
      const reserveVector = normalize(subtract(route.extractZone.position, anchor));
      plannedAnchor = add(plannedAnchor, multiply(reserveVector, reservePull));
    } else if (pressurePocket) {
      plannedAnchor = add(plannedAnchor, multiply(biasDirection, restlessPull));
    }

    const anchorPoint = clampWorldPoint(plannedAnchor);
    const shouldSweep =
      Boolean(sweepPocket && nearestPocket?.label === sweepPocket.label) &&
      (index === 0 || Math.random() < sweepChance);

    const pocketDirection = nearestPocket
      ? normalize(subtract(route.extractZone.position, nearestPocket.position))
      : routeDirection;
    const laneDirection = length(pocketDirection) > 0.1 ? pocketDirection : biasDirection;
    const laneSide = perpendicular(length(laneDirection) > 0.1 ? laneDirection : { x: 1, y: 0 });
    const facingTarget =
      nearestPocket?.position ??
      secondaryPressurePocket?.position ??
      pressurePocket?.position ??
      add(anchorPoint, multiply(length(routeDirection) > 0.1 ? routeDirection : { x: 1, y: 0 }, 160));

    if (shouldSweep) {
      sweepCount += 1;
      const sweepSide = Math.random() > 0.5 ? 1 : -1;
      const sweepSpawn = clampWorldPoint(
        add(
          add(anchorPoint, multiply(laneDirection, -RAID_STAGE_SWEEP_OFFSET)),
          multiply(laneSide, RAID_STAGE_SWEEP_LATERAL * sweepSide)
        )
      );

      return {
        position: sweepSpawn,
        anchor: anchorPoint,
        isSweeper: true,
        posture: "sweeper" as const,
        facingTarget: anchorPoint
      };
    }

    const inReservePocket = Boolean(reservePocket && nearestPocket?.label === reservePocket.label);
    const shouldPatrol =
      !inReservePocket &&
      (threatPattern.label === "Restless Hunt" ||
        (thinPocket && nearestPocket?.label === thinPocket.label) ||
        Math.random() < patrolChance);

    if (inReservePocket) {
      reserveCount += 1;
      const reserveSpawn = clampWorldPoint(
        add(
          add(anchorPoint, multiply(laneDirection, -RAID_STAGE_PATROL_OFFSET * 0.56)),
          multiply(laneSide, (Math.random() > 0.5 ? 1 : -1) * RAID_STAGE_RESERVE_SCATTER)
        )
      );
      return {
        position: reserveSpawn,
        anchor: anchorPoint,
        isSweeper: false,
        posture: "reserve" as const,
        facingTarget
      };
    }

    if (shouldPatrol) {
      patrolCount += 1;
      const patrolSide = Math.random() > 0.5 ? 1 : -1;
      const patrolSpawn = clampWorldPoint(
        add(
          add(anchorPoint, multiply(laneDirection, -RAID_STAGE_PATROL_OFFSET)),
          multiply(laneSide, RAID_STAGE_PATROL_LATERAL * patrolSide)
        )
      );
      const patrolAnchor = clampWorldPoint(
        add(
          add(anchorPoint, multiply(laneDirection, RAID_STAGE_PATROL_OFFSET * 0.36)),
          multiply(laneSide, RAID_STAGE_PATROL_LATERAL * -0.24 * patrolSide)
        )
      );
      return {
        position: patrolSpawn,
        anchor: patrolAnchor,
        isSweeper: false,
        posture: "patrol" as const,
        facingTarget: patrolAnchor
      };
    }

    if (Math.random() > holdChance) {
      patrolCount += 1;
      const driftSide = Math.random() > 0.5 ? 1 : -1;
      const driftSpawn = clampWorldPoint(
        add(
          add(anchorPoint, multiply(laneDirection, -RAID_STAGE_PATROL_OFFSET * 0.72)),
          multiply(laneSide, RAID_STAGE_PATROL_LATERAL * 0.72 * driftSide)
        )
      );
      return {
        position: driftSpawn,
        anchor: anchorPoint,
        isSweeper: false,
        posture: "patrol" as const,
        facingTarget
      };
    }

    holdCount += 1;
    const holdPosition =
      Math.random() > 0.34 ? clampWorldPoint(randomPointAround(anchorPoint, RAID_STAGE_HOLD_SCATTER)) : anchorPoint;
    return {
      position: holdPosition,
      anchor: anchorPoint,
      isSweeper: false,
      posture: "hold" as const,
      facingTarget
    };
  });

  const thinSummary = thinPocket ? `${thinPocket.label} opens thinner` : "no lane opens especially thin";
  const secondaryPressureSummary = secondaryPressurePocket
    ? `${secondaryPressurePocket.label} is the second hot lane`
    : "no second hot lane fully forms";
  const sweepSummary =
    sweepPocket && sweepCount > 0
      ? `${sweepCount} sweeper${sweepCount === 1 ? "" : "s"} cross ${sweepPocket.label}`
      : "no sweep team is crossing yet";
  const reserveSummary = reservePocket ? `${reservePocket.label} is holding the late reserve` : "no reserve lane is banking extra bodies";
  const postureSummary = `${holdCount} hold${holdCount === 1 ? "" : "s"}, ${patrolCount} patrol${patrolCount === 1 ? "" : "s"}, ${reserveCount} reserve${reserveCount === 1 ? "" : "s"}`;
  const pocketPlan = buildPocketPlan(
    pressurePocket,
    secondaryPressurePocket,
    thinPocket,
    sweepPocket,
    reservePocket
  );

  return {
    pressurePocket,
    secondaryPressurePocket,
    thinPocket,
    sweepPocket,
    reservePocket,
    pocketPlan,
    sweepCount,
    holdCount,
    patrolCount,
    reserveCount,
    spawns,
    threatLabel: `${routeIdentity.label} // ${threatPattern.label}`,
    threatSummary: `${routeIdentity.summary} ${threatPattern.summary} ${pressurePocket ? `${pressurePocket.label} is the main hot pocket, ` : ""}${secondaryPressureSummary}, ${thinSummary}, ${sweepSummary}, ${reserveSummary}, and the opener fields ${postureSummary}.`
  };
};

const buildPocketEventPlan = (
  route: RaidRouteDefinition,
  insertion: RaidInsertionDefinition,
  enemyPlan: ReturnType<typeof buildEnemyAnchorPlan>,
  obstacles: ReadonlyArray<ArenaObstacle>
): RaidPocketEventPlan | null => {
  if (route.combatPockets.length === 0) {
    return null;
  }

  const eventProfiles = [
    {
      id: "black-crate" as const,
      kind: "locker" as const,
      getPocket: () => enemyPlan.thinPocket ?? enemyPlan.reservePocket ?? enemyPlan.pressurePocket ?? randomItem(route.combatPockets),
      getLabel: (pocketLabel: string) => `${pocketLabel} Black Crate`,
      getSummary: (pocketLabel: string) =>
        `${pocketLabel} is holding a broker black crate this roll. It pays rich hardware if you can win the thinner lane long enough to pull it.`,
      rewardCredits: 230 + Math.floor(Math.random() * 41),
      medkitReward: 1,
      ammoReward: 14 + Math.floor(Math.random() * 7),
      stashReward: { medkits: 1, ammoPacks: 1 } as SupplyStock,
      demandCategory: "hardware" as const
    },
    {
      id: "field-triage" as const,
      kind: "medical" as const,
      getPocket: () => enemyPlan.pressurePocket ?? enemyPlan.sweepPocket ?? randomItem(route.combatPockets),
      getLabel: (pocketLabel: string) => `${pocketLabel} Triage Drop`,
      getSummary: (pocketLabel: string) =>
        `${pocketLabel} is carrying a live triage drop this roll. It is a sustain-heavy detour that pays back med supply if you can hold the hot pocket cleanly.`,
      rewardCredits: 120 + Math.floor(Math.random() * 31),
      medkitReward: 2,
      ammoReward: 0,
      stashReward: { medkits: 1, ammoPacks: 0 } as SupplyStock,
      demandCategory: "medical" as const
    },
    {
      id: "ammo-spill" as const,
      kind: "ammo" as const,
      getPocket: () => enemyPlan.sweepPocket ?? enemyPlan.reservePocket ?? randomItem(route.combatPockets),
      getLabel: (pocketLabel: string) => `${pocketLabel} Ammo Spill`,
      getSummary: (pocketLabel: string) =>
        `${pocketLabel} is holding a cracked ammo spill this roll. It reloads the run if you can own the crossing lane before the next sweep arrives.`,
      rewardCredits: 150 + Math.floor(Math.random() * 36),
      medkitReward: 0,
      ammoReward: 34 + Math.floor(Math.random() * 11),
      stashReward: { medkits: 0, ammoPacks: 1 } as SupplyStock,
      demandCategory: "munitions" as const
    }
  ] as const;

  const eventProfile = randomItem(eventProfiles);
  const pocket = eventProfile.getPocket();

  if (!pocket) {
    return null;
  }

  const routeDirection = normalize(subtract(route.extractZone.position, pocket.position));
  const forward = length(routeDirection) > 0.1 ? routeDirection : normalize(subtract(route.extractZone.position, insertion.position));
  const side = perpendicular(length(forward) > 0.1 ? forward : { x: 1, y: 0 });
  const approachSide = Math.random() > 0.5 ? 1 : -1;
  const stagingPoint = add(
    add(pocket.position, multiply(forward, -26 - Math.random() * 22)),
    multiply(side, approachSide * (24 + Math.random() * 38))
  );
  const position = findWalkableSpawnPoint(
    stagingPoint,
    16,
    92,
    obstacles,
    [
      insertion.position,
      ...route.intelPositions,
      ...route.supplyCaches.map((cache) => cache.position),
      ...route.extractOptions.map((extract) => extract.position)
    ],
    80
  );
  const label = eventProfile.getLabel(pocket.label);
  const summary = eventProfile.getSummary(pocket.label);

  return {
    id: eventProfile.id,
    label,
    summary,
    pocketLabel: pocket.label,
    cache: {
      id: 90 + route.combatPockets.findIndex((entry) => entry.label === pocket.label) + 1,
      position,
      kind: eventProfile.kind,
      label,
      searchDuration: POCKET_EVENT_SEARCH_SECONDS[eventProfile.id],
      demandCategory: eventProfile.demandCategory,
      rewardCredits: eventProfile.rewardCredits,
      medkitReward: eventProfile.medkitReward,
      ammoReward: eventProfile.ammoReward,
      stashReward: eventProfile.stashReward,
      opportunityId: eventProfile.id,
      opportunitySummary: summary
    }
  };
};

const createContractState = (
  template: (typeof CONTRACT_TEMPLATES)[number]
): RaidContractState => {
  return {
    ...template,
    progress: 0,
    completed: false,
    failed: false
  };
};

const createContractBoard = (rotation: number): RaidContractState[] =>
  CONTRACT_TEMPLATES.map((_, index) =>
    createContractState(CONTRACT_TEMPLATES[(rotation + index) % CONTRACT_TEMPLATES.length])
  );

const cloneContract = (contract: RaidContractState): RaidContractState => ({
  ...contract
});

const createEnemy = (
  id: number,
  position: Vec2,
  archetypeId: EnemyArchetypeId,
  facingTarget: Vec2,
  alert = false
): EnemyState => {
  const archetype = SCAV_ARCHETYPES[archetypeId];
  const tapeId = getTapeIdForEnemy(id, archetypeId);
  const tapeCombatTuning = getEnemyTapeCombatTuning(tapeId);
  const weaponId = getArchetypeWeaponId(archetypeId);
  const combatProfile = getSharedWeaponCombatProfile(weaponId, archetypeId);

  return {
    id,
    archetypeId,
    tapeId,
    weaponId,
    position: { ...position },
    velocity: { x: 0, y: 0 },
    facing: normalize(subtract(facingTarget, position)),
    health: archetype.health,
    maxHealth: archetype.health,
    radius: archetypeId === "rusher" ? 17 : 16,
    cooldown:
      (combatProfile.fireIntervalMin +
        Math.random() * Math.max(0.05, combatProfile.fireIntervalMax - combatProfile.fireIntervalMin)) *
      tapeCombatTuning.fireIntervalMultiplier,
    grenadeStock: getEnemyGrenadeStock(archetypeId, tapeId),
    grenadeCooldown: 0,
    anchor: { ...position },
    openingPosture: "hold",
    squadId: null,
    squadRole: "anchor-rifle",
    supportStrongpointLabel: null,
    supportStrongpointTier: null,
    supportLaneLabel: null,
    doctrineState: "hold-threshold",
    doctrineWatchDirection: null,
    doctrineWatchArcDegrees: null,
    alert,
    awareness: alert ? "investigating" : "patrol",
    investigateTarget: alert ? { ...position } : null,
    investigateTimer: 0,
    navigationStallTime: 0,
    navigationRecoveryIndex: 0,
    lastNavigationSample: { ...position },
    navigationCommittedTarget: null,
    pressureType: null,
    pressureTimer: 0,
    blindFireTimer: 0,
    panicTimer: 0,
    armorBrokenTimer: 0,
    armorFlash: 0,
    fleshFlash: 0,
    casualtyState: "healthy",
    woundSeverity: "none",
    bleedoutTimer: 0,
    stabilized: false,
    compressionState: "idle",
    compressionTimer: 0
  };
};

function assignPlannedEnemySquads(
  routeId: string,
  plannedSpawns: ReadonlyArray<{
    anchor: Vec2;
    position: Vec2;
    posture: EnemyOpeningPosture;
    archetypeId: EnemyArchetypeId;
  }>,
  supportStrongpoints: ReadonlyArray<HostileSupportStrongpoint>
): {
  assignments: PlannedEnemySquadAssignment[];
  reservedStrongpointsBySquadId: Map<string, HostileSupportStrongpoint>;
} {
  const assignments: PlannedEnemySquadAssignment[] = plannedSpawns.map(() => ({
    squadId: `${routeId}-enemy-1`,
    squadRole: "anchor-rifle"
  }));
  const reservedStrongpointsBySquadId = new Map<string, HostileSupportStrongpoint>();
  const unassignedIndices = new Set(plannedSpawns.map((_, index) => index));
  const buildingStrongpoints = supportStrongpoints.filter((strongpoint) => strongpoint.placementKind === "building");
  const guardedBuildingStrongpoints = buildingStrongpoints
    .filter((strongpoint) => strongpoint.guarded)
    .sort((left, right) => {
      if (getBuildingOccupationTierWeight(left.occupationTier) !== getBuildingOccupationTierWeight(right.occupationTier)) {
        return getBuildingOccupationTierWeight(left.occupationTier) - getBuildingOccupationTierWeight(right.occupationTier);
      }
      if (Math.abs(right.priority - left.priority) > 0.01) {
        return right.priority - left.priority;
      }
      return left.label.localeCompare(right.label);
    });
  const sortedIndices = plannedSpawns
    .map((_, index) => index)
    .sort((left, right) => {
      const leftSpawn = plannedSpawns[left];
      const rightSpawn = plannedSpawns[right];
      if (Math.abs(leftSpawn.anchor.x - rightSpawn.anchor.x) > 0.1) {
        return leftSpawn.anchor.x - rightSpawn.anchor.x;
      }
      return leftSpawn.anchor.y - rightSpawn.anchor.y;
    });
  const clusters: Array<{
    id: string;
    indices: number[];
    centroid: Vec2;
    strongpointLabel: string | null;
  }> = [];

  const takeBestIndex = (
    available: number[],
    score: (spawnIndex: number) => number
  ): number | null => {
    if (available.length === 0) {
      return null;
    }

    let bestIndex = available[0];
    let bestScore = score(bestIndex);
    for (const candidate of available.slice(1)) {
      const candidateScore = score(candidate);
      if (candidateScore > bestScore) {
        bestIndex = candidate;
        bestScore = candidateScore;
      }
    }

    return bestIndex;
  };

  const assignReservedRole = (
    available: number[],
    squadId: string,
    squadRole: EnemySquadRole,
    score: (spawnIndex: number) => number
  ): void => {
    const reservedIndex = takeBestIndex(available, score);
    if (reservedIndex === null) {
      return;
    }
    assignments[reservedIndex] = { squadId, squadRole };
    available.splice(available.indexOf(reservedIndex), 1);
    unassignedIndices.delete(reservedIndex);
  };

  guardedBuildingStrongpoints.forEach((strongpoint, guardedIndex) => {
    if (unassignedIndices.size < 4) {
      return;
    }

    const squadId = `${routeId}-enemy-${guardedIndex + 1}`;
    const available = [...unassignedIndices];
    const weightedDistance = (spawnIndex: number): number =>
      distance(plannedSpawns[spawnIndex].anchor, strongpoint.position) / Math.max(0.5, strongpoint.priority);

    assignReservedRole(available, squadId, "support-gunner", (spawnIndex) => {
      const spawn = plannedSpawns[spawnIndex];
      const postureScore =
        spawn.posture === "hold" ? 3.1 : spawn.posture === "reserve" ? 2.8 : spawn.posture === "patrol" ? 1.4 : 0.7;
      const archetypeScore = spawn.archetypeId === "rifleman" ? 3 : spawn.archetypeId === "skirmisher" ? 2.2 : 0.6;
      return postureScore + archetypeScore + getSupportStrongpointScore(spawn.anchor, [strongpoint]) - weightedDistance(spawnIndex) / 220;
    });
    assignReservedRole(available, squadId, "anchor-rifle", (spawnIndex) => {
      const spawn = plannedSpawns[spawnIndex];
      const postureScore = spawn.posture === "hold" ? 3.2 : spawn.posture === "reserve" ? 2.4 : 1.1;
      const archetypeScore = spawn.archetypeId === "rusher" ? 0.4 : 1.2;
      return postureScore + archetypeScore - weightedDistance(spawnIndex) / 210;
    });
    assignReservedRole(available, squadId, "probe-rifle", (spawnIndex) => {
      const spawn = plannedSpawns[spawnIndex];
      const postureScore =
        spawn.posture === "sweeper" ? 3 : spawn.posture === "patrol" ? 2.5 : spawn.posture === "reserve" ? 1.8 : 1.3;
      const archetypeScore = spawn.archetypeId === "rusher" ? 2.2 : spawn.archetypeId === "skirmisher" ? 1.5 : 1;
      return postureScore + archetypeScore - weightedDistance(spawnIndex) / 260;
    });
    assignReservedRole(available, squadId, "deep-rifle", (spawnIndex) => {
      const spawn = plannedSpawns[spawnIndex];
      const postureScore = spawn.posture === "reserve" ? 3.4 : spawn.posture === "hold" ? 2.7 : 1;
      const archetypeScore = spawn.archetypeId === "rifleman" ? 1.5 : 1;
      return postureScore + archetypeScore - weightedDistance(spawnIndex) / 240;
    });

    if (![...assignments].some((assignment) => assignment.squadId === squadId && assignment.squadRole === "deep-rifle")) {
      return;
    }

    reservedStrongpointsBySquadId.set(squadId, strongpoint);
  });

  sortedIndices.forEach((spawnIndex) => {
    if (!unassignedIndices.has(spawnIndex)) {
      return;
    }
    const spawn = plannedSpawns[spawnIndex];
    const nearestBuildingStrongpoint = getNearestHostileStrongpoint(spawn.anchor, buildingStrongpoints, 150);
    let bestCluster: (typeof clusters)[number] | null = null;
    let bestDistance = Number.POSITIVE_INFINITY;

    if (nearestBuildingStrongpoint) {
      for (const cluster of clusters) {
        if (cluster.indices.length >= 4 || cluster.strongpointLabel !== nearestBuildingStrongpoint.label) {
          continue;
        }
        const clusterDistance = distance(spawn.anchor, cluster.centroid);
        if (clusterDistance < bestDistance) {
          bestCluster = cluster;
          bestDistance = clusterDistance;
        }
      }
    }

    if (!bestCluster) {
      for (const cluster of clusters) {
        const clusterDistance = distance(spawn.anchor, cluster.centroid);
        if (
          cluster.indices.length < 4 &&
          clusterDistance <= ENEMY_SQUAD_CLUSTER_RADIUS &&
          clusterDistance < bestDistance
        ) {
          bestCluster = cluster;
          bestDistance = clusterDistance;
        }
      }
    }

    if (!bestCluster) {
      bestCluster = {
        id: `${routeId}-enemy-${clusters.length + 1}`,
        indices: [],
        centroid: nearestBuildingStrongpoint ? { ...nearestBuildingStrongpoint.position } : { ...spawn.anchor },
        strongpointLabel: nearestBuildingStrongpoint?.label ?? null
      };
      clusters.push(bestCluster);
    }

    bestCluster.indices.push(spawnIndex);
    unassignedIndices.delete(spawnIndex);
    const weight = bestCluster.indices.length;
    bestCluster.centroid = {
      x: (bestCluster.centroid.x * (weight - 1) + spawn.anchor.x) / weight,
      y: (bestCluster.centroid.y * (weight - 1) + spawn.anchor.y) / weight
    };
  });

  clusters.forEach((cluster) => {
    const available = [...cluster.indices];
    const supportIndex = takeBestIndex(available, (spawnIndex) => {
      const spawn = plannedSpawns[spawnIndex];
      const postureScore =
        spawn.posture === "hold" ? 2.4 : spawn.posture === "reserve" ? 2.1 : spawn.posture === "patrol" ? 1.2 : 0.6;
      const archetypeScore = spawn.archetypeId === "rifleman" ? 2.8 : spawn.archetypeId === "skirmisher" ? 2 : 0.8;
      const strongpointScore = getSupportStrongpointScore(spawn.anchor, supportStrongpoints);
      return postureScore + archetypeScore + strongpointScore;
    });
    if (supportIndex !== null) {
      assignments[supportIndex] = { squadId: cluster.id, squadRole: "support-gunner" };
      available.splice(available.indexOf(supportIndex), 1);
    }

    const anchorIndex = takeBestIndex(available, (spawnIndex) => {
      const spawn = plannedSpawns[spawnIndex];
      const postureScore = spawn.posture === "hold" ? 3.2 : spawn.posture === "reserve" ? 2.3 : 1;
      const archetypeScore = spawn.archetypeId === "rusher" ? 0.4 : 1.1;
      return postureScore + archetypeScore - distance(spawn.anchor, cluster.centroid) / 180;
    });
    if (anchorIndex !== null) {
      assignments[anchorIndex] = { squadId: cluster.id, squadRole: "anchor-rifle" };
      available.splice(available.indexOf(anchorIndex), 1);
    }

    const probeIndex = takeBestIndex(available, (spawnIndex) => {
      const spawn = plannedSpawns[spawnIndex];
      const postureScore =
        spawn.posture === "sweeper" ? 3.2 : spawn.posture === "patrol" ? 2.5 : spawn.posture === "reserve" ? 1.7 : 1.2;
      const archetypeScore = spawn.archetypeId === "rusher" ? 2.2 : spawn.archetypeId === "skirmisher" ? 1.4 : 1;
      return postureScore + archetypeScore + distance(spawn.position, cluster.centroid) / 220;
    });
    if (probeIndex !== null) {
      assignments[probeIndex] = { squadId: cluster.id, squadRole: "probe-rifle" };
      available.splice(available.indexOf(probeIndex), 1);
    }

    const deepIndex = takeBestIndex(available, (spawnIndex) => {
      const spawn = plannedSpawns[spawnIndex];
      const postureScore = spawn.posture === "reserve" ? 3.4 : spawn.posture === "hold" ? 2.4 : 1;
      const archetypeScore = spawn.archetypeId === "rifleman" ? 1.4 : 1;
      return postureScore + archetypeScore + distance(spawn.position, cluster.centroid) / 200;
    });
    if (deepIndex !== null) {
      assignments[deepIndex] = { squadId: cluster.id, squadRole: "deep-rifle" };
      available.splice(available.indexOf(deepIndex), 1);
    }

    available.forEach((spawnIndex, memberIndex) => {
      assignments[spawnIndex] = {
        squadId: cluster.id,
        squadRole: memberIndex % 2 === 0 ? "probe-rifle" : "deep-rifle"
      };
    });
  });

  return {
    assignments,
    reservedStrongpointsBySquadId
  };
}

function isEnemyBuildingHoldRole(role: EnemySquadRole): boolean {
  return role === "support-gunner" || role === "anchor-rifle" || role === "deep-rifle";
}

interface EnemySquadRead {
  squadId: string;
  aliveCount: number;
  downedCount: number;
  supportGunnerAlive: boolean;
  anchorRifleAlive: boolean;
  deepRifleAliveCount: number;
  probeRifleAliveCount: number;
  crossingDangerReduced: boolean;
  firstThresholdSoftened: boolean;
  secondRoomSoftened: boolean;
}

interface EnemySquadOwnershipRead {
  squadId: string;
  strongpointLabel: string;
  occupationTier: BuildingOccupationTier | null;
  laneLabel: string | null;
  roomClearDepthLabel: string | null;
  compressedCount: number;
  ownershipLabel: string;
  statusLabel: string;
}

function isEnemyAliveForSquadRead(enemy: EnemyState): boolean {
  return enemy.casualtyState !== "downed" && enemy.casualtyState !== "dead";
}

function getEnemySquadRead(state: RaidState, squadId: string): EnemySquadRead | null {
  const squadMembers = state.enemies.filter((enemy) => (enemy.squadId ?? `solo-${enemy.id}`) === squadId);
  if (squadMembers.length === 0) {
    return null;
  }

  const aliveMembers = squadMembers.filter(isEnemyAliveForSquadRead);
  return {
    squadId,
    aliveCount: aliveMembers.length,
    downedCount: squadMembers.filter((enemy) => enemy.casualtyState === "downed").length,
    supportGunnerAlive: aliveMembers.some((enemy) => enemy.squadRole === "support-gunner"),
    anchorRifleAlive: aliveMembers.some((enemy) => enemy.squadRole === "anchor-rifle"),
    deepRifleAliveCount: aliveMembers.filter((enemy) => enemy.squadRole === "deep-rifle").length,
    probeRifleAliveCount: aliveMembers.filter((enemy) => enemy.squadRole === "probe-rifle").length,
    crossingDangerReduced: !aliveMembers.some((enemy) => enemy.squadRole === "support-gunner"),
    firstThresholdSoftened: !aliveMembers.some((enemy) => enemy.squadRole === "anchor-rifle"),
    secondRoomSoftened: !aliveMembers.some((enemy) => enemy.squadRole === "deep-rifle")
  };
}

function getEnemySquadOwnershipRead(state: RaidState, squadId: string): EnemySquadOwnershipRead | null {
  const squadMembers = state.enemies.filter((enemy) => (enemy.squadId ?? `solo-${enemy.id}`) === squadId);
  if (squadMembers.length === 0) {
    return null;
  }

  const aliveMembers = squadMembers.filter(isEnemyAliveForSquadRead);
  if (aliveMembers.length === 0) {
    return null;
  }

  const primaryMember =
    aliveMembers.find((enemy) => enemy.squadRole === "support-gunner" && enemy.supportStrongpointLabel) ??
    aliveMembers.find((enemy) => enemy.supportStrongpointLabel) ??
    null;
  if (!primaryMember?.supportStrongpointLabel) {
    return null;
  }

  const squadRead = getEnemySquadRead(state, squadId);
  if (squadRead === null) {
    return null;
  }

  const compressedCount = aliveMembers.filter((enemy) => enemy.compressionState !== "idle").length;
  const strongpointLabel = primaryMember.supportStrongpointLabel;
  const laneLabel = primaryMember.supportLaneLabel;
  const roomClearDepthLabel =
    /cellar|lift|upper|tower|annex/i.test(strongpointLabel)
      ? "Cellar plus upper chain"
      : /bunker|mouth|gate|vault/i.test(strongpointLabel)
        ? "Bunker mouth plus rear pocket"
        : /relay|office|room/i.test(strongpointLabel)
          ? "First room plus back room"
          : /house|dish|shed/i.test(strongpointLabel)
            ? "One-room hold"
            : "Lane-owned pocket";
  const compactStrongpoint =
    laneLabel && !strongpointLabel.toLowerCase().includes(laneLabel.toLowerCase())
      ? `${strongpointLabel} ${laneLabel}`
      : strongpointLabel;
  const ownershipLabel =
    compressedCount >= 2 && !squadRead.secondRoomSoftened
      ? `${strongpointLabel} compressed deeper`
      : squadRead.crossingDangerReduced && !squadRead.secondRoomSoftened && roomClearDepthLabel !== "Lane-owned pocket"
        ? `${strongpointLabel} cracked, back room still active`
        : !squadRead.crossingDangerReduced
          ? `PKM owns ${compactStrongpoint}`
          : `${strongpointLabel} still live`;
  const statusLabel =
    compressedCount >= 2
      ? `Cellar squad compressed deeper x${compressedCount}`
      : squadRead.crossingDangerReduced && !squadRead.secondRoomSoftened && roomClearDepthLabel !== "Lane-owned pocket"
        ? `${strongpointLabel} cracked | back room still active`
        : !squadRead.crossingDangerReduced
          ? `${compactStrongpoint} still owns the lane`
          : `${strongpointLabel} still active`;

  return {
    squadId,
    strongpointLabel,
    occupationTier: primaryMember.supportStrongpointTier,
    laneLabel,
    roomClearDepthLabel,
    compressedCount,
    ownershipLabel,
    statusLabel
  };
}

function getFocusedEnemySquadRead(state: RaidState, position: Vec2, radius = 220): EnemySquadRead | null {
  const nearbyEnemies = state.enemies.filter((enemy) => distance(enemy.position, position) <= radius);
  if (nearbyEnemies.length === 0) {
    return null;
  }

  const squadScores = nearbyEnemies.reduce((scores, enemy) => {
    const squadId = enemy.squadId ?? `solo-${enemy.id}`;
    const enemyDistance = distance(enemy.position, position);
    const existing = scores.get(squadId) ?? {
      count: 0,
      totalDistance: 0,
      nearestDistance: Number.POSITIVE_INFINITY,
      holdRoleCount: 0
    };
    existing.count += 1;
    existing.totalDistance += enemyDistance;
    existing.nearestDistance = Math.min(existing.nearestDistance, enemyDistance);
    if (isEnemyBuildingHoldRole(enemy.squadRole)) {
      existing.holdRoleCount += 1;
    }
    scores.set(squadId, existing);
    return scores;
  }, new Map<string, { count: number; totalDistance: number; nearestDistance: number; holdRoleCount: number }>());

  const rankedSquads = [...squadScores.entries()]
    .map(([squadId, score]) => ({
      squadId,
      score,
      read: getEnemySquadRead(state, squadId)
    }))
    .filter((entry): entry is { squadId: string; score: { count: number; totalDistance: number; nearestDistance: number; holdRoleCount: number }; read: EnemySquadRead } => entry.read !== null);
  const degradedSquads = rankedSquads.filter(
    (entry) => entry.read.crossingDangerReduced || entry.read.firstThresholdSoftened || entry.read.secondRoomSoftened
  );
  const focusedSquadId =
    (degradedSquads.length > 0 ? degradedSquads : rankedSquads)
      .sort((left, right) => {
        if (left.score.nearestDistance !== right.score.nearestDistance) {
          return left.score.nearestDistance - right.score.nearestDistance;
        }
        if (right.score.holdRoleCount !== left.score.holdRoleCount) {
          return right.score.holdRoleCount - left.score.holdRoleCount;
        }
        if (right.score.count !== left.score.count) {
          return right.score.count - left.score.count;
        }
        return left.score.totalDistance / left.score.count - right.score.totalDistance / right.score.count;
      })[0]?.squadId ?? (nearbyEnemies[0].squadId ?? `solo-${nearbyEnemies[0].id}`);
  return getEnemySquadRead(state, focusedSquadId);
}

function getFocusedEnemySquadOwnershipRead(state: RaidState, position: Vec2, radius = 220): EnemySquadOwnershipRead | null {
  const focusedRead = getFocusedEnemySquadRead(state, position, radius);
  return focusedRead ? getEnemySquadOwnershipRead(state, focusedRead.squadId) : null;
}

function getNearestDegradedEnemySquadRead(state: RaidState, position: Vec2): EnemySquadRead | null {
  const squadCandidates = [...new Set(state.enemies.map((enemy) => enemy.squadId ?? `solo-${enemy.id}`))]
    .map((squadId) => {
      const read = getEnemySquadRead(state, squadId);
      if (read === null || (!read.crossingDangerReduced && !read.firstThresholdSoftened && !read.secondRoomSoftened)) {
        return null;
      }
      const aliveMembers = state.enemies.filter(
        (enemy) => (enemy.squadId ?? `solo-${enemy.id}`) === squadId && isEnemyAliveForSquadRead(enemy)
      );
      if (aliveMembers.length === 0) {
        return null;
      }
      const nearestDistance = aliveMembers.reduce(
        (best, enemy) => Math.min(best, distance(enemy.position, position)),
        Number.POSITIVE_INFINITY
      );
      return { read, nearestDistance };
    })
    .filter(
      (entry): entry is { read: EnemySquadRead; nearestDistance: number } => entry !== null && Number.isFinite(entry.nearestDistance)
    )
    .sort((left, right) => left.nearestDistance - right.nearestDistance);
  return squadCandidates[0]?.read ?? null;
}

function getEnemyHoldAnchorRadius(openingPosture: EnemyOpeningPosture, squadRole: EnemySquadRole): number {
  if (squadRole === "support-gunner") {
    return openingPosture === "reserve" ? 88 : 104;
  }
  if (squadRole === "deep-rifle") {
    return openingPosture === "reserve" ? 82 : 96;
  }
  if (squadRole === "anchor-rifle") {
    return openingPosture === "reserve" ? 108 : 124;
  }
  return openingPosture === "hold" || openingPosture === "reserve" ? 144 : 96;
}

function getEnemyCompressionDuration(squadRole: EnemySquadRole): number {
  if (squadRole === "deep-rifle") {
    return 3.4;
  }
  if (squadRole === "support-gunner") {
    return 2.8;
  }
  if (squadRole === "anchor-rifle") {
    return 2.2;
  }
  return 1.2;
}

function getEnemyCompressionOffset(squadRole: EnemySquadRole): number {
  if (squadRole === "deep-rifle") {
    return 52;
  }
  if (squadRole === "support-gunner") {
    return 32;
  }
  if (squadRole === "anchor-rifle") {
    return 20;
  }
  return 12;
}

function getEnemyCompressionAnchor(anchor: Vec2, targetPosition: Vec2, squadRole: EnemySquadRole): Vec2 {
  const awayFromTarget = subtract(anchor, targetPosition);
  if (length(awayFromTarget) <= 0.001) {
    return anchor;
  }
  return add(anchor, multiply(normalize(awayFromTarget), getEnemyCompressionOffset(squadRole)));
}

function getFriendlyCombatantAnchor(
  player: PlayerState,
  slotIndex: number,
  totalCount: number
): Vec2 {
  const facing = length(player.facing) > 0.001 ? normalize(player.facing) : { x: 1, y: 0 };
  const lateral = { x: -facing.y, y: facing.x };
  const slotOffset = slotIndex - (totalCount - 1) / 2;
  const behindDistance = totalCount === 1 ? 46 : slotIndex === 1 && totalCount === 3 ? 72 : 56;
  return {
    x: clamp(player.position.x - facing.x * behindDistance + lateral.x * slotOffset * 34, 48, WORLD_WIDTH - 48),
    y: clamp(player.position.y - facing.y * behindDistance + lateral.y * slotOffset * 34, 48, WORLD_HEIGHT - 48)
  };
}

function getRussianCampNpcName(squadMate: SquadMateState): string {
  if (isUnifiedSquadRosterId(squadMate.id)) {
    return squadMate.name;
  }
  if (squadMate.combatProfileId === "rusher") {
    return "Russian Assaultman";
  }
  if (squadMate.weaponId === "pkm" || squadMate.role.toLowerCase().includes("support")) {
    return "Russian Support Gunner";
  }
  if (squadMate.role.toLowerCase().includes("medic")) {
    return "Russian Field Medic";
  }
  if (squadMate.combatProfileId === "skirmisher") {
    return "Russian Skirmisher";
  }
  return "Russian Rifleman";
}

function isUnifiedSquadRosterId(id: string): boolean {
  return id.startsWith("unified-");
}

function getTownWarSoldierIdFromUnifiedRosterId(rosterId: string): string {
  return rosterId.replace(/^unified-/, "");
}

function getUnifiedSquadRosterId(unifiedSoldierId: string): string {
  return isUnifiedSquadRosterId(unifiedSoldierId) ? unifiedSoldierId : `unified-${unifiedSoldierId}`;
}

function getUnifiedSoldierReadiness(unifiedSoldier: TownWarUnifiedSoldierSnapshot): number {
  const healthRatio = unifiedSoldier.combat.health.current / Math.max(1, unifiedSoldier.combat.health.max);
  const needPenalty =
    unifiedSoldier.colonist.currentNeed === "tired"
      ? 0.12
      : unifiedSoldier.colonist.currentNeed === "hungry" || unifiedSoldier.colonist.currentNeed === "shaken"
        ? 0.08
        : unifiedSoldier.colonist.currentNeed === "low-ammo"
          ? 0.06
          : 0;
  return clamp(0.46 + healthRatio * 0.38 + unifiedSoldier.colonist.skills.nerve / 80 - needPenalty, 0.28, 0.92);
}

function createUnifiedSoldierRosterMate(
  unifiedSoldier: TownWarUnifiedSoldierSnapshot,
  status: SquadRosterState["status"]
): SquadRosterState {
  return {
    id: unifiedSoldier.id,
    name: unifiedSoldier.displayName,
    role: `${unifiedSoldier.role} / camp soldier`,
    voiceTag: "Russian",
    voiceSignature: `${unifiedSoldier.colonist.identitySummary.bestSkills} // ${unifiedSoldier.colonist.currentNeed}`,
    weaponId: unifiedSoldier.combat.weaponId,
    status,
    readiness: getUnifiedSoldierReadiness(unifiedSoldier),
    fatigue: unifiedSoldier.colonist.needs.fatigue,
    raids: unifiedSoldier.colonist.dramaArc.combatNerve > 0.7 ? 1 : 0,
    extracts: 0,
    survivedRaids: 0,
    woundedRaids: unifiedSoldier.colonist.currentNeed === "wounded" ? 1 : 0,
    criticalRaids: 0,
    reserveDays: 0,
    rookie: false,
    bodyRecovered: true,
    lastAssignment: "Assigned from camp roster through unified soldier bridge",
    lastCallout: unifiedSoldier.readable,
    lastOutcome: "Camp soldier attached to the boys net; still keeps colonist priorities when returned to camp.",
    casualtyRecord: null,
    memorialNote: null,
    familyNotified: false,
    wakeHeld: false,
    dialogueMemories: []
  };
}

function getUnifiedSoldierLiveCombatantSource(unifiedSoldier: TownWarUnifiedSoldierSnapshot | null): LiveSquadCombatantSource | null {
  return unifiedSoldier
    ? {
        healthCurrent: unifiedSoldier.combat.health.current,
        healthMax: unifiedSoldier.combat.health.max,
        ammoInMag: unifiedSoldier.combat.ammo.inMag,
        reserveAmmo: unifiedSoldier.combat.ammo.reserve
      }
    : null;
}

function getTownWarSoldierCombatArchetype(soldier: TownWarSoldierState): EnemyArchetypeId {
  if (soldier.role === "builder" || soldier.role === "medic") {
    return "skirmisher";
  }
  if (soldier.role === "suppressor" || soldier.role === "defender") {
    return "rifleman";
  }
  return "rusher";
}

function getTownWarSoldierCombatWeapon(soldier: TownWarSoldierState): WeaponId {
  if (soldier.role === "suppressor") {
    return "pkm";
  }
  if (soldier.role === "defender") {
    return "short-mosin";
  }
  return "worn-ak";
}

function getTownWarSoldierRaidLoadout(soldier: TownWarSoldierState): TownWarRaidLoadout {
  return {
    archetypeId: getTownWarSoldierCombatArchetype(soldier),
    weaponId: getTownWarSoldierCombatWeapon(soldier)
  };
}

function canProjectTownWarSoldierIntoRaid(soldier: TownWarSoldierState): boolean {
  return (
    soldier.faction === TOWN_WAR_PLAYER_FACTION &&
    soldier.health.current > 0 &&
    soldier.squadBridge.status !== "assigned" &&
    (soldier.task.kind !== "hold" || soldier.role === "defender" || soldier.role === "rifleman" || soldier.role === "suppressor")
  );
}

function getTownWarSoldierRaidGrenadeStock(soldier: TownWarSoldierState): number {
  return soldier.role === "rifleman" || soldier.role === "defender" ? 1 : 0;
}

function getTownWarSoldierRaidAwareness(soldier: TownWarSoldierState): FriendlyCombatantState["awareness"] {
  return soldier.task.kind === "suppress" || soldier.task.kind === "attack" ? "engaged" : "patrol";
}

function getTownWarSoldierRaidHealth(soldier: TownWarSoldierState, archetype: EnemyArchetypeDefinition): { current: number; max: number } {
  return {
    current: Math.min(archetype.health, soldier.health.current),
    max: Math.max(archetype.health, soldier.health.max)
  };
}

function scoreTownWarSoldierRaidProjection(soldier: TownWarSoldierState): number {
  const taskWeight =
    soldier.task.kind === "suppress"
      ? 130
      : soldier.task.kind === "defend" || soldier.task.kind === "attack"
        ? 115
        : soldier.task.kind === "build" || soldier.task.kind === "heal" || soldier.task.kind === "resupply"
          ? 68
          : 45;
  const roleWeight =
    soldier.role === "suppressor"
      ? 36
      : soldier.role === "rifleman" || soldier.role === "defender"
        ? 28
        : soldier.role === "medic" || soldier.role === "builder"
          ? 18
          : 10;
  const ammoWeight = soldier.ammo.inMag + soldier.ammo.reserve > 0 ? 16 : -30;
  const healthRatio = soldier.health.current / Math.max(1, soldier.health.max);
  return taskWeight + roleWeight + ammoWeight + healthRatio * 24 - soldier.needs.fatigue * 18;
}

const createFriendlyCombatant = (
  id: number,
  squadMate: SquadMateState,
  player: PlayerState,
  slotIndex: number,
  totalCount: number
): FriendlyCombatantState => {
  const archetype = SCAV_ARCHETYPES[squadMate.combatProfileId];
  const weaponId = squadMate.weaponId === "none" ? getArchetypeWeaponId(squadMate.combatProfileId) : squadMate.weaponId;
  const combatProfile = getSharedWeaponCombatProfile(weaponId, squadMate.combatProfileId);
  const position = getFriendlyCombatantAnchor(player, slotIndex, totalCount);

  return {
    id,
    ownerKind: "squadmate",
    ownerId: squadMate.id,
    squadMateId: squadMate.id,
    name: getRussianCampNpcName(squadMate),
    voiceTag: "Russian",
    archetypeId: squadMate.combatProfileId,
    weaponId,
    position,
    velocity: { x: 0, y: 0 },
    facing: length(player.facing) > 0.001 ? normalize(player.facing) : { x: 1, y: 0 },
    health: archetype.health,
    maxHealth: archetype.health,
    radius: squadMate.combatProfileId === "rusher" ? 17 : 16,
    cooldown: combatProfile.fireIntervalMin + Math.random() * Math.max(0.05, combatProfile.fireIntervalMax - combatProfile.fireIntervalMin),
    grenadeStock: squadMate.weaponId === "shotgun" ? 0 : 1,
    grenadeCooldown: 0,
    ammoInMag: WEAPONS[weaponId].magazineSize,
    reserveAmmo: Math.max(WEAPONS[weaponId].magazineSize, Math.round(WEAPONS[weaponId].reserveAmmo * 0.72)),
    reloadTimer: 0,
    dryFireTimer: 0,
    resupplyTimer: 0,
    anchor: { ...position },
    alert: false,
    awareness: "patrol",
    investigateTarget: null,
    investigateTimer: 0,
    navigationStallTime: 0,
    navigationRecoveryIndex: 0,
    lastNavigationSample: { ...position },
    navigationCommittedTarget: null,
    pressureType: null,
    pressureTimer: 0,
    blindFireTimer: 0,
    panicTimer: 0,
    armorBrokenTimer: 0,
    armorFlash: 0,
    fleshFlash: 0,
    casualtyState: "healthy",
    woundSeverity: "none",
    bleedoutTimer: 0,
    stabilized: false
  };
};

const createFriendlyCombatants = (
  startingId: number,
  squadMates: ReadonlyArray<SquadMateState>,
  player: PlayerState
): FriendlyCombatantState[] =>
  squadMates
    .filter((mate) => mate.weaponId !== "none")
    .map((mate, index, armedMates) => createFriendlyCombatant(startingId + index, mate, player, index, armedMates.length));

function getWoundSeverityFromHealth(health: number, maxHealth: number): WoundSeverity {
  const percent = maxHealth > 0 ? health / maxHealth : 0;
  if (percent <= 0) {
    return "severe";
  }
  if (percent <= 0.3) {
    return "severe";
  }
  if (percent <= 0.6) {
    return "moderate";
  }
  if (percent <= 0.82) {
    return "light";
  }
  return "none";
}

function getWoundMoveMultiplier(severity: WoundSeverity): number {
  if (severity === "severe") {
    return 0.58;
  }
  if (severity === "moderate") {
    return 0.78;
  }
  if (severity === "light") {
    return 0.92;
  }
  return 1;
}

function getWoundSpreadMultiplier(severity: WoundSeverity): number {
  if (severity === "severe") {
    return 1.45;
  }
  if (severity === "moderate") {
    return 1.22;
  }
  if (severity === "light") {
    return 1.08;
  }
  return 1;
}

function getWoundFireIntervalMultiplier(severity: WoundSeverity): number {
  if (severity === "severe") {
    return 1.38;
  }
  if (severity === "moderate") {
    return 1.18;
  }
  if (severity === "light") {
    return 1.06;
  }
  return 1;
}

function getWoundEngageRangeMultiplier(severity: WoundSeverity): number {
  if (severity === "severe") {
    return 0.76;
  }
  if (severity === "moderate") {
    return 0.88;
  }
  if (severity === "light") {
    return 0.96;
  }
  return 1;
}

function getCombatantDownThreshold(maxHealth: number, target: "player" | "squadmate" | "enemy"): number {
  if (target === "player") {
    return Math.max(PLAYER_DOWN_THRESHOLD_MIN, Math.round(maxHealth * PLAYER_DOWN_THRESHOLD_PERCENT));
  }
  if (target === "squadmate") {
    return Math.max(SQUAD_DOWN_THRESHOLD_MIN, Math.round(maxHealth * SQUAD_DOWN_THRESHOLD_PERCENT));
  }
  return Math.max(ENEMY_DOWN_THRESHOLD_MIN, Math.round(maxHealth * ENEMY_DOWN_THRESHOLD_PERCENT));
}

function getTapeIdForEnemy(id: number, archetypeId: EnemyArchetypeId): EnemyTapeId {
  const cycle = id % 6;

  if (archetypeId === "rifleman") {
    return cycle >= 4 ? "green" : "blue";
  }

  if (archetypeId === "skirmisher") {
    return cycle >= 4 ? "yellow" : "green";
  }

  return cycle >= 4 ? "green" : "yellow";
}

const createIntelSites = (positions: ReadonlyArray<Vec2>): IntelState[] =>
  positions.map((position, index) => ({
    id: index + 1,
    position: { ...position },
    secured: false,
    alarmTriggered: false
  }));

const createSupplyCaches = (spawns: ReadonlyArray<SupplyCacheSpawn>): SupplyCacheState[] =>
  spawns.map((spawn) => ({
    id: spawn.id,
    position: { ...spawn.position },
    kind: spawn.kind,
    label: spawn.label,
    demandCategory: spawn.demandCategory ?? (spawn.kind === "medical" ? "medical" : spawn.kind === "ammo" ? "munitions" : "hardware"),
    searched: false,
    searchDuration: spawn.searchDuration ?? CACHE_SEARCH_SECONDS,
    rewardCredits:
      spawn.rewardCredits ??
      (spawn.kind === "locker"
        ? 140 + Math.floor(Math.random() * 61)
        : spawn.kind === "medical"
          ? 70 + Math.floor(Math.random() * 41)
          : 85 + Math.floor(Math.random() * 51)),
    medkitReward: spawn.medkitReward ?? (spawn.kind === "medical" ? 1 : 0),
    ammoReward:
      spawn.ammoReward ?? (spawn.kind === "ammo" ? 20 + Math.floor(Math.random() * 13) : spawn.kind === "locker" ? 10 + Math.floor(Math.random() * 11) : 0),
    resupplyCrate: false,
    resupplyAmmoStock: 0,
    resupplyAmmoStockMax: 0,
    resupplyThreatTimer: 0,
    stashReward:
      spawn.stashReward ??
      (spawn.kind === "medical"
        ? { medkits: 1, ammoPacks: 0 }
        : spawn.kind === "ammo"
          ? { medkits: 0, ammoPacks: 1 }
          : Math.random() > 0.5
            ? { medkits: 1, ammoPacks: 0 }
            : { medkits: 0, ammoPacks: 1 }),
    opportunityId: spawn.opportunityId ?? null,
    opportunitySummary: spawn.opportunitySummary ?? null,
    frontlineDrop: false,
    frontlineDropSourceLabel: null
  }));

